window.QUESTIONS = [{"id":"23","category_id":"2","question":"What does this sign mean?","img":"a_jrDYK.png","options":["Trams emerging from left.","Tram lane on left.","No parking inside the white line.","Bus and tram lane on left."],"answer":["option_2"],"explanation":"This sign tells you there is a tram lane on the left. Be aware that there might be pedestrians in the area and crossing the road."},{"id":"24","category_id":"2","question":"What does this sign mean?","img":"a_BtRUM.png","options":["Radio transmission mast ahead.","Overhead electric cables.","Sharp corners ahead.","Crosswinds ahead."],"answer":["option_2"],"explanation":"This sign gives advance warning of electric cables overhead. Drivers with a high load should be particularly careful."},{"id":"25","category_id":"2","question":"Who can use a signed cycle track accompanied by a continuous white line on the left-hand side?","img":"","options":["Cyclists and users of motorised wheelchairs.","Drivers when overtaking a vehicle turning right.","Cyclists and motorcyclists.","Drivers, when it is not being used by a cyclist."],"answer":["option_1"],"explanation":"A cycle track is for the use of cyclists and motorised wheelchairs only. No other vehicles may cross into or over a mandatory cycle track unless this is necessary in order to leave or enter a side road or a property adjacent to the cycle track."},{"id":"26","category_id":"2","question":"What lights indicate a zebra crossing?","img":"","options":["Flashing amber beacons.","Flashing red beacons.","Continuously lit amber beacons.","Continuously lit red beacons."],"answer":["option_1"],"explanation":"A zebra crossing is indicated by amber flashing beacons on poles and black and white stripes on the road. You must stop for pedestrians on the crossing and for those about to cross."},{"id":"27","category_id":"2","question":"What do temporary traffic lights at road works mean?","img":"","options":["A driver must comply with the lights at all times.","A driver must comply with the lights when workers are on site only.","A driver need not comply if a convoy of traffic is going in the same direction.","A driver need only comply when there is oncoming traffic."],"answer":["option_1"],"explanation":"You must comply with any temporary traffic lights used to control vehicle movements at or near road works. It is an offence not to obey these lights."},{"id":"28","category_id":"2","question":"What do these signs together mean?","img":"a_pv9Pq.png","options":["Parking not allowed during times shown.","Access for buses and taxis only during times shown.","Pedestrianised street ahead - traffic not allowed except during times shown.","Clearway ahead - no stopping or parking during times shown."],"answer":["option_3"],"explanation":"When posted together these signs tells you that there is a pedestrianised street ahead and that traffic is not allowed to enter except during the times stated on the information plate."},{"id":"29","category_id":"2","question":"What does this sign mean?","img":"a_rOcGJ.png","options":["Maximum permitted weight is 3 tonnes.","Minimum permitted weight is 3 tonnes.","3-axled vehicles are not permitted.","Only 3-axled vehicles are permitted."],"answer":["option_1"],"explanation":"This sign tells you that you must not enter this area if your vehicle is over 3 tonnes or 3,000 kg."},{"id":"30","category_id":"2","question":"What does this sign mean?","img":"a_an4DE.png","options":["Passing other traffic that exceeds the weight shown is not allowed.","Parking in loading area is not allowed.","Parking of vehicles exceeding the weight shown is not allowed.","Parking of vehicles under the weight shown is not allowed."],"answer":["option_3"],"explanation":"This sign tells you that you must not park in this area if your vehicle is over the weight limit indicated."},{"id":"31","category_id":"2","question":"What does this sign mean?","img":"a_ajgZN.png","options":["No overtaking.","No stopping/parking on the right.","End of dual carriageway.","Double parking not allowed."],"answer":["option_1"],"explanation":"This sign tells you that overtaking is prohibited. These signs are usually found in places where overtaking may be dangerous, such as in areas with reduced visibility."},{"id":"32","category_id":"2","question":"What does this sign mean?","img":"a_ZNVdx.png","options":["Only cyclists and buses are allowed to use the lane during the times indicated.","Only buses, cyclists and taxis are allowed to use the lane outside the hours indicated.","Only buses and cyclists may park during the times indicated.","Only buses, cyclists and taxis are allowed to use the lane ahead during the hours indicated."],"answer":["option_4"],"explanation":"This sign tells you there is a with-flow nearside bus lane ahead on the left – that is, one where the buses move in the same direction as the traffic to their right. The information plate tells the times when the bus lane is in operation. Only buses, taxis and cyclists may use the bus lane during those hours."},{"id":"33","category_id":"2","question":"What does this sign mean?","img":"a_qjzzd.png","options":["Only double-decker buses and cyclists may use lane.","Cyclists and buses must turn left.","With-flow bus and cycle lane ahead on left.","Only buses and cyclists may park."],"answer":["option_3"],"explanation":"This sign tells you there is a with-flow nearside bus lane ahead to the left. Only buses, taxis and cyclists may use the bus lane during the stated operational hours."},{"id":"34","category_id":"2","question":"What does this sign mean?","img":"a_TNTeM.png","options":["Cyclists must give way to buses ahead.","Buses must give way to other traffic ahead.","Buses must give way to cyclists ahead.","Bus and cycle lane ahead on right."],"answer":["option_4"],"explanation":"This sign tells you that there is an offside bus lane ahead on the right. Only buses, taxis and cyclists may use the bus lane during the stated operational hours."},{"id":"35","category_id":"2","question":"What does this sign mean?","img":"a_0P6qm.png","options":["Buses may block the driver’s view of cyclists.","With-flow bus lane on the left.","Contra-flow bus lane ahead.","With-flow bus lane on the right."],"answer":["option_4"],"explanation":"This sign indicates a with-flow offside bus lane on the right. Only buses, taxis and cyclists may use the bus lane during the stated operational hours."},{"id":"36","category_id":"2","question":"What does this sign mean?","img":"a_Xig8T.png","options":["Cycle track may be crossed by buses.","With-flow bus lane to right.","Contra-flow bus lane on the right.","Buses emerging from right."],"answer":["option_3"],"explanation":"This sign tells you that you must drive on the left and not use the contra-flow bus lane day or night. A contraflow bus lane is one where the buses are going in the opposite direction."},{"id":"37","category_id":"2","question":"What does this sign mean?","img":"a_xArHX.png","options":["Contra-flow bus lane.","With-flow bus lane.","Double-decker buses only.","Two-way traffic system."],"answer":["option_1"],"explanation":"This sign tells you that you must drive on the left and not use the contra-flow bus lane day or night. A contra-flow bus lane is one where the buses are going in the opposite direction."},{"id":"38","category_id":"2","question":"What does this sign mean?","img":"a_UDn6I.png","options":["Tram lane on left.","Tram lane on right.","Parking only inside the white line.","With-flow bus lane ahead."],"answer":["option_2"],"explanation":"This sign tells you there is an offside tram lane on the right. Drivers should also be aware that there might be pedestrians in the area."},{"id":"39","category_id":"2","question":"What does this sign mean?","img":"a_dDbCa.png","options":["Y-junction where main road bears to the left.","Y-junction where heavy vehicles must go left.","Y-junction where vehicles must go left.","Y-junction where main road bears to the right."],"answer":["option_1"],"explanation":"This sign gives advance warning of a Y-junction with a minor road ahead. The wider arm of the Y indicates the course of the main road."},{"id":"40","category_id":"2","question":"What does this sign mean?","img":"a_en1D1.png","options":["Junction ahead with dual carriageway.","Y-junction ahead with roads of lesser importance.","Y-junction ahead with roads of equal importance.","Minor road ahead."],"answer":["option_3"],"explanation":"This sign gives advance warning of a Y-junction ahead with roads of equal importance. Approach such a junction with caution and be prepared to react to any changes in the traffic situation."},{"id":"41","category_id":"2","question":"What does this sign mean?","img":"a_8365z.png","options":["T-junction ahead with roads of major importance.","Crossroads with major road ahead.","Crossroads with dual carriageway ahead.","Road passing under a bridge ahead."],"answer":["option_2"],"explanation":"This sign gives advance warning of a crossroads junction with a major road ahead. Be prepared to stop."},{"id":"42","category_id":"2","question":"What does this sign mean?","img":"a_iZQtQ.png","options":["T-junction ahead with a road of minor importance.","T-junction ahead with a road of major importance.","Cul-de-sac to the right.","Cul-de-sac to the left and right."],"answer":["option_2"],"explanation":"This sign gives advance warning of a T-junction ahead with a major road. Be prepared to yield or stop as necessary."},{"id":"43","category_id":"2","question":"What does this sign mean?","img":"a_qcUrO.png","options":["T-junction with crossroads ahead.","Unguarded level crossing ahead.","Level crossing ahead guarded by gates.","Crossroads with dual carriageway ahead."],"answer":["option_4"],"explanation":"This sign gives advance warning of a crossroads junction at a dual carriageway ahead. Drivers need to be observant, taking extra care for traffic coming from each direction. Yield and/or stop as appropriate."},{"id":"44","category_id":"2","question":"What does this sign mean?","img":"a_Zz2dP.png","options":["Guarded level crossing ahead.","Unguarded level crossing ahead.","T-junction with dual carriageway ahead.","Low bridge ahead."],"answer":["option_3"],"explanation":"This sign gives advance warning of a T-junction at a dual carriageway ahead. Drivers need to be observant, taking extra care for traffic coming from each direction. Yield and/or stop as appropriate."},{"id":"45","category_id":"2","question":"What does this sign mean?","img":"a_6LVcJ.png","options":["Traffic merging from the right.","End of dual carriageway ahead.","Traffic merging from the left.","Traffic from the left has priority."],"answer":["option_3"],"explanation":"This sign gives advance warning of traffic merging from the left. You should expect vehicles to join from the left. You may need to slow down, allowing them to merge safely."},{"id":"46","category_id":"2","question":"What does this sign mean?","img":"a_2gbzX.png","options":["Traffic merging/diverging ahead.","Road narrows briefly ahead.","Yield to merging/diverging traffic ahead.","Diversion at junction ahead."],"answer":["option_1"],"explanation":"This sign gives advance warning of roads both merging (entering onto the main road) and diverging (exiting the main road). Drivers should be prepared for traffic changing speed and direction as vehicles enter or exit at the junctions on the left ahead."},{"id":"47","category_id":"2","question":"What does this sign mean?","img":"a_YH9gd.png","options":["Dangerous corner ahead.","One-way street ahead.","Junction to the left.","Dangerous bend ahead."],"answer":["option_1"],"explanation":"This sign gives advance warning of a dangerous corner to the left. You may need to slow down and react to any changes in the traffic situation ahead."},{"id":"48","category_id":"2","question":"What does this sign mean?","img":"a_HAAZ1.png","options":["Sharp change of direction to the right.","Series of speed ramps ahead.","Road closed - drivers must turn back.","Sharp change of direction to the left."],"answer":["option_1"],"explanation":"This sign gives advance warning of a sharp change of direction to the right. You should slow down as you approach the hazard."},{"id":"49","category_id":"2","question":"What does this sign mean?","img":"a_wJbaI.png","options":["Road narrows on the left.","Merging traffic from the left.","End of dual carriageway.","The driver must overtake on the right only."],"answer":["option_1"],"explanation":"This sign gives advance warning that the road narrows on the left ahead. You should show caution and prepare to adjust your road position."},{"id":"50","category_id":"2","question":"What does this sign mean?","img":"a_X5Avh.png","options":["Tramline ahead.","Overtake only on the left ahead.","Road divides ahead.","Railway tunnel ahead."],"answer":["option_3"],"explanation":"This sign gives advance warning that the road divides ahead. You should prepare to move to the left."},{"id":"51","category_id":"2","question":"What does this sign mean?","img":"a_zMcPY.png","options":["Steep descent ahead.","Steep ascent ahead.","River or unprotected quay ahead.","Uneven road surface ahead."],"answer":["option_1"],"explanation":"This sign gives advance warning of a steep descent/downward slope ahead. You should react accordingly by adjusting speed and selecting the appropriate gear."},{"id":"52","category_id":"2","question":"What does this sign mean?","img":"a_PDdg9.png","options":["Low bridge up ahead.","Restricted road width ahead.","Restricted weight limit for road segment indicated.","Road narrows ahead - maximum length of vehicle is indicated."],"answer":["option_1"],"explanation":"This sign gives advance warning that you are approaching a low bridge, with restricted headroom as shown on the sign."},{"id":"53","category_id":"2","question":"What does this sign mean?","img":"a_YBcUP.png","options":["Railway bridge ahead.","Level crossing ahead unprotected by lights and barriers.","Level crossing ahead protected by lights and barriers.","Railway station ahead."],"answer":["option_3"],"explanation":"This sign gives advance warning of a railway level crossing ahead protected by lights and barriers. The crossing may also have an audible warning alarm. You should be prepared to stop."},{"id":"54","category_id":"2","question":"What does this sign mean?","img":"a_dx4PB.png","options":["Road divides ahead - pass on the left or right.","Road damaged ahead.","Road flooded ahead.","Sharp depression or dip ahead."],"answer":["option_4"],"explanation":"This sign gives advance warning of a dip or depression in the road ahead which may be hidden and could obscure your view of oncoming traffic. You should reduce your speed accordingly and be aware that overtaking is dangerous in these areas."},{"id":"55","category_id":"2","question":"What does this sign mean?","img":"a_6IROF.png","options":["Series of rumble strips ahead.","Road works ahead.","Series of bumps or hollows ahead.","Steep hills ahead."],"answer":["option_3"],"explanation":"This sign gives advance warning of a series of bumps or hollows ahead. Be prepared to reduce your speed as necessary."},{"id":"56","category_id":"2","question":"What does this sign mean?","img":"a_tt5JO.png","options":["Slippery road ahead.","Road narrows from right.","Steep hill ahead.","Series of bends ahead."],"answer":["option_1"],"explanation":"This sign gives advance warning of the potential danger of slippery road surfaces ahead."},{"id":"57","category_id":"2","question":"What does this sign mean?","img":"a_ZJTtY.png","options":["School children crossing ahead.","Traffic signals ahead.","Railway level crossing ahead.","Stop at zebra crossing."],"answer":["option_2"],"explanation":"This sign gives advance warning of a traffic light controlled junction ahead. This sign is generally found in areas where the lights may not be visible to drivers in good time – for example, following a bend in the road."},{"id":"58","category_id":"2","question":"What does this sign mean?","img":"a_XcFSl.png","options":["Picnic area ahead.","School ahead.","Children’s play area ahead.","Pedestrian crossing ahead."],"answer":["option_2"],"explanation":"This sign gives advance warning of a school ahead. You should adjust your speed and react accordingly as there may be children in the area."},{"id":"59","category_id":"2","question":"What does this sign mean?","img":"a_j5Nib.png","options":["Golf course ahead.","Falling rocks ahead.","Crosswinds ahead.","Airport ahead."],"answer":["option_3"],"explanation":"This sign gives advance warning that there may be crosswinds ahead. Crosswinds can affect the stability of your vehicle on the road. Be prepared to slow down if necessary."},{"id":"60","category_id":"2","question":"What does this sign mean?","img":"a_HKhWw.png","options":["Low bridge 500 metres ahead.","Motorway ends 500 metres ahead.","No overtaking for 500 metres.","Bridge repair 500 metres ahead."],"answer":["option_2"],"explanation":"This is a motorway information sign that tells you that the motorway will end in 500 metres ahead. Motorway rules will no longer apply, for example a lower speed limit may be applicable."},{"id":"61","category_id":"2","question":"What does this sign mean?","img":"a_tyqLP.png","options":["End of overhead bridge area.","End of motorway.","No bridges ahead.","No overtaking."],"answer":["option_2"],"explanation":"This sign indicates the end of the motorway. You are leaving the motorway and its rules will no longer apply."},{"id":"62","category_id":"2","question":"What does this sign mean?","img":"a_riLFV.png","options":["Overtaking lane ends ahead.","A driver may overtake on the right only.","Road narrows from right.","Right-hand lane has an uneven surface."],"answer":["option_3"],"explanation":"Where there are roadworks up ahead, this warning sign tells you that the road narrows from the right creating a potential hazard."},{"id":"63","category_id":"2","question":"What does this sign mean?","img":"a_YSgPe.png","options":["End of dual carriageway ahead.","Road narrows on both sides.","Traffic merging from both sides.","End of obstruction between lanes."],"answer":["option_2"],"explanation":"This roadworks warning sign tells you that the road narrows on both sides creating a potential hazard. Be prepared to slow down and drive with extra care."},{"id":"64","category_id":"2","question":"What does this sign mean?","img":"a_1sgOn.png","options":["Flagman ahead.","Hitch-hiking permitted.","Football stadium ahead.","Pedestrian crossing to right."],"answer":["option_1"],"explanation":"This roadworks warning sign tells you that the traffic flow ahead is controlled manually by a flagman. Be aware and follow directions given by the flagman."},{"id":"65","category_id":"2","question":"What does this sign mean?","img":"a_wLbSg.png","options":["Traffic may not stop.","Dual carriageway ahead.","One-way street.","Two-way traffic."],"answer":["option_4"],"explanation":"This warning sign tells you that during roadworks there will be two-way traffic in operation ahead. Continue to drive with extra care."},{"id":"66","category_id":"2","question":"What does this sign mean?","img":"a_Ta9Rx.png","options":["Nearside lane of two closed.","T-junction ahead in the left lane.","Offside lane of two closed.","Traffic in nearside lane must turn left."],"answer":["option_1"],"explanation":"This roadworks warning sign tells you that the nearside (left-hand) lane is closed ahead. If you are in this lane you will need to move to the offside (right-hand) lane when it is safe to do so."},{"id":"67","category_id":"2","question":"What does this sign mean?","img":"a_fiL3t.png","options":["End of dual carriageway.","Corner ahead on offside lane.","Offside lane closed ahead.","No stopping, except in offside lane."],"answer":["option_3"],"explanation":"This roadworks warning sign tells you that the offside (right-hand) lane of three is closed ahead. Drivers in the nearside or centre lanes should be aware that traffic may merge from the right."},{"id":"68","category_id":"2","question":"What does this sign mean?","img":"a_mB2BA.png","options":["Bend in the road to the left ahead.","Lay-by ahead.","Traffic should cross back to the left-hand lane ahead.","Slow lane ahead for heavy traffic."],"answer":["option_3"],"explanation":"This roadworks warning sign tells you that the course of the road will return to the left ahead. This usually appears after a stretch where traffic was diverted to a right-hand lane."},{"id":"69","category_id":"2","question":"What does this sign mean?","img":"a_Iyw4N.png","options":["Traffic should cross out to the right-hand lane ahead.","Bend in the road to the right ahead.","Traffic calming measures ahead.","End of “no overtaking” zone."],"answer":["option_1"],"explanation":"This roadworks warning sign tells you that the course of the road will divert to the right ahead."},{"id":"70","category_id":"2","question":"What does this sign mean?","img":"a_IIije.png","options":["Tunnel ends ahead.","Dual carriageway ends ahead.","End of central reserve or obstruction.","Beware of vehicle with a wide load."],"answer":["option_3"],"explanation":"This roadworks warning sign tells you that traffic previously separated by the central reserve or an obstruction will revert to two-way traffic."},{"id":"71","category_id":"2","question":"What does this hand signal mean?","img":"a_7u9Em.png","options":["The cyclist intends to stop.","The cyclist intends to slow down.","The cyclist intends to move out or turn right.","The cyclist intends to move in or turn left."],"answer":["option_3"],"explanation":"This hand signal tells other road users that the cyclist intends to either move out or make a right-hand turn. Drivers should be aware that cyclists could move out into the path of their vehicle without looking."},{"id":"72","category_id":"2","question":"What does this hand signal mean?","img":"a_icih4.png","options":["The cyclist is signalling following traffic to overtake.","The cyclist intends to slow down or stop.","The cyclist intends to move out.","The cyclist intends to turn left."],"answer":["option_2"],"explanation":"This hand signal informs other road users that cyclist intends to slow down or stop. This may indicate that the cyclist is aware of some hazard ahead, so drive with extra care."},{"id":"73","category_id":"2","question":"What does this hand signal mean?","img":"a_1KgXF.png","options":["The driver intends to proceed straight ahead.","The driver intends to turn left.","The driver intends to slow down or stop.","The driver intends to reverse."],"answer":["option_1"],"explanation":"This hand signal informs other road users or a Garda directing traffic that the driver intends to proceed straight ahead."},{"id":"74","category_id":"2","question":"What does this traffic light mean?","img":"a_sGGVY.png","options":["Traffic turning left should prepare for full green to move off.","Traffic is not allowed to turn left.","All traffic must turn left only.","Traffic turning left may proceed if the way is clear."],"answer":["option_4"],"explanation":"A green arrow (filter light) means that traffic may proceed in the direction of the arrow if it is safe to do so."},{"id":"75","category_id":"2","question":"When traffic lights are green, when should a driver not proceed?","img":"","options":["When oncoming traffic is waiting to turn left.","When traffic is stopped waiting to turn from the road on the right.","When it would be unsafe to do so.","When traffic is stopped waiting to turn from the road on the left."],"answer":["option_3"],"explanation":"Although a green traffic light means proceed with caution, you should not enter a junction if the way is not clear or if by doing so you would cause an obstruction to other road users."},{"id":"76","category_id":"2","question":"Where is a driver allowed to park?","img":"","options":["On a footpath.","Where there is a continuous white line along the centre of the road.","At road works.","Where the driver is not blocking other road users their view of traffic signals or the road ahead."],"answer":["option_4"],"explanation":"It is an offence to park at the side of a road that has a single or double continuous white line along its centre. Parking on such a road could create an obstruction and may cause inconvenience or danger to other road users."},{"id":"77","category_id":"2","question":"What distance before a zebra crossing is parking prohibited?","img":"","options":["15 metres.","10 metres.","20 metres.","5 metres."],"answer":["option_1"],"explanation":"It is an offence to park 15 metres before or 5 metres after a pedestrian crossing. Parking in this manner may restrict the zone of vision of drivers approaching the crossing and endanger pedestrians."},{"id":"78","category_id":"2","question":"Within what distance of a road junction is parking prohibited?","img":"","options":["15 metres, unless parking spaces are clearly marked.","10 metres, unless parking spaces are clearly marked.","5 metres, unless parking spaces are clearly marked.","20 metres, unless parking spaces are clearly marked."],"answer":["option_3"],"explanation":"It is an offence to park within 5 metres of a road junction unless parking spaces are clearly marked. Parking in that area may restrict the zone of vision of drivers approaching the junction and may cause an obstruction to large vehicles wishing to turn."},{"id":"79","category_id":"2","question":"Is a driver permitted to park at an entrance to a property?","img":"","options":["Yes, outside business hours.","Yes, for 1 hour between 07:00 hrs to 23:30 hrs.","Yes, with the property owner’s consent.","Yes, for 1 hour between 23:30 hrs to 07:00 hrs."],"answer":["option_3"],"explanation":"You may park across the entrance to a property only with the owner’s consent. Parking across an entrance may cause inconvenience and danger to persons entering or leaving the property."},{"id":"80","category_id":"2","question":"When is parking permitted on a footpath?","img":"","options":["It is never permitted to park on a footpath.","When cars are parked on both sides of the road.","When at least half of the footpath remains free for pedestrians.","When no more than half of the vehicle is on the footpath."],"answer":["option_1"],"explanation":"It is an offence to park on a footpath. Where a vehicle is parked on a footpath, pedestrians may have to step onto the road to go around the vehicle and so place themselves in danger."},{"id":"81","category_id":"2","question":"When is double parking permitted?","img":"","options":["When there is a hard shoulder.","When there are double yellow lines.","It is never permitted.","When there are double white lines."],"answer":["option_3"],"explanation":"Double parking is never permitted. Parking is never permitted where it might interfere in any way with the normal flow of traffic or obstruct or endanger other road users."},{"id":"82","category_id":"2","question":"When is parking permitted at a taxi rank?","img":"","options":["Parking at a taxi rank is prohibited unless driving a taxi.","When the rank is unoccupied.","When waiting to collect passengers from a taxi.","When parking for less than 15 minutes."],"answer":["option_1"],"explanation":"Stopping or parking within an area marked as a taxi rank is prohibited as this may obstruct taxis entering or leaving the rank."},{"id":"83","category_id":"2","question":"When is parking permitted at a sharp bend?","img":"","options":["Parking is never permitted at a sharp bend.","When drivers coming from behind can see the parked vehicle.","When the hazard warning lights of the parked vehicle are on.","When parking no more than 45 centimetres from the kerb or edge of the road."],"answer":["option_1"],"explanation":"Parking is never permitted where it might interfere in any way with the normal flow of traffic or obstruct or endanger other road users – for example, by forcing other drivers into the path of oncoming traffic."},{"id":"84","category_id":"2","question":"When is parking permitted on the brow of a hill?","img":"","options":["Only when there is no traffic on the road.","Parking is never permitted on the brow of a hill.","Parking is permitted when a vehicle has an efficient handbrake.","When the driver angles the wheels towards the kerb."],"answer":["option_2"],"explanation":"Parking on the brow of a hill or on a humpbacked bridge is prohibited. Parking in such a place may restrict the zone of vision of drivers approaching the hill and force them into the path of oncoming traffic."},{"id":"85","category_id":"2","question":"What is the purpose of traffic calming measures?","img":"","options":["To alert drivers to road flooding ahead.","To slow down traffic in the vicinity.","To inform the driver of an increased speed limit ahead.","To prioritise heavy goods traffic."],"answer":["option_2"],"explanation":"The purpose of traffic calming measures is to slow down fast-moving traffic to a speed more suitable for the area they are entering. These measures are usually found in rural areas on the entry points to towns or villages."},{"id":"86","category_id":"2","question":"When may a trailer be towed on a public road without a rear number plate?","img":"","options":["When the tailboard is removed.","When carrying a load that overhangs the trailer.","Never, a number plate must always be displayed.","When being towed by an agricultural tractor."],"answer":["option_3"],"explanation":"The law requires all motorised vehicles to display a rear number plate that is clean and legible."},{"id":"87","category_id":"2","question":"What traffic may use a cycle lane accompanied by a continuous white line?","img":"","options":["Cyclists and motorised wheelchairs.","Cyclists and taxis.","Cyclists and motorcyclists.","Buses and cyclists."],"answer":["option_1"],"explanation":"A cycle track is for the use of cyclists and motorised wheelchairs. No other vehicles may cross into or over a mandatory cycle track unless this is necessary in order to leave a side road or a property adjacent to the cycle track."},{"id":"88","category_id":"2","question":"Apart from cyclists and motorised wheelchairs, what other road users may use an unoccupied cycle lane accompanied by a broken white line?","img":"","options":["Only moped riders and motorcyclists.","Only buses and taxis.","All drivers may make temporary use.","Only hackneys and taxis."],"answer":["option_3"],"explanation":"Drivers may make temporary use of a cycle track with a broken white line on the right-hand side if it is not occupied."},{"id":"89","category_id":"2","question":"When must drivers stop at an automated railway level crossing with barriers and red flashing lights?","img":"","options":["Stop safely when the amber light shows, or when red lights start to flash.","When there are no lights visible.","When the red and amber lights stop flashing.","When the barrier is fully up."],"answer":["option_1"],"explanation":"You must stop safely when the amber light shows. Flashing red lights have the same meaning as a steady red traffic light - stop safely when they show."},{"id":"90","category_id":"2","question":"At a railway level crossing with unattended gates, what should a car driver do?","img":"","options":["Telephone the nearest railway station before opening a gate.","Open both gates and after passing the first, stop and close it.","Open both gates before proceeding to cross.","Drive halfway across and close the first gate before opening the second."],"answer":["option_3"],"explanation":"At a level crossing with unattended gates a driver must stop, look for trains and listen for the sound of a horn or approaching trains. If it is safe, open both gates, complete the crossing and then close both gates."},{"id":"91","category_id":"2","question":"What do flashing amber arrows indicate at a junction?","img":"","options":["When safe, drivers should proceed in the direction indicated.","It is prohibited to proceed in the direction indicated.","Proceed smartly through junction to avoid delay.","The direction indicated is a cul-de-sac."],"answer":["option_1"],"explanation":"When you meet a flashing amber arrow at a junction, you should proceed in the direction indicated provided it is safe to do so."},{"id":"92","category_id":"2","question":"When do temporary speed limits apply at roadworks?","img":"","options":["During business hours only.","Only when road workers are on site.","Only when there is oncoming traffic.","For the duration of the roadworks."],"answer":["option_4"],"explanation":"Temporary speed limits at road works apply for the duration of the works. When road works are completed, normal speed limits apply."},{"id":"93","category_id":"2","question":"What does a continuous white line along the centre of the road mean?","img":"a_4VNb7.png","options":["Traffic can overtake.","Parking allowed during business hours.","U-turn allowed during daylight hours.","No U-turn allowed."],"answer":["option_4"],"explanation":"You must never do a U-turn on any stretch of road with a continuous white line along its centre. The restricted vision at such places would make doing a U-turn very unsafe."},{"id":"94","category_id":"2","question":"When wanting to stop temporarily in a congested area where should the driver park?","img":"","options":["Double park in a convenient place with your hazard lights on.","Park on the footpath so as not to impede the free flow of traffic in the road.","Park slightly up on the footpath with the hazard lights on.","Park in a safe, legal and convenient place."],"answer":["option_4"],"explanation":"You should park only where it is safe, legal and convenient to do so. Your parked vehicle must not cause a danger or an obstruction to other road users. The use of hazard warning lights does not excuse unsafe or illegal parking."},{"id":"95","category_id":"2","question":"What is a clearway?","img":"","options":["An area that is strictly reserved for the loading and unloading of HGVs.","An area where stopping and parking is not permitted during certain times.","An area where stopping and parking is reserved for buses and taxis only.","An area that is reserved for pedestrians and motorised wheelchairs."],"answer":["option_2"],"explanation":"A clearway is an area of road that must be kept clear for moving traffic during certain times of the day (usually busy periods). The times when stopping or parking is prohibited are shown on an information plate under the sign."},{"id":"96","category_id":"2","question":"What does this sign mean when displayed on the approach to a toll plaza?","img":"a_EJpNq.png","options":["This lane closed - keep left.","Service station ahead.","Toll collector operating lane.","Garda checkpoint to the left."],"answer":["option_3"],"explanation":"This sign is used at toll plazas to direct traffic into a lane where the toll charge may be paid directly to a cashier. This lane would normally be used by motorists who have neither the exact change nor an electronic tag on their vehicle."},{"id":"97","category_id":"2","question":"What does this sign mean when displayed on the approach to a toll plaza?","img":"a_rOOVT.png","options":["Cashier in this lane.","Ticket dispenser in this lane.","Coin basket in this lane.","Electronic toll collection."],"answer":["option_3"],"explanation":"This sign is used at toll plazas to direct traffic into a lane where the toll charge may be paid by putting the exact change into an automatic coin machine. This lane usually has a height barrier fitted to prevent large vehicles using it."},{"id":"98","category_id":"2","question":"What does this sign mean when displayed on the approach to a toll plaza?","img":"a_Kbxjq.png","options":["Electronic toll accepted in any lane.","Electronic toll not accepted in this lane.","Electronic toll out of order in this lane.","Payment in euros only in this lane."],"answer":["option_1"],"explanation":"This sign is used at toll plazas to direct traffic into a lane where the toll charge is collected electronically. When the vehicle passes through the plaza it is identified by means of an electronic tag fitted to the front windscreen. Payment will be collected via the users account. Only vehicles fitted with the tags are allowed to use those lanes."},{"id":"99","category_id":"2","question":"What does a flashing amber arrow pointing left at a traffic light mean?","img":"a_IWkhj.png","options":["A driver may proceed before traffic on the other road.","The driver must wait until the traffic lights turn green.","A driver may turn left but must yield to traffic on the other road.","A driver must not proceed in this direction."],"answer":["option_3"],"explanation":"A flashing left amber arrow at a junction means you may proceed left but must give way to pedestrians and traffic already coming through the junction on the other road."},{"id":"100","category_id":"2","question":"What does this sign mean?","img":"a_xyNma.png","options":["Bridge ahead.","Entry to motorway.","End of motorway."],"answer":["option_2"],"explanation":"This road sign informs road users that they are entering the motorway and must obey motorway rules. Before driving on the motorway users must familiarise themselves with motorway rules."},{"id":"101","category_id":"2","question":"What does this sign mean?","img":"a_5O3ut.png","options":["Minor road ahead.","Start of dual carriageway.","Y-junction ahead with roads of equal importance."],"answer":["option_3"],"explanation":"This sign gives advance warning of a Y-junction hazard ahead with a road of equal importance. Be prepared to yield to other road users."},{"id":"102","category_id":"2","question":"What does this sign mean?","img":"a_RhrwM.png","options":["Roundabout ahead.","Ring road ahead.","Loop road ahead."],"answer":["option_1"],"explanation":"This sign gives advance warning of a roundabout ahead. You must be prepared to yield to other road users already on the roundabout or coming from the right."},{"id":"103","category_id":"2","question":"What does this sign mean?","img":"a_nDurY.png","options":["Mini-roundabout ahead.","Roadworks ahead, diversion in operation.","Loop road ahead."],"answer":["option_1"],"explanation":"This sign gives advance warning of a mini-roundabout ahead. You must be prepared to yield to other road users already on the roundabout or coming from the right."},{"id":"104","category_id":"2","question":"What does this sign mean?","img":"a_oPlEg.png","options":["Automatic level crossing ahead.","Unguarded level crossing ahead.","Attended level crossing ahead."],"answer":["option_1"],"explanation":"This sign gives advance warning of an automatic level crossing ahead. Drivers should approach with caution and be prepared to slow down or stop as necessary."},{"id":"105","category_id":"2","question":"What does this sign mean?","img":"a_nKdnS.png","options":["Steep descent ahead.","Unprotected quay, canal or river ahead.","Road likely to flood."],"answer":["option_2"],"explanation":"This sign gives advance warning of an unprotected area of water ahead. You should be cautious due to the extreme danger."},{"id":"106","category_id":"2","question":"What does this sign mean?","img":"a_zGQeG.png","options":["Deer or wild animals ahead.","Cattle and farm animals ahead.","Stag hunting ahead."],"answer":["option_1"],"explanation":"This sign gives advance warning that there may be deer or other wild animals coming onto the roadway. Be prepared to slow down or stop suddenly if required."},{"id":"107","category_id":"2","question":"What does this sign mean?","img":"a_tscYP.png","options":["Roadworks ahead.","Building site ahead.","Flagman ahead."],"answer":["option_1"],"explanation":"This warning sign tells you that there are roadworks ahead. You should approach with caution and be alert for a change in the road surface, and for the presence of machinery and road workers."},{"id":"108","category_id":"2","question":"What does this sign mean?","img":"a_vZu0C.png","options":["With-flow bus and cycle lane on left.","Cycle track ahead may be crossed by buses only.","Parking for buses and bicycles on left."],"answer":["option_1"],"explanation":"This sign indicates a nearside with-flow bus lane on the left. Only buses, taxis and cyclists may use the bus lane during the stated operational hours."},{"id":"109","category_id":"2","question":"What does this sign mean?","img":"a_cRz00.png","options":["Crossroads ahead with roads of lesser importance.","Crossroads ahead with roads of equal importance.","Major road ahead."],"answer":["option_2"],"explanation":"This sign gives advance warning of a crossroad junction ahead where the roads are of equal importance. At this type of junction you should yield to traffic approaching from the right and traffic already turning."},{"id":"110","category_id":"2","question":"What does this sign mean?","img":"a_zATQN.png","options":["Dangerous corner ahead.","Dangerous bend ahead.","Turn left."],"answer":["option_2"],"explanation":"This sign gives advance warning of a dangerous bend to the left. You may need to slow down and react to any changes in the traffic situation ahead."},{"id":"111","category_id":"2","question":"What does this sign mean?","img":"a_o1i5Z.png","options":["Series of dangerous bends ahead.","Overhead electric cables.","Series of dangerous corners ahead."],"answer":["option_3"],"explanation":"This sign gives advance warning of a series of dangerous corners ahead. You should slow down and react to any changes in the traffic situation."},{"id":"112","category_id":"2","question":"What does this sign mean?","img":"a_4mWNL.png","options":["Slippery road ahead.","Series of dangerous corners ahead.","Series of dangerous bends ahead."],"answer":["option_3"],"explanation":"This sign gives advance warning of a series of dangerous bends ahead. You should slow down and react to any changes in the traffic situation."},{"id":"113","category_id":"2","question":"What does this sign mean?","img":"a_SQ4Ak.png","options":["Road narrows on both sides.","End of dual carriageway.","Dual carriageway ahead."],"answer":["option_1"],"explanation":"This sign gives advance warning that the road is narrowing on both sides ahead. You should show caution and prepare to slow down."},{"id":"114","category_id":"2","question":"What does this sign mean?","img":"a_uPEmO.png","options":["Two-way traffic ahead.","One-way street ahead.","Dual carriageway ahead."],"answer":["option_1"],"explanation":"This sign gives advance warning of two-way traffic ahead, with oncoming traffic in the opposite lane."},{"id":"115","category_id":"2","question":"What does this sign mean?","img":"a_RFpCS.png","options":["Humpback bridge ahead.","Steep descent ahead.","Steep ascent ahead."],"answer":["option_3"],"explanation":"This sign gives advance warning of a steep ascent/upward hill ahead. You should react by selecting the appropriate gear."},{"id":"116","category_id":"2","question":"What does this sign mean?","img":"a_6KzVu.png","options":["Level crossing ahead with pedestrian walkway.","Playground ahead.","School children crossing ahead."],"answer":["option_3"],"explanation":"This sign gives advance warning that there may be school children crossing the road ahead, slow down if required and be prepared to stop."},{"id":"117","category_id":"2","question":"What does this sign mean?","img":"a_insrP.png","options":["School playground ahead.","Children’s play area ahead.","School children crossing ahead."],"answer":["option_3"],"explanation":"This sign gives advance warning that there may be school children crossing the road ahead, slow down if required and be prepared to stop."},{"id":"118","category_id":"2","question":"What do these signs together mean?","img":"a_bduUM.png","options":["Slippery road - children may fall.","Loose chippings on the road ahead.","Beware of children crossing."],"answer":["option_3"],"explanation":"These signs are usually displayed in residential areas, and they give advance warning that children might be crossing ahead. You should proceed cautiously and be prepared to stop suddenly."},{"id":"119","category_id":"2","question":"What does this sign mean?","img":"a_EErf4.png","options":["Livestock mart ahead.","Cattle grid ahead.","Possibility of cattle or farm animals ahead."],"answer":["option_3"],"explanation":"This sign gives advance warning that there may be cattle or other farm animals on the road ahead. Slow down if required and be prepared to stop."},{"id":"120","category_id":"2","question":"What does this sign mean?","img":"a_qzt3R.png","options":["Sheep market ahead.","Abattoir ahead.","Possibility of sheep ahead."],"answer":["option_3"],"explanation":"This sign gives advance warning that there may be sheep on the road ahead. Slow down if required and be prepared to stop."},{"id":"121","category_id":"2","question":"What does this sign mean?","img":"a_flHMR.png","options":["Historic site ahead.","Tunnel ahead.","Low bridge ahead."],"answer":["option_2"],"explanation":"This sign gives advance warning of a tunnel ahead. You should be aware of the procedures to follow when entering a tunnel – which include keeping a safe distance from the vehicle ahead or removing sunglasses."},{"id":"122","category_id":"2","question":"What does this sign mean?","img":"a_KIsoa.png","options":["Rugged coast ahead.","Danger of falling rocks ahead.","Steep descent ahead."],"answer":["option_2"],"explanation":"This sign gives advance warning that there is a danger of rocks and other debris falling onto the road. Drive with caution."},{"id":"123","category_id":"2","question":"What does this sign mean?","img":"a_5Co3O.png","options":["Direction of prevailing wind.","Possibility of low flying aircraft.","Airport ahead."],"answer":["option_2"],"explanation":"This sign gives advance warning that there may be low-flying aircraft in the area. Low-flying aircraft can cause distraction due to a sudden loud noise."},{"id":"124","category_id":"2","question":"What does this sign mean?","img":"a_MjW88.png","options":["A driver must merge from the left.","A driver must drive on the left-hand side.","A driver must overtake on the left-hand side."],"answer":["option_2"],"explanation":"This sign is generally in areas where tourists might be travelling and reminds motorists to drive on the left. These signs are commonly found around airports and ferry ports."},{"id":"125","category_id":"2","question":"What does this sign mean?","img":"a_o7yyw.png","options":["Road narrows from the right.","Slippery road.","Series of bends ahead."],"answer":["option_2"],"explanation":"This roadworks warning sign tells you that the surface ahead is slippery due to mud or debris and there is an increased risk of skidding."},{"id":"126","category_id":"2","question":"What does this sign mean?","img":"a_apir9.png","options":["Left-hand lane has an uneven surface.","Slow lane ends ahead.","Road narrows from left."],"answer":["option_3"],"explanation":"This warning sign tells you that there are roadworks up ahead where the road narrows from the left creating a potential hazard."},{"id":"127","category_id":"2","question":"What does this sign mean?","img":"a_Pihua.png","options":["School children crossing ahead.","Temporary traffic signals ahead.","Railway crossing ahead."],"answer":["option_2"],"explanation":"This roadworks warning sign tells you that temporary traffic signals are in use ahead. You should prepare to slow down, approach with caution and comply with the signal displayed."},{"id":"128","category_id":"2","question":"What does this sign mean?","img":"a_u7Hyi.png","options":["Overtaking permitted, except on the left lane.","Do not drive on the hard shoulder.","Nearside lane of three closed."],"answer":["option_3"],"explanation":"This roadworks warning sign tells you that the nearside (left-hand) lane of three is closed up ahead. If you are in this lane you will need to move to the centre (middle) lane when it is safe to do so."},{"id":"129","category_id":"2","question":"At roadworks, what does this sign mean?","img":"a_h2q4I.png","options":["Proceed with caution.","Proceed using hand signals only.","Proceed only when beckoned to do so."],"answer":["option_1"],"explanation":"This traffic control sign tells you that you may proceed with caution through road works."},{"id":"130","category_id":"2","question":"At roadworks, what does this sign mean?","img":"a_6QKkX.png","options":["Stop only if faced by oncoming traffic.","Stop before or at the sign.","Stop for school warden."],"answer":["option_2"],"explanation":"This traffic control sign at roadworks means you must stop."},{"id":"131","category_id":"2","question":"What do these signs together mean?","img":"a_F1Gno.png","options":["End of road.","End of road works.","End of detour."],"answer":["option_3"],"explanation":"Together these two signs indicate that a detour has ended."},{"id":"132","category_id":"2","question":"What does this hand signal mean?","img":"a_9wYYI.png","options":["The cyclist intends to stop.","The cyclist intends to turn right.","The cyclist intends to turn left."],"answer":["option_2"],"explanation":"This hand signal tells other road users that the cyclist intends to either move out or make a right-hand turn. Drivers should be aware that cyclists could cross the path of their vehicle."},{"id":"133","category_id":"2","question":"What distance after a pedestrian crossing can a driver park to make a delivery?","img":"","options":["15 metres","5 metres","10 metres"],"answer":["option_2"],"explanation":"Make sure you do not interfere with normal traffic flow and that your vehicle does not disturb, block or endanger other road users. A driver must not park 15 metres before or 5 metres after a pedestrian crossing or traffic lights."},{"id":"134","category_id":"2","question":"Unless otherwise indicated, what is the maximum speed allowed for a car towing a trailer on national roads?","img":"","options":["100 km/h.","60 km/h.","120 km/h.","80 km/h."],"answer":["option_4"],"explanation":"When towing a trailer on a national road, it is illegal to exceed 80 km/h – exceeding this speed will make the vehicle unstable."},{"id":"135","category_id":"2","question":"What does a continuous white line in the centre of the road mean?","img":"a_hiFH7.png","options":["Vehicles may perform a U-turn.","Vehicles may park during daylight hours only.","Vehicles may not cross or drive over the line.","Vehicles may cross the line for a short time."],"answer":["option_3"],"explanation":"You must not cross or straddle a continuous white line in the centre of the road unless you wish to enter land or premises and it is safe to do so."},{"id":"136","category_id":"2","question":"What lights are recommended to be used when parking or leaving a vehicle for a short period of time on the side of the road at night?","img":"","options":["Rear fog lights in order to alert other road users to the vehicle’s size.","Front and rear side lights to alert other road users to the vehicle’s presence.","Front dipped headlights in order to alert other road users to the vehicle’s location."],"answer":["option_2"],"explanation":"Drivers can quickly become dazzled and disorientated by headlights or fog lights of parked vehicles. If you need to have lights on in these circumstances, you should use only side or parking lights. You should not leave headlights on when parked."},{"id":"137","category_id":"2","question":"What should a driver check when parking their vehicle?","img":"","options":["That the roadway is adequately lit.","That the vehicle is at least 15 centimetres from the kerb.","That they comply with mandatory road markings and signs."],"answer":["option_3"],"explanation":"Drivers should ensure when parking their vehicle on a roadway that they comply with all relevant road markings and road signs posted, e.g. a driver should not park opposite a continuous white line."},{"id":"138","category_id":"2","question":"What does this sign mean?","img":"a_cGPHX.png","options":["Bus and tramway crossing ahead.","Tramway crossing ahead.","Railway station.","Level crossing ahead."],"answer":["option_2"],"explanation":"This sign gives advance warning sign of a tram crossing ahead. You should be prepared to stop and yield to the tram, if required."},{"id":"139","category_id":"2","question":"What must a driver do when this sign is NOT accompanied by a white stop line on the road?","img":"a_PgFOM.png","options":["Stop no more than one car length past the sign.","Stop at the sign.","Stop only if there is traffic on the major road.","Stop past the sign."],"answer":["option_2"],"explanation":"Where a STOP sign is not accompanied by a white stop line, you must stop at the sign."},{"id":"140","category_id":"2","question":"What does this sign mean at a junction?","img":"a_HFvTh.png","options":["Yield to traffic coming from your right only.","Slow down and yield to pedestrians.","Yield to all heavy goods vehicles.","Yield to traffic on the major road."],"answer":["option_4"],"explanation":"At a junction, the YIELD sign tells you that you must give way to traffic on a major road ahead. This means that you must slow down and be prepared to stop."},{"id":"141","category_id":"2","question":"What does this sign mean at a roundabout?","img":"a_MZO5H.png","options":["Yield to traffic coming from the left.","Yield to cyclists and motorcyclists only.","Yield to traffic coming from the right, or already on the roundabout.","Yield to buses and trucks only."],"answer":["option_3"],"explanation":"At a roundabout, the YIELD sign tells you that you must slow down and be prepared to stop. You must yield (give way) to traffic already on the roundabout or coming from the right."},{"id":"142","category_id":"2","question":"What does this sign mean?","img":"a_6tADJ.png","options":["Traffic from the right has priority.","Motorway to the left.","Diversion ahead to the left.","Turn left only."],"answer":["option_4"],"explanation":"This sign tells you that you must turn left. It is usually displayed at a junction where all traffic must turn left – for example, in a one-way system that incorporates a junction."},{"id":"143","category_id":"2","question":"What does this sign mean?","img":"a_yVQfi.png","options":["Overtake only on the right.","Turn right only.","Major road joining from the left.","Diversion ahead to the right."],"answer":["option_2"],"explanation":"This sign tells you that you must turn right. It is usually displayed at a junction where all traffic must turn right – for example, in a one-way system that incorporates a junction."},{"id":"144","category_id":"2","question":"What does this sign mean?","img":"a_csJu4.png","options":["Diversion to the left ahead.","Sharp corner to the left ahead.","Turn left ahead.","One-way traffic to the left ahead."],"answer":["option_3"],"explanation":"This sign tells you that you must turn left ahead. It is usually displayed on the approach to a one-way system."},{"id":"145","category_id":"2","question":"What does this sign mean?","img":"a_v4bq6.png","options":["One-way traffic to the right ahead.","You must turn right ahead.","Diversion to the right ahead.","Sharp bend to the right ahead."],"answer":["option_2"],"explanation":"This sign tells you that you must turn right ahead. It is usually displayed on the approach to a one-way system."},{"id":"146","category_id":"2","question":"What does this sign mean?","img":"a_CGd3Y.png","options":["Pass either side.","Dual carriageway ahead.","One-way street.","Two-way traffic ahead."],"answer":["option_1"],"explanation":"This sign tells you that traffic may pass on either side of the traffic island."},{"id":"147","category_id":"2","question":"What does this sign mean?","img":"a_iJ2ij.png","options":["Entry to tunnel prohibited.","Two-way traffic prohibited.","U-turn not permitted.","Reversing not permitted."],"answer":["option_3"],"explanation":"This sign tells you that you are not permitted to make a U-turn. It is commonly displayed on approach to junctions on dual carriageways. Drivers should also be aware that U-turns are also not permitted anywhere there is a continuous white line along the centre of the road or on a one-way street."},{"id":"148","category_id":"2","question":"What does this sign mean?","img":"a_ukjYl.png","options":["Parking is prohibited during the hours shown.","Disc parking operates except during the hours shown.","Disc parking operates during the time shown.","Parking without a disc is allowed during the hours shown."],"answer":["option_3"],"explanation":"This sign tells you that vehicles must display a parking disc when parked during the hours shown on the information plate."},{"id":"149","category_id":"2","question":"What does this sign mean?","img":"a_lNeSV.png","options":["Private parking is permitted when the taxi rank is empty.","Only taxis may turn right or left.","Private vehicles may pick up or set down passengers.","Designated rank for taxis."],"answer":["option_4"],"explanation":"A taxi rank sign indicates that this is an area reserved for taxis, and parking or stopping by other road users is not permitted."},{"id":"150","category_id":"2","question":"What does this sign mean?","img":"a_uyBr2.png","options":["Cyclists must dismount ahead.","Track reserved for motorcyclist.","Start of cycle track.","Bicycle race track."],"answer":["option_3"],"explanation":"This sign indicates the start of a cycle track. If the track is bounded by a broken white line, other road users should avoid using it wherever possible. If it is bounded by a continuous white line, drivers of cars and other vehicles must not drive on it."},{"id":"151","category_id":"2","question":"What does this sign mean?","img":"a_orQ38.png","options":["Junction ahead with roads of greater importance.","Junction ahead with roads of lesser importance.","Junction ahead with railway crossing.","Junction ahead with roads of equal importance."],"answer":["option_2"],"explanation":"This sign gives advance warning of a junction ahead with minor roads on either side. Be aware that vehicles may be emerging from the minor roads."},{"id":"152","category_id":"2","question":"What does this sign mean?","img":"a_XA6gY.png","options":["T-junction ahead with road of less importance.","T-junction ahead with roads of equal importance.","T-junction ahead with merging traffic.","T-junction ahead with dual carriageway."],"answer":["option_2"],"explanation":"This sign gives advance warning of a T-junction ahead with a road of equal importance. You must give way to traffic already on the road you are joining."},{"id":"153","category_id":"2","question":"What does this sign mean?","img":"a_jMJxY.png","options":["Major roadworks ahead.","Level crossing ahead unguarded by gates or barriers.","End of major roadworks ahead.","Level crossing ahead guarded by gates or barriers."],"answer":["option_2"],"explanation":"This sign gives advanced warning of an unguarded level crossing ahead. This is a crossing without gates or barriers and you should cross it with extreme caution."},{"id":"154","category_id":"2","question":"What does this sign mean?","img":"a_WB2sQ.png","options":["Private grounds - no entry.","Level crossing ahead guarded by gates or barriers.","Road fencing ahead.","Farm machinery crossing ahead."],"answer":["option_2"],"explanation":"This sign gives advance warning of a railway crossing ahead that is protected by gates or lifting barriers. You should be prepared to stop and follow the required procedure."},{"id":"155","category_id":"2","question":"What does this sign mean?","img":"a_BCMFP.png","options":["Series of bumps or hollows ahead.","Road falls from centre to left and right.","Traffic island ahead.","Sharp rise in the road ahead - for example, a humpback bridge."],"answer":["option_4"],"explanation":"This sign gives advance warning of a hump in the road. You should adjust your speed accordingly."},{"id":"156","category_id":"2","question":"What does this sign mean?","img":"a_EwicU.png","options":["Riding path - no vehicles allowed.","Entrance to horse riding school.","Racecourse ahead.","Accompanied horses and ponies ahead."],"answer":["option_4"],"explanation":"This sign gives advance warning that there may be horses on the road ahead. You should show due regard for horses and their riders."},{"id":"157","category_id":"2","question":"What does this sign mean?","img":"a_CBo7z.png","options":["School ahead.","Pedestrian crossing ahead.","Lane reserved for pedestrians.","Beware of pedestrians at night."],"answer":["option_2"],"explanation":"This sign gives advance warning of a pedestrian crossing ahead. You should show caution and be prepared to stop."},{"id":"158","category_id":"2","question":"What does this sign mean?","img":"a_nEEHy.png","options":["Sharp descent in 200 metres.","No overtaking for 200 metres.","Dual carriageway crossing ahead.","200 metres to the next exit."],"answer":["option_4"],"explanation":"This is a motorway information sign that tells you that the next exit off the motorway is 200 metres ahead."},{"id":"159","category_id":"2","question":"What does this sign mean?","img":"a_wPk09.png","options":["Mini-roundabout ahead.","Heavy vehicles have priority.","Start of central reserve or obstruction.","Dual carriageway ahead."],"answer":["option_3"],"explanation":"This roadworks warning sign tells you that two-way traffic will separate to avoid an obstruction."},{"id":"160","category_id":"2","question":"What does this hand signal mean?","img":"a_G90us.png","options":["The cyclist intends to stop.","The cyclist intends to turn left.","The cyclist intends to go straight on.","The cyclist is giving way to other traffic."],"answer":["option_3"],"explanation":"This hand signal informs other road users that the cyclist intends to proceed straight ahead at a junction and drivers should show caution."},{"id":"161","category_id":"2","question":"What does this hand signal mean?","img":"a_0teuf.png","options":["The driver intends to go straight ahead.","The driver intends to turn left.","The driver intends to slow down or stop.","The driver intends to turn right."],"answer":["option_2"],"explanation":"This hand signal informs other road users that the driver intends to turn left and the vehicle will change direction."},{"id":"162","category_id":"2","question":"What does this hand signal mean?","img":"a_mz92a.png","options":["The driver intends to move out or turn right.","The driver intends to do a U-turn.","The driver intends to turn left.","The driver intends to stop ahead."],"answer":["option_1"],"explanation":"This hand signal informs other road users that the driver intends to move out or turn right and the vehicle will change direction."},{"id":"163","category_id":"2","question":"What does this hand signal mean?","img":"a_uepdM.png","options":["The driver intends to slow down or stop.","The driver intends to begin a U-turn.","The driver intends to turn right.","The driver intends to turn left."],"answer":["option_1"],"explanation":"This hand signal informs other road users that the driver intends to slow down or stop and following traffic should be prepared to slow down also."},{"id":"164","category_id":"2","question":"What does this hand signal mean?","img":"a_XdjnY.png","options":["The driver intends to turn left.","The driver intends to stop.","The driver intends to slow down.","The driver intends to turn right."],"answer":["option_1"],"explanation":"This hand signal informs other road users or a Garda directing traffic (facing this vehicle), that the driver intends to make a left-hand turn."},{"id":"165","category_id":"2","question":"What does this hand signal mean?","img":"a_8g2TZ.png","options":["The driver intends to turn left.","The driver will begin to reverse.","The driver intends to slow down.","The driver intends to turn right."],"answer":["option_4"],"explanation":"This hand signal informs other road users or a Garda directing traffic (facing this vehicle) that the driver intends to turn right."},{"id":"166","category_id":"2","question":"What does this Garda signal mean?","img":"a_3bA94.png","options":["Turn right.","Stop if approaching from front.","Stop if approaching from behind.","Turn left."],"answer":["option_3"],"explanation":"When approaching a Garda giving this signal you must stop."},{"id":"167","category_id":"2","question":"What does this Garda signal mean?","img":"a_jVMPa.png","options":["Turn left.","Stop if approaching from either the front or behind.","Turn right.","Proceed if approaching from the front."],"answer":["option_2"],"explanation":"When approaching a Garda giving this signal you must stop."},{"id":"168","category_id":"2","question":"What does this Garda signal mean?","img":"a_5I78t.png","options":["The Garda is beckoning on traffic from the front.","The driver must not proceed to the right.","The driver must not proceed to the left.","The Garda is beckoning on traffic approaching from either side."],"answer":["option_4"],"explanation":"When approaching a Garda giving this signal you may proceed."},{"id":"169","category_id":"2","question":"What does this Garda signal mean?","img":"a_PsbM2.png","options":["Traffic approaching from the front must stop.","Traffic approaching from the right may proceed.","Traffic approaching from the front may proceed.","Traffic approaching from behind must stop."],"answer":["option_3"],"explanation":"When approaching a Garda giving this signal you may proceed."},{"id":"170","category_id":"2","question":"What does this road marking indicate?","img":"a_L1hvz.png","options":["No entry.","Speed control ramp.","Pelican crossing.","Zebra crossing."],"answer":["option_4"],"explanation":"A zebra crossing is a designated area for pedestrians to cross the road. As a driver you must always yield to pedestrians on a zebra crossing."},{"id":"171","category_id":"2","question":"What does this road marking mean?","img":"a_US2oE.png","options":["A driver may overtake in this area.","Road surface is uneven.","No parking in this area.","Set down area only."],"answer":["option_3"],"explanation":"White zigzag lines indicate that you are approaching a pedestrian crossing. You must not park or overtake within this area."},{"id":"172","category_id":"2","question":"What does this road marking mean?","img":"a_VBViE.png","options":["Traffic entering a box junction may have right of way over traffic from both right and left.","Traffic entering a box junction from right and left has the right of way unless continuing straight on.","Traffic must not enter unless they can clear the box junction without stopping, or when turning right.","Taxi set-down area."],"answer":["option_3"],"explanation":"You must not enter the yellow box junction unless you can clear it without stopping or unless you are turning right and are prevented from doing so by oncoming traffic."},{"id":"173","category_id":"2","question":"What does this road marking mean?","img":"a_uqYYY.png","options":["Road narrows ahead.","A driver is approaching a STOP sign.","All traffic must keep to the left of the white line.","A driver may overtake."],"answer":["option_3"],"explanation":"Where there is a continuous white line in the centre of the road, you are not permitted to: 1. Straddle or cross the white line; 2. Overtake another vehicle; 3. Perform a U-turn; or 4. Park on the road."},{"id":"174","category_id":"2","question":"What does this road marking and information plate together mean?","img":"a_EvfNp.png","options":["Parking only at times and days shown.","Parking not allowed at the times and days shown.","Taxi parking only at the times and days shown.","Taxi parking only outside the times and days shown."],"answer":["option_2"],"explanation":"A single yellow line along the edge of a road means that you must not park there during the times shown on the accompanying information plate."},{"id":"175","category_id":"2","question":"What does this road marking and information plate together mean?","img":"a_jsyYQ.png","options":["Taxi rank at times shown.","No parking at any time.","Parking not allowed at the times shown.","Loading bay at times shown."],"answer":["option_3"],"explanation":"A single yellow line along the edge of a road means that you must not park there during the times shown on the accompanying information plate."},{"id":"176","category_id":"2","question":"What does this road marking mean?","img":"a_xy8PH.png","options":["A driver may not overtake along this road.","A driver must not cross the broken white line unless it is safe to do so.","A driver may overtake provided they do not cross the broken white line.","A driver may not park along this road."],"answer":["option_2"],"explanation":"A broken white line along the centre of the road means you must not cross the line unless it is safe to do so when overtaking or passing."},{"id":"177","category_id":"2","question":"What do these road markings mean?","img":"a_oJrcz.png","options":["No parking allowed.","Dual carriageway ahead.","No overtaking allowed.","Continuous white lines ahead."],"answer":["option_4"],"explanation":"Double broken white lines along the centre of the road alert you to continuous white lines ahead. Do not cross them unless it is safe to do so."},{"id":"178","category_id":"2","question":"If driving from A to B, what do these road markings mean?","img":"a_gvMOv.png","options":["A driver may overtake if it is safe to do so.","Road narrows ahead.","Dual carriageway ahead.","A driver may not overtake."],"answer":["option_1"],"explanation":"Where there is a broken white line and a continuous white line along the centre of the road, you must obey the line that is nearest to you. In this case you may cross the lines as long as it is safe to do so."},{"id":"179","category_id":"2","question":"If driving from A to B, what do these road markings mean?","img":"a_euKIX.png","options":["A driver may not cross the lines to overtake.","A driver may cross the lines to overtake.","Oncoming traffic may not cross the lines to overtake.","Only motorcyclists may cross the lines to overtake."],"answer":["option_1"],"explanation":"Where there is a broken white line and a continuous white line along the centre of the road, you must obey the line that is nearest to you. In this case you may not cross the lines."},{"id":"180","category_id":"2","question":"What does this road marking mean?","img":"a_ALYsb.png","options":["No entry.","Pedestrian crossing.","The road ahead is a cul-de-sac.","Private vehicles not allowed."],"answer":["option_1"],"explanation":"This road marking indicates a one-way street. You may not enter this street."},{"id":"181","category_id":"2","question":"What does this road marking mean?","img":"a_4KNOY.png","options":["Parking prohibited at all times.","Taxi parking only.","Keep outside the yellow lines.","Parking prohibited during business hours."],"answer":["option_1"],"explanation":"A double yellow line along the edge of the road means parking is not allowed at any time."},{"id":"182","category_id":"2","question":"What does this road marking mean?","img":"a_s6mt8.png","options":["Drivers must keep left of the continuous white line.","Only motorcyclists may cross the lines to overtake.","Oncoming traffic may cross the line to overtake.","Drivers may cross the line to overtake."],"answer":["option_1"],"explanation":"A single continuous white line along the centre of the road means all traffic must keep to the left of the line. You are not permitted to overtake or perform a U-turn on this section of road."},{"id":"183","category_id":"2","question":"What does the broken yellow line road marking mean?","img":"a_sjkNA.png","options":["The edge of the carriageway or hard shoulder.","No stopping for any reason except in an emergency.","Parking prohibited at all times.","Slow lane for heavy vehicles only."],"answer":["option_1"],"explanation":"A single broken yellow line along the side of the road marks the edge of the carriageway/hard shoulder. This is normally for the use of pedestrians and cyclists. As a driver, however, you may use it briefly to allow faster traffic to overtake, but only where it is safe to do so."},{"id":"184","category_id":"2","question":"What does this traffic light mean?","img":"a_THz5i.png","options":["Proceed if the way is clear.","The traffic lights are out of order.","Stop, unless it is unsafe to do so.","Prepare to move off."],"answer":["option_3"],"explanation":"When the traffic light is showing amber you must not go beyond the stop line unless you so close to the traffic lights that stopping would be dangerous."},{"id":"185","category_id":"2","question":"What does this traffic light mean?","img":"a_kLNpN.png","options":["Traffic must stop at the traffic light.","Traffic may proceed but not turn right.","Give way to any oncoming traffic turning right.","Traffic may proceed if the way is clear."],"answer":["option_4"],"explanation":"You may proceed on a green traffic light if it is safe to do so."},{"id":"186","category_id":"2","question":"What colour traffic light comes on after the green?","img":"","options":["Flashing amber.","Green arrow.","Red only.","Amber only."],"answer":["option_4"],"explanation":"The normal sequence of traffic lights is red–green–amber."},{"id":"187","category_id":"2","question":"What colour traffic light comes on after a non-flashing amber light?","img":"","options":["Red only.","Flashing red light.","Green only.","Flashing amber light."],"answer":["option_1"],"explanation":"The normal sequence of traffic lights is red–green–amber."},{"id":"188","category_id":"2","question":"What do flashing amber lights at a pelican crossing mean?","img":"","options":["Danger ahead. A driver must stop and wait until the light stops flashing.","Drivers have right of way.","Stop and give way to pedestrians - proceed if the way is clear.","A driver is entering a special speed limit area."],"answer":["option_3"],"explanation":"A flashing amber light at a pelican crossing means you must yield to pedestrians. You may proceed, however, if the crossing is clear."},{"id":"189","category_id":"2","question":"Which car, if any, is parked incorrectly?","img":"a_dWhDU.png","options":["Neither car.","Both cars.","The green car.","The red car."],"answer":["option_2"],"explanation":"It is an offence to park within 15 metres before or 5 metres after a pedestrian crossing. Parking in this manner may restrict the zone of vision of drivers approaching the crossing and endanger pedestrians."},{"id":"190","category_id":"2","question":"What should a driver do when approaching traffic lights that change from green to amber?","img":"a_qo9fW.png","options":["Accelerate to clear the junction.","Stop the vehicle immediately.","Sound the horn while proceeding through the junction.","Stop, unless it is unsafe to do so."],"answer":["option_4"],"explanation":"When you are approaching a set of traffic lights showing green, you should take care and be prepared to stop if the amber light comes on."},{"id":"191","category_id":"2","question":"What should a driver do at an amber traffic light?","img":"a_WBDLK.png","options":["Continue only if sure that the junction is clear of pedestrians.","Continue as there is no traffic at the junction.","Stop at the line unless it is not safe to do so.","Make sure to pass the lights before they turn red."],"answer":["option_3"],"explanation":"By law you must stop at an amber traffic light if it is safe to do so."},{"id":"192","category_id":"2","question":"What restriction applies to a driver’s full licence if they have passed their test on a vehicle with automatic transmission?","img":"","options":["They must continue to display L plates.","They may not drive on motorways.","They may not drive at speeds of more that 80 km/h.","They may not drive vehicles with manual transmission."],"answer":["option_4"],"explanation":"If you pass your driving test in a vehicle fitted with automatic transmission, a code 78 will be noted on the full licence in the restrictions/information column."},{"id":"193","category_id":"2","question":"What roads are learner permit holders allowed to drive on?","img":"","options":["All roads except national roads.","All roads except dual-carriageways.","All roads except motorways and dual-carriageways.","All roads except motorways."],"answer":["option_4"],"explanation":"A learner permit holder must not drive on a motorway. It is a serious offence to do so."},{"id":"194","category_id":"2","question":"How should an L plate be composed?","img":"","options":["A green L on a white background.","A red L on a transparent background.","A white L on a red background.","A red L on a white background."],"answer":["option_4"],"explanation":"L plates should be displayed front and rear. The plates should be a red L on a white background and should be not less than 15 cm high with a border of at least 2 cm. A learner motorcyclist must wear a yellow tabard displaying L plates front and rear. The L plates must be not less than 15 cm high on a white background."},{"id":"195","category_id":"2","question":"Which roads are learner permit holders not allowed to drive on?","img":"","options":["They may not drive on national roads.","They may not drive on dual carriageways.","They may not drive on rural roads.","They may not drive on motorways."],"answer":["option_4"],"explanation":"A learner permit holder must not drive on a motorway. It is a serious offence to do so."},{"id":"196","category_id":"2","question":"Is it permitted to use a vehicle in a public place without a current tax disc displayed?","img":"","options":["No, only vintage vehicles are exempt from displaying a tax disc.","Yes, but for not more than 10 days after the expiry of the previous disc.","Yes, but for not more than one month after the expiry of the previous disc.","No, all motor vehicles must display a current tax disc."],"answer":["option_4"],"explanation":"A motor vehicle must be taxed and must display the up-to-date tax disk before it may be taken on the road."},{"id":"197","category_id":"2","question":"If a driver wishes to drive a vehicle but the tax disc is expired, what should they do?","img":"","options":["They should tax it immediately.","They should drive it only in case of an emergency.","They should contact the Gardaí for approval.","They should renew it within 10 days of expiry."],"answer":["option_1"],"explanation":"A motor vehicle must be taxed and must display the up-to-date tax disc before it may be taken on the road."},{"id":"198","category_id":"2","question":"If a driver wishes to drive another vehicle which is not currently taxed, would they be allowed to transfer the current tax disc from their own vehicle onto it?","img":"","options":["Under circumstances when the proper form has been completed and sent to the local Motor Tax Office.","Under no circumstances should a tax disc be transferred to another vehicle.","Yes, provided their own vehicle is not being used at the same time.","Only on a temporary basis if the other vehicle is subject to a lower rate of tax."],"answer":["option_2"],"explanation":"A motor vehicle must be taxed and must display its own current tax disc before it may be taken on the road. The tax disc includes information about the vehicle, including its make and model, colour and registration number."},{"id":"199","category_id":"2","question":"When a vehicle is being driven by a person who is not the owner, who is responsible for ensuring that the vehicle is taxed and that a current tax disc is displayed?","img":"","options":["The owner is the only one responsible.","The driver is the only one responsible.","The Gardaí have total responsibility in this area.","The driver and/or the owner of the vehicle are responsible."],"answer":["option_4"],"explanation":"If you are the owner or the driver of a vehicle, you must ensure that it is taxed and that it displays an up-to-date tax disc before you take it on the road."},{"id":"200","category_id":"2","question":"When must a current tax disc be displayed on a new vehicle on a public road?","img":"","options":["At all times when the vehicle is on a public road.","Not later than 1 month after registration.","Only when driving on motorways.","Not later than 10 days after registration."],"answer":["option_1"],"explanation":"A motor vehicle must be taxed before it may be taken on the road, and it must always display an up-to-date tax disc."},{"id":"201","category_id":"2","question":"If a vehicle is being driven by someone who is not the owner but has the owner’s consent, who should ensure that the driver is properly insured?","img":"","options":["The insurance company.","The driver and the vehicle owner.","The vehicle owner only.","The driver only."],"answer":["option_2"],"explanation":"All drivers must have insurance covering them to drive a vehicle on a public road. It is a serious offence to drive a vehicle that is not insured. It is also an offence to allow a vehicle that you own to be driven by an uninsured driver."},{"id":"202","category_id":"2","question":"Is a driver still insured to drive their vehicle after their insurance policy has expired?","img":"","options":["The driver is insured up to 7 days after the expiry of the policy.","The driver is not insured after the expiry of the policy.","The driver is insured up to 14 days after the expiry of the policy.","The driver is insured up to 10 days after the expiry of the policy."],"answer":["option_2"],"explanation":"All drivers must have insurance covering them to drive a vehicle on a public road. The vehicle must display an up-to-date insurance disc."},{"id":"203","category_id":"2","question":"If a driver wishes to drive another privately-owned vehicle but they are uncertain if they are insured to drive that vehicle, what should they do?","img":"","options":["A driver should contact their own insurer to confirm whether or not their insurance policy covers the driving of other vehicles.","Drive if there is an insurance disc on the vehicle.","Transfer the insurance disc from their own vehicle on to the vehicle they wish to drive.","Drive it provided that they tell their insurance company within 10 days and agree to pay any additional premium."],"answer":["option_1"],"explanation":"If you are in any doubt about your insurance cover, you should discuss the matter with your insurance company. It is a serious offence to drive without insurance."},{"id":"204","category_id":"2","question":"When a driver wishes to drive a vehicle and they are not sure if they are covered by insurance, what should they do?","img":"","options":["They should check with their local Motor Taxation Office to see if they are insured.","They should check with their local Garda station to see if they are insured.","They should not drive until their insurance company confirms that they are insured.","They should check with their local NDLS office to see if they are insured."],"answer":["option_3"],"explanation":"If you are in any doubt about your insurance cover, you should discuss the matter with your insurance company. It is a serious offence to drive without insurance."},{"id":"205","category_id":"2","question":"What is the minimum insurance cover a driver needs to drive on a public road?","img":"","options":["Third party.","Third party, fire and theft.","Comprehensive.","Personal accident."],"answer":["option_1"],"explanation":"As a motorist, you must have a minimum of third party insurance."},{"id":"206","category_id":"2","question":"If a driver passes their test using a vehicle with automatic transmission, which vehicles are they licensed to drive?","img":"","options":["Only manual vehicles in the licence category.","All vehicles in the licence category.","All vehicles in the licence category but only automatic vehicles on a motorway.","Only automatic vehicles in the licence category."],"answer":["option_4"],"explanation":"If you pass your driving test in an automatic or adapted vehicle, your full licence will apply to that type of vehicle only. A licence restricted to automatic vehicles will have a code 78 indicated in the restrictions/information column of the licence."},{"id":"207","category_id":"2","question":"Which vehicle is exempt from speed limits when being used in an emergency?","img":"","options":["Doctor on call.","Fire Brigade.","Breakdown recovery.","Mountain rescue."],"answer":["option_2"],"explanation":"In the course of their duty Gardaí, Fire Brigade and Ambulance personnel are exempt from some traffic laws including speed limits, as long as they do not put other road users in danger. If you hear or see a Garda or emergency vehicle approaching under emergency conditions, be extra careful and give way, if it is safe to do so."},{"id":"208","category_id":"2","question":"Where can drivers locate the Maximum Authorised Mass (MAM) of their vehicle?","img":"","options":["On a metal plate on the vehicle.","On the tax disc.","On the NCT disc.","On the insurance disc."],"answer":["option_1"],"explanation":"The plate displaying the Maximum Authorised Mass (MAM) of a vehicle is normally located under the bonnet or in the passenger compartment. If you are not sure where it is located on your vehicle, check the driver’s handbook supplied with the vehicle."},{"id":"209","category_id":"2","question":"Which vehicle is exempt from speed limits when being used in an emergency?","img":"","options":["Mountain rescue.","Doctor on call.","Breakdown recovery.","Ambulance."],"answer":["option_4"],"explanation":"In the course of their duty Gardaí, Fire Brigade and Ambulance personnel are exempt from some traffic laws including speed limits, as long as they do not put other road users in danger. If you hear or see a Garda or emergency vehicle approaching under emergency conditions, be extra careful and give way, if it is safe to do so."},{"id":"210","category_id":"2","question":"Which vehicle is exempt from speed limits when being used in an emergency?","img":"","options":["Garda.","Breakdown recovery.","Mountain rescue.","Doctor on call."],"answer":["option_1"],"explanation":"In the course of their duty Gardaí, Fire Brigade and Ambulance personnel are exempt from some traffic laws including speed limits, as long as they do not put other road users in danger. If you hear or see a Garda or emergency vehicle approaching under emergency conditions, be extra careful and give way, if it is safe to do so."},{"id":"211","category_id":"2","question":"What does this sign mean?","img":"a_Xbmea.png","options":["Traffic queues likely ahead.","Three vehicles may queue ahead.","Parking for works vehicles on left.","Steep incline ahead."],"answer":["option_1"],"explanation":"This roadworks warning sign tells you that there may be traffic queues ahead, possibly due to temporary traffic lights at the works. Proceed with caution."},{"id":"212","category_id":"2","question":"What does this sign mean?","img":"a_YCEAO.png","options":["Uneven surface.","Soft margin on left.","Parking on left only.","Slippery surface."],"answer":["option_1"],"explanation":"This roadworks warning sign tells you that the road surface may be uneven, possibly due to the resurfacing of part of a lane. Proceed with caution."},{"id":"213","category_id":"2","question":"Where should L plates be displayed on cars?","img":"","options":["On the front only.","On the rear only.","Both front and rear.","On the driver’s side only."],"answer":["option_3"],"explanation":"The holder of a learner permit must display L plates on the front and rear of their car at all times when driving on public roads."},{"id":"214","category_id":"2","question":"How would a driver calculate the maximum overall permitted weight of their vehicle?","img":"","options":["By calculating the unladen weight of the vehicle plus the weight of the fuel.","By adding the unladen weight of the vehicle to the load permitted to be carried.","By checking the unladen weight of the vehicle.","By checking the weight of the load which may be carried."],"answer":["option_2"],"explanation":"The maximum permitted weight of a vehicle is the sum of the unladen weight of the vehicle plus the maximum load that may be carried in it. It is an offence to overload a vehicle, as it reduces your ability to control it effectively."},{"id":"215","category_id":"2","question":"What is the Maximum Authorised Mass (MAM) of a car that may be driven by the holder of a Category B driving licence?","img":"","options":["3,000 kilograms.","4,000 kilograms.","3,500 kilograms.","3,750 kilograms."],"answer":["option_3"],"explanation":"The holder of a Category B driving licence is not permitted to drive a vehicle with a MAM of more than 3,500 kg. This restriction is noted on the licence."},{"id":"216","category_id":"2","question":"What is the maximum number of passengers that may be carried in a vehicle driven by the holder of a Category B driving licence?","img":"","options":["9 passengers.","10 passengers.","7 passengers.","8 passengers."],"answer":["option_4"],"explanation":"The holder of a Category B driving licence is not permitted to drive a vehicle that has seating for more than 8 passengers excluding the driver."},{"id":"217","category_id":"2","question":"When can the holder of a Category W learner permit carry a passenger?","img":"","options":["Only when the passenger also holds a Category W driving licence and the vehicle is designed to carry a passenger.","Only when the passenger holds a Category AM driving licence.","Only when the passenger also holds a Category W driving licence.","Only when the passenger holds a Category AM driving licence and the vehicle is designed to carry a passenger."],"answer":["option_1"],"explanation":"The holder of a Category W learner permit may carry a passenger in the vehicle only if: The vehicle is designed to take a passenger, and the passenger has held a full driving licence in Category W for two or more years."},{"id":"218","category_id":"2","question":"Is a driver allowed to use rebated (green) diesel fuel in a car on a public road?","img":"","options":["Green diesel may be used in a car only in winter months.","Green diesel may be used in a car only if the car is a taxis.","Green diesel may never be used in a car.","Green diesel may be used in a car only in summer months."],"answer":["option_3"],"explanation":"If, in its normal use, a vehicle is used on a public road, it must use unmarked (white) diesel, as the appropriate excise duties are included in the purchase price. Drivers can be prosecuted for using green diesel in a vehicle on a public road."},{"id":"219","category_id":"2","question":"When must a tractor or works vehicle be fitted with a rear-view mirror?","img":"","options":["A rear-view mirror is not required in a tractor or works vehicle.","A rear-view mirror must be fitted only when towing a trailer over 8 metres long.","A rear-view mirror must always be fitted.","A rear-view mirror must be fitted only when towing a trailer."],"answer":["option_3"],"explanation":"All vehicles used on a public road must have a rear-view mirror. The mirror should be used to enable the driver to see the traffic and road conditions behind and to each side."},{"id":"220","category_id":"2","question":"What is the maximum gross weight of a vehicle that may be driven by the holder of a Category B driving licence?","img":"","options":["3,450 kilograms","3,250 kilograms","3,000 kilograms","3,500 kilograms"],"answer":["option_4"],"explanation":"The holder of a Category B driving licence is not permitted to drive a vehicle with a design gross vehicle weight of more than 3,500 kg. This restriction is noted on the licence."},{"id":"221","category_id":"2","question":"What does this sign mean?","img":"a_wAzxZ.png","options":["The driver must stop for school crossing ahead.","The driver must stop their vehicle.","The driver must give way to traffic coming from the right."],"answer":["option_2"],"explanation":"This sign appears at junctions where a minor road joins a major road. You must stop your vehicle completely at a STOP sign."},{"id":"222","category_id":"2","question":"What must a driver do when this sign is accompanied by a white stop line on the road?","img":"a_BlcqL.png","options":["Stop at the line only if you see traffic approaching.","Stop past the line.","Stop at the line."],"answer":["option_3"],"explanation":"When accompanied by a STOP sign, the white stop line indicates the point at which you must stop your vehicle."},{"id":"223","category_id":"2","question":"What does this sign mean?","img":"a_XQj6T.png","options":["No height restriction ahead.","No entry ahead.","Cul-de-sac ahead."],"answer":["option_2"],"explanation":"This sign tells you that you must not proceed in the direction of the arrow. This is displayed to prevent traffic going in the wrong direction – for example, the wrong way up a one-way street."},{"id":"224","category_id":"2","question":"What does this sign mean?","img":"a_eE3PQ.png","options":["No right turn.","Cul-de-sac to the right.","Turn right only."],"answer":["option_1"],"explanation":"This sign is displayed at a junction where you must not turn right."},{"id":"225","category_id":"2","question":"What does this sign mean?","img":"a_7Yb2t.png","options":["Maximum speed is 30 km/h.","Minimum speed is 30 km/h.","Speed limit continues for 30 kilometres."],"answer":["option_1"],"explanation":"This sign tells you that the maximum legal speed limit permitted for this section of road is 30 km/h. These signs are commonly found in slow zones in residential areas."},{"id":"226","category_id":"2","question":"What does this sign mean?","img":"a_QAP1T.png","options":["Speed limit continues for 50 kilometres.","Minimum speed is 50 km/h.","Maximum speed is 50 km/h."],"answer":["option_3"],"explanation":"This sign tells you that the maximum legal speed limit permitted for this section of road is 50 km/h."},{"id":"227","category_id":"2","question":"What does this sign mean?","img":"a_lx8SC.png","options":["Minimum speed is 60 km/h.","Maximum speed is 60 km/h.","Speed limit continues for 60 metres."],"answer":["option_2"],"explanation":"This sign tells you that the maximum legal speed limit permitted for this section of road is 60 km/h."},{"id":"228","category_id":"2","question":"What does this sign mean?","img":"a_vtEsA.png","options":["Speed limit continues for 80 metres.","Maximum speed is 80 km/h.","Minimum speed is 80 km/h."],"answer":["option_2"],"explanation":"This sign tells you that the maximum legal speed limit permitted for this section of road is 80 km/h."},{"id":"229","category_id":"2","question":"What does this sign mean?","img":"a_uhTac.png","options":["Minimum speed is 100 km/h.","Maximum speed is 100 km/h.","Speed limit continues for 100 metres."],"answer":["option_2"],"explanation":"This sign tells you that the maximum legal speed limit permitted for this section of road is 100 km/h."},{"id":"230","category_id":"2","question":"What does this sign mean?","img":"a_O0nJM.png","options":["Parking is not allowed.","Private vehicles parking only.","Public service vehicles parking only."],"answer":["option_1"],"explanation":"This sign tells you that parking is prohibited in both directions."},{"id":"231","category_id":"2","question":"What does this sign mean?","img":"a_aTRB6.png","options":["Stop and wait for green light before proceeding.","The driver must stop when red lights show.","Stop and wait for amber light before proceeding."],"answer":["option_2"],"explanation":"This sign gives advance warning that you must stop when red lights show. This sign may be displayed at a railway level crossing."},{"id":"232","category_id":"2","question":"What does this hand signal mean?","img":"a_BaRXc.png","options":["The cyclist intends to turn right.","The cyclist intends to stop.","The cyclist intends to turn left."],"answer":["option_3"],"explanation":"This hand signal informs other road users that the cyclist intends to make a left-hand turn."},{"id":"233","category_id":"2","question":"What does this traffic light mean?","img":"a_s9Kmu.png","options":["The driver must stop and wait until the full green light appears.","The driver may proceed in the direction of the green arrow if the way is clear.","The driver must divert to the right."],"answer":["option_2"],"explanation":"A green arrow (filter light) means that traffic may proceed in the direction of the arrow if it is safe to do so."},{"id":"234","category_id":"2","question":"What does this traffic light mean?","img":"a_oyMwb.png","options":["Traffic must proceed if safe to do so.","Traffic may stop if safe to do so.","Traffic must stop at the traffic light."],"answer":["option_3"],"explanation":"A red light means STOP. You must not go beyond the stop line or (if there is no stop line) beyond the light."},{"id":"235","category_id":"2","question":"What road users must comply with traffic lights (including pedestrian lights)?","img":"","options":["All road users.","Drivers and cyclists only.","Drivers and pedestrians only."],"answer":["option_1"],"explanation":"All road users including pedestrians must comply with traffic controls. Drivers should be aware that traffic lights and pedestrian lights can be combined at junctions and should show caution and consideration to pedestrians."},{"id":"236","category_id":"2","question":"What does this sign mean?","img":"a_qM4qj.png","options":["Slippery road up ahead.","Uneven surface on left.","Loose chippings on road."],"answer":["option_3"],"explanation":"This roadworks warning sign tells you that the road ahead has been resurfaced and there may be loose chippings. You should reduce speed while driving through this area as the loose chippings could affect your vehicle’s road holding and braking."},{"id":"237","category_id":"2","question":"When must the holder of a learner permit display L plates on their car?","img":"","options":["When driving unaccompanied by a full licence holder.","When driving on their first learner permit.","At all times when driving."],"answer":["option_3"],"explanation":"The holder of a learner permit must display L plates on the front and rear of their car at all times when driving on public roads."},{"id":"238","category_id":"2","question":"When can a child under the age of sixteen drive a tractor on a public road?","img":"","options":["Children under 16 are not allowed to drive a tractor on a public road.","A child under 16 is allowed to drive a tractor on a public road when they hold a learner permit.","A child under 16 is allowed to drive a tractor on a public road when accompanied by a fully licensed driver."],"answer":["option_1"],"explanation":"Persons under 16 years of age are not permitted to drive a tractor in a public place."},{"id":"239","category_id":"2","question":"What does this sign mean?","img":"a_EkbLb.png","options":["Pass on the left.","Steep decline to the left.","Keep left."],"answer":["option_3"],"explanation":"This sign tells you that you must keep left. It is usually displayed at a traffic island in the centre of the road and also used on occasion to control traffic at roadworks."},{"id":"240","category_id":"2","question":"What does this sign mean?","img":"a_AohiP.png","options":["Steep decline from the left.","Traffic crossing from the left.","Keep right."],"answer":["option_3"],"explanation":"This sign tells you that you must keep right. It is usually found in a one-way system where the traffic is required to keep to the right and also used on occasion to control traffic at roadworks."},{"id":"241","category_id":"2","question":"What does this sign mean?","img":"a_fvBGF.png","options":["No right turn.","Turn right ahead.","Dangerous bend to the right ahead."],"answer":["option_1"],"explanation":"This sign is displayed at a junction where you may not turn right."},{"id":"242","category_id":"2","question":"What does this sign mean?","img":"a_jhjIT.png","options":["No left turn.","Turn right only.","No right turn."],"answer":["option_1"],"explanation":"This sign is displayed at a junction where you may not turn left."},{"id":"243","category_id":"2","question":"What does this sign mean?","img":"a_xr8b5.png","options":["Traffic merging at 120 metres ahead.","Minimum speed is 120 km/h.","Maximum speed is 120 km/h."],"answer":["option_3"],"explanation":"This sign tells you that the maximum legal speed limit permitted for this section of road is 120 km/h."},{"id":"244","category_id":"2","question":"What does this sign mean?","img":"a_zRzjW.png","options":["Parking prohibited at the times shown.","Parking permitted during the times shown.","Maximum parking for one hour during times shown."],"answer":["option_2"],"explanation":"These signs tells you that parking is permitted in both directions, but only at the times shown on the information plate."},{"id":"245","category_id":"2","question":"What does this sign mean?","img":"a_TlDQE.png","options":["Road closed during the times shown.","Pedestrianised street - no access for vehicles.","Clearway - no stopping or parking during the times shown."],"answer":["option_3"],"explanation":"A clearway sign means that stopping or parking is not permitted in this area during the times shown on the information plate."},{"id":"246","category_id":"2","question":"What does this sign mean?","img":"a_UmZXI.png","options":["Roads closed ahead to both left and right.","Cul-de-sac to both left and right.","Staggered crossroads ahead with roads of equal importance."],"answer":["option_3"],"explanation":"This sign gives advance warning of a staggered junction ahead with roads to the left and right. Be aware that vehicles may be emerging from these roads."},{"id":"247","category_id":"2","question":"What does this sign mean?","img":"a_FRZEb.png","options":["Dual carriageway ends.","Road narrows ahead.","Tunnel ahead."],"answer":["option_1"],"explanation":"This sign gives advance warning of the end of a dual carriageway. You will soon be entering a 2-way road."},{"id":"248","category_id":"2","question":"What does this sign mean?","img":"a_lxO7c.png","options":["Three lanes ahead.","Crossing traffic ahead.","Three hundred meters to the next exit."],"answer":["option_3"],"explanation":"This is a motorway information sign that tells you that the next exit off the motorway is 300 metres ahead."},{"id":"249","category_id":"2","question":"What does this sign mean?","img":"a_fuZv8.png","options":["100 metres to the next exit.","Sharp descent for 100 metres.","Low bridge ahead."],"answer":["option_1"],"explanation":"This is a motorway information sign that tells you that the next exit off the motorway is 100 metres ahead."},{"id":"250","category_id":"2","question":"What does this hand signal mean?","img":"a_bkx6G.png","options":["The cyclist intends to stop.","The cyclist intends to cross the road.","The cyclist intends to turn left."],"answer":["option_3"],"explanation":"This hand signal informs other road users that the cyclist intends to turn left."},{"id":"251","category_id":"2","question":"What does this Garda signal mean?","img":"a_1maSm.png","options":["Stop if approaching from the front.","Stop if approaching from behind.","Proceed if approaching from the front."],"answer":["option_1"],"explanation":"When approaching a Garda giving this signal you must stop."},{"id":"252","category_id":"2","question":"What does this road marking indicate?","img":"a_ELMTw.png","options":["Traffic calming.","Pedestrian island.","Zebra crossing."],"answer":["option_3"],"explanation":"A zebra crossing is a designated area for pedestrians to cross the road. As a driver you must always yield to pedestrians on a zebra crossing."},{"id":"253","category_id":"2","question":"What is the maximum speed allowed for cars and motorcycles on motorways?","img":"","options":["80 km/h.","100 km/h.","120 km/h.","60 km/h."],"answer":["option_3"],"explanation":"It is illegal to exceed 120 km/h when driving on a motorway."},{"id":"254","category_id":"2","question":"Unless otherwise indicated, what is the maximum speed allowed for cars or motorcycles on national roads?","img":"","options":["100 km/h.","80 km/h.","60 km/h.","120 km/h."],"answer":["option_1"],"explanation":"It is illegal to exceed 100 km/h when driving on a single carriageway national road."},{"id":"255","category_id":"2","question":"Unless otherwise indicated, what is the maximum speed allowed for a car towing a caravan on national roads?","img":"","options":["120 km/h.","60 km/h.","80 km/h.","100 km/h."],"answer":["option_3"],"explanation":"When towing a caravan on a national road, it is illegal to exceed 80 km/h – excessive speed will make such a vehicle unstable."},{"id":"256","category_id":"2","question":"Unless otherwise indicated, what is the maximum speed allowed for a car towing a caravan on a motorway?","img":"","options":["90 km/h.","80 km/h.","120 km/h.","100 km/h."],"answer":["option_2"],"explanation":"When towing a caravan on a motorway it is illegal to exceed 80 km/h – excessive speed will make such a vehicle unstable."},{"id":"257","category_id":"2","question":"Unless otherwise indicated, what is the maximum speed allowed for a car towing a trailer on a motorway?","img":"","options":["60 km/h.","100 km/h.","80 km/h.","120 km/h."],"answer":["option_3"],"explanation":"When towing a trailer on a motorway it is illegal to exceed 80 km/h – excessive speed will make such a vehicle unstable."},{"id":"258","category_id":"2","question":"Who is authorized to see a driver’s vehicle registration document?","img":"","options":["A member of the car recovery company or anyone assisting in the recovery.","A Garda may ask you to produce the vehicle’s registration document at a named Garda station.","Any Fire Brigade or Ambulance personnel at the scene of a collision the driver has been involved in.","Any person with whom the driver is involved in a collision."],"answer":["option_2"],"explanation":"A Garda may demand to see your driving licence at any time, and you should always carry this with you when driving. A Garda may also examine your insurance disc, tax disc and NCT disc (if applicable). A Garda may ask you to produce other documents (including the vehicle’s registration document) at a named Garda station within 10 days."},{"id":"259","category_id":"2","question":"What does this sign mean?","img":"a_s7I6f.png","options":["Straight ahead only.","Height restriction ahead.","Motorway ahead."],"answer":["option_1"],"explanation":"This sign tells you that you must proceed straight ahead. This sign is usually displayed on the entry to a one-way street."},{"id":"260","category_id":"3","question":"What effect does carrying a load have on a vehicle’s braking ability?","img":"","options":["It increases the efficiency of the brakes.","It increases the distance required to stop.","It reduces the distance required to stop.","It has no effect provided the brakes are good."],"answer":["option_2"],"explanation":"When driving a vehicle which is carrying a load, the driver should be aware that the forces acting on the vehicle will increase the distance required to stop. The driver should allow for this by increasing the distance from the vehicle in front."},{"id":"261","category_id":"3","question":"What effect does towing a loaded trailer have on stopping ability?","img":"","options":["It increases the efficiency of the brakes.","It reduces the stopping distance.","It increases the stopping distance.","It has no effect on stopping distance."],"answer":["option_3"],"explanation":"If you are towing a loaded trailer, you need to be aware that your braking distance could be considerably greater, depending on the weight and size of the trailer. The driver should allow for this by increasing the distance from the vehicle in front."},{"id":"262","category_id":"3","question":"Which of the following statements is true in relation to tyre pressure and driving on a motorway?","img":"","options":["The driver should increase the rear tyre pressure in order to cope with sustained high speed.","The driver should reduce tyre pressure because high speeds will cause them to heat up.","The driver should ensure that tyre pressure is correct, in line with the manufacturer’s recommendations.","The driver should increase the front tyre pressure in order to cope with sustained high speed."],"answer":["option_3"],"explanation":"The driver should ensure that the tyre pressure of their vehicle is correct at all times. Correct tyre pressure is especially important when travelling long distances, on motorways and at speed."},{"id":"263","category_id":"3","question":"What should a driver do when involved in an incident where nobody is injured but the vehicles are causing a danger or obstruction on the road?","img":"","options":["Halt all traffic until it has been established who is at fault.","Take care when moving damaged vehicles and make every effort to warn other traffic.","Move all passengers and put a red warning triangle on the road.","Wait for the Gardaí to arrive before moving the vehicles."],"answer":["option_2"],"explanation":"In a collision where nobody is injured and there is only minor damage to vehicles, the vehicles should be moved to the side of the road to ensure that they do not cause an obstruction or endanger other road users."},{"id":"264","category_id":"3","question":"What should a driver do if involved in an incident where there is damage to property only?","img":"","options":["There is no need to report the incident if there is no damage to the vehicle.","It is only necessary to report the incident to the Gardaí within 10 days.","It is not necessary to report it to the Gardaí provided it has been reported to the property owner.","Report the incident both to the property owner and the Gardaí within 48 hours."],"answer":["option_3"],"explanation":"If the incident causes damage to property only and there is a Garda present, it must be reported to the Garda. If there is no Garda present, the owner or the person in charge of the property must be informed. If neither are present then the relevant information must be provided at a Garda station as soon as possible."},{"id":"265","category_id":"3","question":"What should a driver do where a person has been injured in a collision?","img":"","options":["Move the victim only if there is a risk of fire or further injury.","Always move the victim and the vehicles.","Move the victim to the side of the road.","Move the vehicles out of the way to avoid causing obstruction."],"answer":["option_1"],"explanation":"Never move an injured person at the scene of a collision unless there is a risk of fire or further injury. Moving an injured person could add to their injuries. Trained personnel know best how to attend to injured persons. Call the emergency services (on 999 or 112) or make sure that someone else has called them."},{"id":"266","category_id":"3","question":"What type of drink should be given to a person who has been injured in a collision?","img":"","options":["A hot drink.","A cold drink.","A non-alcoholic drink.","No drink should be given."],"answer":["option_4"],"explanation":"A person who has been injured in a collision should not be given anything to drink, as this could cause them to choke. Ideally trained personnel should be consulted before attending to an injured person. Call the emergency services (on 999 or 112) or make sure that someone else has called them."},{"id":"267","category_id":"3","question":"What should a driver do to assist a person who is unconscious following a collision?","img":"","options":["Try to keep the person warm with a blanket or overcoat.","Move the person to the nearest hospital immediately.","Try and get the person to drink something warm.","Raise the person’s head and hold it in that position."],"answer":["option_1"],"explanation":"If a person is unconscious following a collision, a driver should try to keep them warm with a blanket or overcoat until the emergency services arrive. Call the emergency services (on 999 or 112) or make sure that someone else has called them."},{"id":"268","category_id":"3","question":"If a driver is involved in a serious collision with an uninsured motorist, where nobody is injured, who should it be reported to?","img":"","options":["The National Driver Licence Service (NDLS).","The local Motor Taxation Office.","The Irish Insurance Federation.","The driver’s insurance company and the Gardaí."],"answer":["option_4"],"explanation":"If you are involved in a serious collision, you should always report it to the Gardaí and to your insurance company."},{"id":"269","category_id":"3","question":"What should a driver do if involved in a collision with another vehicle where nobody is injured?","img":"","options":["Submit a written report to the Insurance Bureau of Ireland.","Give their name and address only to the other person.","Exchange all relevant details with the other driver.","Exchange no details but report the incident to the Gardaí."],"answer":["option_3"],"explanation":"If a you are involved in a collision with another vehicle where nobody is injured, you should exchange all the relevant details with the other driver – including name, address, vehicle registration, make and model and all insurance details."},{"id":"270","category_id":"3","question":"What should a driver do if they arrive at the scene of a collision involving a vehicle carrying hazardous materials?","img":"","options":["Keep well clear and call the emergency services.","Try to move the vehicle to a safe place.","Contact the haulage company who own the vehicle.","Try to prevent any further leakage of hazardous materials before raising the alarm."],"answer":["option_1"],"explanation":"If a driver arrives at the scene of a collision involving a vehicle carrying hazardous materials, they should keep well clear of the scene. Call the emergency services on 999 or 112 and give them as much information as you can about the marking labels on the vehicle. You should also warn other road users about the danger. Allow the emergency services to do any rescuing."},{"id":"271","category_id":"3","question":"How does the driver know the vehicle’s total load-carrying capacity?","img":"","options":["By referring to the vehicle manufacturer’s specification.","By measuring the size of the boot.","By counting the number of seats.","By checking the horse power of the engine."],"answer":["option_1"],"explanation":"Design Gross Vehicle Weight is the term used by manufacturers for the weight of the vehicle together with the maximum load it is designed to carry. Drivers must understand the carrying capacity of their vehicle. Overloading your vehicle will make it more difficult to control, and its an offence."},{"id":"272","category_id":"3","question":"What determines the maximum allowed towing capacity of a vehicle?","img":"","options":["The size of the tyres on the vehicle.","The combined weight of the vehicle and its trailer.","The manufacturer’s specifications.","The strength of the tow bar."],"answer":["option_3"],"explanation":"The maximum weight that your vehicle can safely tow is specified by the manufacturer, and is usually set out in the driver’s handbook for the vehicle, and in some cases on a plate attached to the vehicle. This is the safe towing limit for the vehicle and you should not exceed it."},{"id":"273","category_id":"3","question":"What effect can overloading a vehicle have on its road-holding?","img":"","options":["Provided the load is evenly distributed, it improves the stability of the vehicle.","The load can make the vehicle more difficult to control.","The load can make the vehicle more difficult to control, but only when going downhill.","The load can make the vehicle more difficult to control, but only when reversing."],"answer":["option_2"],"explanation":"Overloading your vehicle will make it more difficult to control. Remember: It’s an offence to overload a vehicle."},{"id":"274","category_id":"3","question":"What would be the effect of overloading a vehicle with passengers or goods?","img":"","options":["It would improve the vehicle’s road-holding ability.","It would not have any effect provided speed is reduced.","Overloading will not reduce the ability to control the vehicle.","It would reduce the driver’s ability to control the vehicle."],"answer":["option_4"],"explanation":"Overloading your vehicle will make it more difficult to control, and will increase the risk of a collision."},{"id":"275","category_id":"3","question":"What effect could an unevenly distributed load have on a vehicle?","img":"","options":["It could make the vehicle unstable while turning.","It could cause the clutch to slip while accelerating.","It could cause the vehicle to overheat.","It could cause the gear box to overheat."],"answer":["option_1"],"explanation":"When loading a vehicle you should ensure that the load is distributed evenly. An unevenly distributed load may change the vehicle’s centre of gravity and this could affect the braking and steering."},{"id":"276","category_id":"3","question":"Why is it important to ensure that the vehicle headlights are correctly aligned?","img":"","options":["To increase the lifespan of the headlights.","To enable the driver to see properly.","To reduce battery consumption.","To enable the driver to drive faster in the dark."],"answer":["option_2"],"explanation":"A driver should ensure their headlights are properly aligned so as not to dazzle oncoming drivers and also to see properly themselves."},{"id":"277","category_id":"3","question":"In general, how frequently should a vehicle’s lights be checked?","img":"","options":["When wintertime approaches.","Daily before driving.","At major service intervals.","At minor service intervals."],"answer":["option_2"],"explanation":"A driver is responsible for their vehicle’s roadworthiness and they should check it daily before driving. Among the checks they should make are that all the lights are clean and in working order."},{"id":"278","category_id":"3","question":"What effect can a broken lens have on headlights?","img":"","options":["It can cause the bulb to overheat.","It can reduce and distort the beam.","It can increase the brightness of the beam in the other headlight.","It can cause other bulbs to blow if not fixed immediately."],"answer":["option_2"],"explanation":"A driver is responsible for their vehicle’s roadworthiness and they should check it at regular intervals. Among the checks they should make are that all the lights are in working order. If they find defects in the lights, such as a broken lens, they should have them repaired or replaced as soon as possible."},{"id":"279","category_id":"3","question":"A driver wishes to drive at night, but the offside (right-hand side) headlight bulb is blown. What should the driver do?","img":"","options":["Not drive until the bulb is replaced.","Replace it temporarily with the brake-light bulb.","Drive with the hazard lights on.","Replace it temporarily with the nearside (left-hand side) bulb."],"answer":["option_1"],"explanation":"A driver is responsible for their vehicle’s roadworthiness and they should check it at regular intervals. Drivers must not drive on the road unless their vehicle’s headlights are in good working order, adjusted properly and clean."},{"id":"280","category_id":"3","question":"How would a driver know that a brake-light bulb is not working?","img":"","options":["They would notice the brake pedal become firmer under pressure.","They would notice the brake pedal getting softer under pressure.","By standing at the rear of the vehicle and checking as another person presses the brake pedal.","By standing at the rear of the vehicle and getting another person to turn on side lights."],"answer":["option_3"],"explanation":"In order for a driver to know that the rear brake lights are working correctly, they should stand at the rear of the vehicle and check that the brake lights come on while another person presses the brakes."},{"id":"281","category_id":"3","question":"What does this light mean?","img":"a_8rEaj.png","options":["The gear box is over-heating.","The oil level is too low.","The engine is over-heating.","The battery is not charging."],"answer":["option_4"],"explanation":"If the battery warning light comes on whilst driving, it means there is some kind of problem with the electrical charging system of the vehicle and the battery is not being charged properly. The driver should get this checked by a professional as soon as possible. It is important to understand the meaning of your vehicle’s warning lights, information on which can be found in the vehicle’s handbook."},{"id":"282","category_id":"3","question":"What does this light mean?","img":"a_cnS5D.png","options":["The high-beam headlights are switched on.","The reversing light is switched on.","The headlight beam should be dipped.","The number plate light is faulty."],"answer":["option_1"],"explanation":"All vehicles are fitted with warning lights to alert the driver to different things. This light comes on when the full beam headlights are turned on. It is important to understand the meaning of your vehicle’s warning lights, information on which can be found in the vehicle’s handbook."},{"id":"283","category_id":"3","question":"What does this light mean?","img":"a_XkmoA.png","options":["Low engine oil level.","Low engine coolant level.","Low brake fluid level.","Low battery fluid level."],"answer":["option_1"],"explanation":"If the engine oil warning light comes on, it means that the engine oil level/pressure has dropped. You should not drive the vehicle until the problem is fixed. If the light comes on while driving, pull over and stop in a safe place as soon as possible. It is important to understand the meaning of your vehicle’s warning lights, information on which can be found in the vehicle’s handbook."},{"id":"284","category_id":"3","question":"What does this light mean?","img":"a_GqJLI.png","options":["Right-hand fog light on.","Directional indicator on.","Brake light bulb blown.","Headlight bulb blown."],"answer":["option_2"],"explanation":"All vehicles are fitted with warning lights to alert you to different things. This light tells you that the directional indicator is on. If this light is still on after you have completed your manoeuvre, cancel it to avoid misleading other road users. It is important to understand the meaning of your vehicle’s warning lights, information on which can be found in the vehicle’s handbook."},{"id":"285","category_id":"3","question":"What should a driver do if a system warning light lights up on the dashboard of their vehicle whilst driving?","img":"","options":["Continue for a distance to see if the light goes out.","Continue to drive and listen for any unusual sounds.","Carry on and check the problem later.","Stop and check the problem."],"answer":["option_4"],"explanation":"If a system warning light lights up while you are driving, you should stop in a safe place as soon as possible and investigate the problem before deciding what action to take. It is important to understand the meaning of your vehicle’s warning lights, information on which can be found in the vehicle’s handbook."},{"id":"286","category_id":"3","question":"What should a driver do if a red system warning light lights up on the dashboard of their vehicle?","img":"","options":["Continue on and see if it goes out.","Stop and investigate the cause.","Drive to the nearest garage and have it checked.","Continue on and listen for any unusual sounds."],"answer":["option_2"],"explanation":"If a red system warning light comes on while you are driving, you should stop in a safe place as soon as possible and investigate the problem before deciding what action to take. It is important to understand the meaning of your vehicle’s warning lights, information on which can be found in the vehicle’s handbook."},{"id":"287","category_id":"3","question":"What is the purpose of the red reflectors at the rear of a vehicle?","img":"","options":["They warn the driver behind to switch to main beam.","They reflect light at night to make other road users aware of the vehicle.","They warn pedestrians of the vehicle’s location.","They are a substitute in case of brake-light failure."],"answer":["option_2"],"explanation":"Motor vehicles are fitted with red reflectors to make it easier to be seen by other road users. Drivers should keep reflectors clean, intact and check them by shining a light on them to make sure that they are working effectively. Whilst driving, drivers should be cautious as red reflectors may be an indication of both parked/stationery or moving vehicles ahead."},{"id":"288","category_id":"3","question":"If, when driving along, the driver notices that the engine power is lower than normal, what should they do?","img":"","options":["Switch to a different fuel.","Have the vehicle checked by a competent person.","Replace the engine oil filter.","Adjust the fuel mixture control mechanism."],"answer":["option_2"],"explanation":"If the driver notices that the vehicle seems underpowered when driving, this could present a number of problems, e.g. lack of power when overtaking. The driver should have it checked by a competent person as soon as possible as there may be a number of causes, some of which may deteriorate further."},{"id":"289","category_id":"3","question":"While driving, the driver notices the vehicle temperature gauge showing red. What should they do?","img":"","options":["Stop in a safe place and have the problem investigated.","Drive to the nearest service depot and top-up the water in the radiator.","Remove the filler cap from the radiator and check for leakage.","Do not drive until an anti-waxing agent is added to the coolant."],"answer":["option_1"],"explanation":"Many vehicles are fitted with various warning lights and gauges. A warning light or a red zone on a temperature gauge means the engine is starting to overheat and the vehicle should not be driven until the problem is rectified. Refer to the vehicle handbook for further information and guidance or seek advice from a competent person."},{"id":"290","category_id":"3","question":"What should a driver do if they notice steam rising from the engine compartment?","img":"","options":["Remove the filler cap from the coolant bottle.","Increase speed to increase the air flow into the engine compartment.","Stop where safe and investigate the cause.","Top up with anti-freeze immediately."],"answer":["option_3"],"explanation":"If a driver notices steam rising from the engine compartment of their vehicle, they should stop where safe and only investigate the cause once it has cooled down. Do not remove a radiator or header tank cap when the engine is hot. Steam rising from the engine is an indication that the engine is overheating and it should not continue to be driven. Refer to the vehicle handbook for further information and guidance or seek advice from a competent person."},{"id":"291","category_id":"3","question":"If a driver notices that structural parts of their vehicle’s body have been affected by rust, what should they do?","img":"","options":["Have paint sprayed over it of the same colour.","Have it repaired by a competent repair shop.","Have it sandpapered and keep the affected area dry.","Treat the area with grease and paint over it."],"answer":["option_2"],"explanation":"Over time vehicles may become affected by rust to various degrees. Drivers should inspect their vehicles periodically and if they find signs of rust they should have it assessed and repaired if necessary to prevent further deterioration. A weakened vehicle structure may have serious consequences in the event of a collision."},{"id":"292","category_id":"3","question":"After changing a wheel on a vehicle, which of the following should be checked soon afterwards?","img":"","options":["The wheel nuts.","The tyre tread depth.","The air valve.","The brake pad clearance."],"answer":["option_1"],"explanation":"After changing a wheel on a vehicle it is recommended to check the wheel nuts after a short period of driving to ensure they are still properly secured."},{"id":"293","category_id":"3","question":"In general, how often should a driver check the tyre pressure of a vehicle?","img":"","options":["Monthly.","Six monthly.","Annually.","Regularly."],"answer":["option_4"],"explanation":"Drivers have a legal responsibility to make sure that their vehicle is roadworthy. To do this, they should carry out regular, weekly and periodic checks, including a weekly tyre pressure check. Incorrectly inflated tyres may cause vehicle instability, uneven tyre wear and longer stopping distances."},{"id":"294","category_id":"3","question":"What is the main reason for maintaining the correct tyre pressures?","img":"","options":["To help provide optimum road holding.","To reduce engine wear.","To stop the vehicle from sloping to the left.","To help maintain the correct ground clearance."],"answer":["option_1"],"explanation":"The vehicle manufacturer specifies the pressure to which tyres on a vehicle should be inflated. This is the pressure that gives the best performance in road holding, efficient braking and fuel consumption. Some manufacturers specify different pressures for front and rear tyres."},{"id":"295","category_id":"3","question":"A fault in which component may lead to uneven or excessive tyre wear?","img":"","options":["Clutch.","Suspension.","Accelerator.","Gearbox."],"answer":["option_2"],"explanation":"If a vehicle has a worn suspension it may lead to uneven or excessive tyre wear. If drivers notice that their tyres are unevenly worn, they should investigate the reason and have it repaired by a competent person."},{"id":"296","category_id":"3","question":"What can be affected by driving on under-inflated tyres?","img":"","options":["Oil pressure.","The exhaust system.","Fuel consumption.","The coolant system."],"answer":["option_3"],"explanation":"Incorrect tyre pressure adversely affects many of a vehicle’s systems, including brakes, suspension and steering. In particular, under-inflated tyres can increase the vehicle’s fuel consumption. Check tyre pressures regularly and ensure they are inflated as per manufacturer’s recommendations."},{"id":"297","category_id":"3","question":"When should tyre pressure be checked?","img":"","options":["When the tyres are part-worn.","When the tyres are cold.","At service intervals only.","When the tyres are hot."],"answer":["option_2"],"explanation":"Drivers should check the tyre pressure in their vehicle at least once a week and before commencing a long journey. For accuracy, do this when the tyres are cold and using a reliable gauge. Tyres should always be inflated according to the vehicle manufacturer’s guidelines, information on which can be found in the vehicle handbook."},{"id":"298","category_id":"3","question":"During a weekly check, a driver notices a badly worn front tyre. What should the driver do?","img":"","options":["Have the worn tyre replaced.","Fit the worn tyre on one of the rear wheels.","Reduce speed when driving on wet roads.","Check the tyre pressure to ensure it remains constant."],"answer":["option_1"],"explanation":"The tyres are the vehicle’s only contact with the road, the area of contact is small and, if worn, will not grip properly and safely. The quality of the tyres on a vehicle is an important factor in the vehicle’s road holding and braking ability. Drivers should check their tyres regularly and if they notice that a tyre is badly worn, they should replace it immediately. Whilst the minimum legal tread depth for tyres on most vehicles is 1.6 mm (1 mm for motorcycles), drivers should replace a tyre before it becomes this worn."},{"id":"299","category_id":"3","question":"What does worn tread along the edge of the inside of a tyre suggest?","img":"","options":["Air pressure is high.","The vehicle has been driven too fast around corners.","Air pressure is low.","Steering alignment may be faulty."],"answer":["option_4"],"explanation":"If a driver notices the inside edge of the tyre is worn, this may indicate a problem with the steering alignment. This is a potentially dangerous problem, and should be fixed by a competent person as soon as possible. Failure to do so may result in a blow-out and loss of control of the vehicle."},{"id":"300","category_id":"3","question":"With regard to tyres, what should a driver do before starting a long journey?","img":"","options":["Check the tyres are inflated to normal air pressure.","Increase the air pressure in the tyres.","Reduce the air pressure in the tyres.","Reduce front tyre air pressure and increase rear tyre air pressure."],"answer":["option_1"],"explanation":"It is important to check the tyre pressure before starting a long journey as incorrect air pressure can adversely affect many of the vehicle’s systems, including brakes, steering, suspension and fuel consumption. Tyres should always be inflated according to the vehicle manufacturer’s guidelines, information on which can be found in the vehicle handbook."},{"id":"301","category_id":"3","question":"What should the driver do to secure the vehicle when changing a front nearside (left-hand side) wheel?","img":"","options":["Point the front wheels away from the kerb.","Ensure that the vehicle cannot roll when jacked up.","Ensure the gear lever is in neutral.","Point the front wheels towards the kerb."],"answer":["option_2"],"explanation":"If a driver has to change a front nearside (left-hand side) wheel, make sure to do it in a safe place on level ground. Take care, wear high-visibility vest/jacket, use a warning triangle and hazard warning lights as appropriate. The vehicle should be secured by applying the parking brake (handbrake), switching off the engine, engaging a low gear and using a wheel chock if necessary. If unfamiliar with how to change a wheel seek assistance from a competent person."},{"id":"302","category_id":"3","question":"What is the most common cause of heavy steering?","img":"","options":["Over-inflated tyres.","Badly worn brakes.","Under-inflated tyres.","Poorly oiled steering."],"answer":["option_3"],"explanation":"Heavy steering is when a driver needs to use more effort than usual to turn the steering wheel, this may be as a direct result of under-inflated tyres. Check your tyre pressures but be aware there may be other causes of heavy steering such as low power steering fluid level. Seek advice from a competent person and have this investigated immediately."},{"id":"303","category_id":"3","question":"Which of the following is a driver required to keep in good condition?","img":"","options":["Seatbelts.","Radio.","Paintwork.","Upholstery."],"answer":["option_1"],"explanation":"Drivers are responsible for their vehicles’ roadworthiness and should check them at regular intervals. Among the checks they should make are that all the seatbelts (drivers and passengers) are clean, untangled and in good working order."},{"id":"304","category_id":"3","question":"What should a driver do if condensation is affecting the vehicle’s windows?","img":"","options":["Drive for a few kilometres with a window open.","Make sure that all demister vents and windows are closed.","Wipe the windows with the back of the hand.","Dry the windows with a cloth and then use the demister system."],"answer":["option_4"],"explanation":"Make sure the windows are clear and clean at all times so that the driver can see the road and traffic conditions all around. Condensation on the window can seriously impair your ability to make proper observations. Drivers should familiarise themselves with how to correctly set the vehicle’s ventilation system in order to keep the windows clear."},{"id":"305","category_id":"3","question":"What should a driver do if the right-hand headlight bulb fails when driving at night?","img":"","options":["Drive with the hazard lights on.","Have the bulb replaced immediately.","Replace it temporarily with the left-hand headlight bulb.","Replace it temporarily with the brake light bulb."],"answer":["option_2"],"explanation":"Vehicles (except motorcycles) are required by law to have right and left headlights. Faulty lights should be repaired immediately. A vehicle with only one headlight can cause a hazard to other road users or be mistaken for a motorcycle."},{"id":"306","category_id":"3","question":"A driver has stalled in the middle of an unguarded level crossing and cannot restart the engine. The warning bell is ringing. What should the driver do?","img":"","options":["Stay at the vehicle and warn the approaching train.","Walk clear of the crossing and phone the signal operator so that trains can be stopped.","Push the vehicle clear of the crossing.","Try to restart the engine in first gear."],"answer":["option_2"],"explanation":"In this situation, the driver and all passengers should get out of the vehicle and immediately use the emergency phone at the crossing to contact the signal operator so that trains can be stopped. If necessary, warn other motorists. Do not return to the vehicle until instructed by the signal operator or emergency services."},{"id":"307","category_id":"3","question":"When attaching a trailer to their vehicle, what must a driver check?","img":"","options":["That the load is positioned to the rear of the trailer.","That the load is evenly spread.","That the load is positioned to the front of the trailer.","That the trailer has a spare wheel."],"answer":["option_2"],"explanation":"Proper weight distribution helps to ensure the stability of both the towing vehicle and the trailer. In the trailer, the bulk of the load should be over the axles. If a heavy load is positioned at the front of the trailer, this will result in too much nose weight on the hitch of the towing vehicle and make it difficult to steer. If a heavy load is positioned at the rear of the trailer, this will result in reduced weight on the rear axle of the towing vehicle, which will make it more unstable."},{"id":"308","category_id":"3","question":"When attaching a trailer to their vehicle, what must a driver check?","img":"","options":["That the trailer coupling is attached securely.","That the load is positioned to the front of the trailer.","That the trailer springs are well greased.","That the trailer has a spare wheel."],"answer":["option_1"],"explanation":"Before towing a trailer or a caravan, check that the tow bar is securely attached to the towing vehicle, that the trailer coupling is properly attached to the tow bar and locked in place, and that the breakaway cable is properly connected."},{"id":"309","category_id":"3","question":"What effect do the hazard warning lights have on the brake lights?","img":"","options":["They have no effect.","They cause the brake lights to switch off completely.","They cause the left and right brake lights to flash alternately.","They cause the brake lights to flash repeatedly."],"answer":["option_1"],"explanation":"The hazard lights work independently of the other lights on the vehicle (except the direction indicators), and have no effect on the brake lights. Use the hazard warning lights to warn other road users of a danger ahead, when your vehicle is broken down and causing an obstruction, or when you needs to slow down sharply on a motorway."},{"id":"310","category_id":"3","question":"When should a driver use their hazard warning lights?","img":"","options":["When the brake lights are not working.","When the vehicle has broken down.","When about to pull in and stop.","When parking for a short time on a single yellow line."],"answer":["option_2"],"explanation":"Use the hazard warning lights to warn other road users of a danger ahead. For example, if a driver’s vehicle has broken down and is stopped on the hard shoulder, they should use the vehicle’s hazard warning lights to warn other road users of their presence."},{"id":"311","category_id":"3","question":"When should a driver use their vehicle’s hazard warning lights?","img":"","options":["When a following vehicle is too close.","When double parking.","When the brake lights are not working.","When causing an unavoidable obstruction."],"answer":["option_4"],"explanation":"Use the hazard warning lights to warn other road users of a danger ahead. For example, if a driver’s vehicle is causing an unavoidable obstruction such as being broken down, they should use the vehicle’s hazard warning lights to warn other road users of their presence."},{"id":"312","category_id":"3","question":"When should a driver use their vehicle’s hazard warning lights?","img":"","options":["When parked at a bend or corner.","When reversing onto a narrow road.","When moving slowly in traffic.","When broken down and causing an obstruction."],"answer":["option_4"],"explanation":"Use the hazard warning lights to warn other road users of a danger ahead. For example, if a driver’s vehicle is causing an unavoidable obstruction such as being broken down, they should use the vehicle’s hazard warning lights to warn other road users of their presence."},{"id":"313","category_id":"3","question":"What lighting must be on a two-axle car-trailer?","img":"","options":["Indicators, brake lights, rear number plate light, red reflectors and rear tail lights.","Indicators and rear number plate lights only.","Flashing rear tail lights.","Brake lights and indicators only."],"answer":["option_1"],"explanation":"All vehicles, including trailers, must have rear indicators, brake lights, a rear number plate light, red reflectors and rear tail lights."},{"id":"314","category_id":"3","question":"In general, how should children under 3 years of age be secured in a vehicle?","img":"","options":["They should always be placed in the front passenger seat wearing a seat belt.","They should always be carried in an adult’s lap.","They should always sit on the rear passenger seat.","They should always be secured in the correct child seat."],"answer":["option_4"],"explanation":"Safety belts are designed mainly for adults and older children. Children under 3 years of age must be restrained in an appropriate child restraint system. Warning: Never use a rearward facing child car seat in a seat protected by an active frontal airbag."},{"id":"315","category_id":"3","question":"Can a child under the age of 3 years be carried unrestrained in the vehicle’s front passenger seat?","img":"","options":["No, unless the child is using a child booster seat.","Yes, provided the infant is held securely by an adult.","No, an infant must always be restrained in the correct child seat.","Yes, but only if the vehicle is fitted with active airbags."],"answer":["option_3"],"explanation":"Generally, children must never travel unrestrained in a vehicle. Children under 3 years of age must be restrained in an appropriate child restraint system. Warning: Never use a rearward facing child car seat in a seat protected by an active frontal airbag."},{"id":"316","category_id":"3","question":"If a vehicle breaks down, where should the driver stop?","img":"","options":["As far to the left as possible.","As far to the right as possible.","In the lane where the problem occurred.","The nearest exit ramp."],"answer":["option_1"],"explanation":"When a vehicle breaks down it is important to move as far in to the left as possible for the convenience of other road users and the safety of the vehicles occupants."},{"id":"317","category_id":"3","question":"What is the quickest way to warn other traffic of a crash?","img":"","options":["Use hazard lights.","Place a large object in the centre of the road.","Stand in the road and wave arms.","Call local radio station."],"answer":["option_1"],"explanation":"If you arrive at the scene of a crash, find a safe place to stop so that you don’t endanger yourself or others, warn other road users of the incident by using hazard lights."},{"id":"318","category_id":"3","question":"In order to inform the emergency services of a crash what telephone number should be called?","img":"","options":["199","555","911","112"],"answer":["option_4"],"explanation":"If a driver arrives at or is involved in a crash it may be essential to obtain the assistance of the emergency services as a matter of urgency. The common European emergency number is 112 however in Ireland you may also use 999."},{"id":"319","category_id":"3","question":"When calling for help on an emergency telephone on the motorway, who does the call go to?","img":"","options":["National Safety Council.","Road Safety Authority.","National Roads Authority.","The Gardaí."],"answer":["option_4"],"explanation":"The emergency telephones at the side of a motorway are linked directly to An Garda Síochána in order for them to respond appropriately as soon as possible. The Gardaí know precisely the location of each call using these phones."},{"id":"320","category_id":"3","question":"Where an injured person is discovered lying in the road, when should they be moved?","img":"","options":["If the person is cold.","If the person needs CPR.","If the person has broken bones.","If the person is bleeding."],"answer":["option_2"],"explanation":"If a person discovered lying in the road is not breathing, it may be essential to move them in order to safely carry out emergency CPR. It may also be necessary to move them under other circumstances but an urgent assessment of the situation should be carried out first."},{"id":"321","category_id":"3","question":"When dealing with crash victims, remember A B C. What does A stand for?","img":"","options":["Airway.","Arms.","Accident.","Assist."],"answer":["option_1"],"explanation":"In assessing a crash victim’s vital signs, the following basic procedure should be used: First check the victim’s Airway is clear, then check they are Breathing and then check their Circulation (ABC)."},{"id":"322","category_id":"3","question":"What is good basic first aid for a person who has been burned?","img":"","options":["Apply warm water to the burn.","Apply cold water to the burn.","Remove clothing covering the burn.","Apply grease to the burn."],"answer":["option_2"],"explanation":"When a person has been burned firstly check the person for shock, then try to cool the burn if you can. Try to find water or other liquid that is clean, cold and non-toxic to pour on it. The cool liquid may cool the affected area down and reduce damage. The person should be advised to seek medical advice as soon as possible."},{"id":"323","category_id":"3","question":"What effect could hitting or mounting the kerb have on a vehicle’s tyres?","img":"","options":["It could strengthen the sidewalls.","It could damage the sidewalls.","It could increase the air pressure.","It could wear the tread."],"answer":["option_2"],"explanation":"Drivers should avoid hitting or mounting the kerb as it causes damage to the sidewalls of the tyre. The damage caused could cause the tyre to blow-out later. If this happens at high speed the driver may lose control of the vehicle with dangerous consequences."},{"id":"324","category_id":"3","question":"Who should first be contacted where a person has been injured in a collision?","img":"","options":["The person’s relatives.","The injured person’s insurance company.","The emergency services."],"answer":["option_3"],"explanation":"Where somebody has been injured in a collision, it is important to call the emergency services immediately on 999 or 112. Trained emergency services personnel know best how to attend to injured persons."},{"id":"325","category_id":"3","question":"While driving, a driver notices a strong smell of fuel. What should they do?","img":"","options":["Drive at a reduced speed.","Turn on the fan to clear the air.","Stop where safe and investigate."],"answer":["option_3"],"explanation":"A strong smell of fuel is usually an indication that something is wrong, and drivers should stop and investigate as soon as possible. Leaking or spilling petrol can be dangerous because it is so combustible, and leaking diesel fuel can make the road very slippery."},{"id":"326","category_id":"3","question":"What would make a pedestrian more visible to a driver at night?","img":"","options":["Wearing a waterproof jacket.","Wearing headphones.","Wearing a hi-vis jacket."],"answer":["option_3"],"explanation":"Even with the best vehicle headlights, drivers can see less at night than during the day, pedestrians as vulnerable road users are extremely difficult to see in the dark. Wearing reflective clothing makes pedestrians more visible. Pedestrians should always wear bright and hi-vis clothing during the day and reflective clothing at night when walking outside built-up areas."},{"id":"327","category_id":"3","question":"Why should a driver adjust their head restraint before starting a journey?","img":"","options":["To improve rear passengers view of the road ahead.","To provide support to the neck in the event of a collision.","To prevent glare from the headlights of following vehicles."],"answer":["option_2"],"explanation":"Vehicle seats are fitted with head restraints to help reduce injury such as whiplash in the event of the vehicle being involved in a collision. Drivers and passengers should ensure that head restraints are adjusted to provide maximum protection. The top of the head restraint should be in line with the top of the head. The centre of the head restraint should be roughly in line with the top of the ears."},{"id":"328","category_id":"3","question":"What is the purpose of daytime running lights on a vehicle?","img":"","options":["To give the vehicle extra light when driving at night.","To illuminate the road in bad weather conditions in daylight hours.","To increase the vehicles visibility in daylight hours."],"answer":["option_3"],"explanation":"Daytime running lights refer to the white lighting systems on the front of a vehicle that automatically come on during daylight hours. The purpose of daytime running lights are to increase the visibility and presence of the vehicle to other road users."},{"id":"329","category_id":"3","question":"What is the immediate effect of a head-on collision between two cars at speed?","img":"","options":["All persons in each vehicle are thrown violently backwards only.","All persons in each vehicle are thrown violently forward.","Only front seatbelts will activate."],"answer":["option_2"],"explanation":"In a head-on collision passengers in both vehicles are propelled forwards, and if they are not wearing seatbelts they may go through the windscreen. It is the driver’s responsibility to ensure that all passengers under the age of 17 wear seatbelts. Older passengers are themselves responsible for wearing seatbelts."},{"id":"330","category_id":"3","question":"Is it allowed for a vehicle to be driven on a public road when the brake lights are not working?","img":"","options":["No, it is never permitted to be driven.","Yes, during lighting-up times.","Yes, outside of lighting-up times.","No, unless driving in a built-up area."],"answer":["option_1"],"explanation":"A driver must always ensure that their vehicle’s brake-lights are clean and working correctly before driving on a public road. Never drive a vehicle when the brake lights are not working properly."},{"id":"331","category_id":"3","question":"Under what circumstances would a driver increase the air pressure in the tyres?","img":"","options":["When the tread depth on the tyres is below 2 mm.","When taking a journey with additional passengers.","When the journey exceeds 200 km.","When higher speeds are expected on motorway driving."],"answer":["option_2"],"explanation":"Before starting a journey with extra passengers or loads, drivers should check the air pressure and when they inflate the tyres, they should increase the vehicle’s tyre pressures in accordance with the vehicle manufacturer’s recommended tyre pressure. This information can be found in the vehicle manufacturer’s handbook."},{"id":"332","category_id":"3","question":"How can sunlight affect visibility in a car with dirty windows?","img":"","options":["It can enhance visibility.","It can seriously reduce visibility.","It can cause objects to seem further away than they are.","It can cause objects to seem closer than they are."],"answer":["option_2"],"explanation":"It is essential that all vehicle windows are clear and clean at all times so that drivers can see road and traffic conditions all around. Dirty windows are a particular hazard when the sun is low in the sky. Dirty windows also decrease visibility during hours of twilight and darkness."},{"id":"333","category_id":"3","question":"How does driving at high speed affect a vehicle’s road holding?","img":"","options":["The suspension compensates for any unevenness in the road surface.","The wheel alignment keeps the tyres in full contact with the road.","The road holding ability of the vehicle is increased.","The road holding ability of the vehicle is reduced."],"answer":["option_4"],"explanation":"Driving at high speed is a factor that affects road holding. At higher speeds the airflow under a vehicle reduces tyre grip on the road and when you are approaching a bend or corner, the momentum of the vehicle makes it more difficult to change direction."},{"id":"334","category_id":"3","question":"What effect could incorrectly aligned headlights have?","img":"","options":["They could cause a fire.","They could reduce battery life.","They could wear out the bulbs prematurely.","They could dazzle oncoming drivers."],"answer":["option_4"],"explanation":"A driver should ensure their headlights are properly aligned so as not to dazzle oncoming drivers and also to see properly themselves."},{"id":"335","category_id":"3","question":"What should a driver do before towing a caravan?","img":"","options":["Ensure all passengers are securely seated in the caravan.","Have extended mirrors fitted to the towing vehicle.","Have an extended mirror fitted to the driver’s side of the vehicle only.","Ensure that only adult passengers are seated in the caravan."],"answer":["option_2"],"explanation":"If a driver intends towing a caravan, they should fit extended mirrors to both sides of the towing vehicle. This will allow the driver to better observe the traffic situation behind and to the sides."},{"id":"336","category_id":"3","question":"Generally what lighting must a car, tractor or works vehicle have when driving?","img":"","options":["Headlights, front and rear side lights, rear number plate light, red rear reflectors, brake lights and indicators.","Headlights and a reversing light.","Headlights, number plate and rear reflectors only.","Headlights, brake lights and indicators only."],"answer":["option_1"],"explanation":"In general all cars, tractors and works vehicles are required by law to have headlights, front and rear side lights, rear number plate light, rear reflectors, brake lights and indicators. There are some exceptions to this, such as electric cars with a maximum speed of 38 km/h."},{"id":"337","category_id":"3","question":"What danger could be associated with driving a tractor and trailer over a humpbacked bridge?","img":"","options":["The tractor’s suspension could smooth out the bump.","The trailer could become detached.","The trailer could jack-knife.","The trailer’s parking brake could automatically engage."],"answer":["option_2"],"explanation":"Before towing a trailer, a driver should ensure that the tow hitch has sufficient ground clearance. If this hits the road, for example when travelling over a humpbacked bridge, there is a danger that the trailer will become detached. Drivers should also plan and carry out their journey with an awareness of this risk."},{"id":"338","category_id":"3","question":"What should a driver do if their vehicle breaks down on an automatic railway level crossing?","img":"","options":["Walk along the track to give warning to any approaching trains.","Get passengers clear of the crossing and phone the signal operator so that trains can be stopped.","Try to push the vehicle clear of the crossing as soon as possible.","Turn on the warning bells at the crossing."],"answer":["option_2"],"explanation":"In this situation, you and all passengers should get out of the vehicle and immediately use the emergency phone at the crossing to contact the signal operator so that trains can be stopped. If necessary, warn other motorists. Do not return to the vehicle until instructed by the signal operator or emergency services."},{"id":"339","category_id":"3","question":"What danger can arise from the power take-off shaft of a tractor?","img":"","options":["If it is not disengaged, the steering will lock.","If it is not covered, clothing can get caught in it.","If it is not covered, the tractor will speed up rapidly.","If it is not disengaged, the battery will run flat."],"answer":["option_2"],"explanation":"If you are working at the rear of a tractor, you should bear in mind that if the power take-off shaft is not covered, loose clothing might get caught in it and lead to injury or death."},{"id":"340","category_id":"3","question":"When changing a wheel on a public road, what should a person do to ensure their own safety?","img":"","options":["Ensure the vehicle is in reverse gear and front wheels are facing the roadway.","Ask a bystander to warn traffic by beckoning them from the middle of the road.","Wear reflective clothing and switch on the vehicle hazard warning lights.","Ensure the vehicle is in first gear and the wheels are facing the roadway."],"answer":["option_3"],"explanation":"When changing a wheel at the side of the road, switch on the vehicle hazard warning lights, and wear reflective or light-coloured clothing. This will help other motorists to react and slow down when passing."},{"id":"341","category_id":"3","question":"What should a driver do when requested to drive a vehicle that they feel is overloaded?","img":"","options":["Drive the vehicle only if accompanied.","Ensure that the load is properly restrained.","Drive at a slower speed than normal.","Refuse to drive the vehicle."],"answer":["option_4"],"explanation":"You should not take a vehicle that you believe to be overloaded onto a public road. Overloading is dangerous, as it affects the stability and braking capabilities of the vehicle."},{"id":"342","category_id":"3","question":"How could towing an overloaded trailer affect a vehicle?","img":"","options":["It could improve braking ability when going downhill.","It could improve road holding on bends.","It could impair the vehicle’s steering and braking.","It could improve the vehicle’s fuel consumption."],"answer":["option_3"],"explanation":"You should not take an overloaded trailer onto a public road. An overloaded trailer impairs the stability, steering and braking of the towing vehicle."},{"id":"343","category_id":"3","question":"What should a driver do to secure the towing vehicle before unhitching a trailer?","img":"","options":["Disconnect the electrical supply to the trailer lights and lower the jockey wheel.","Apply the handbrake, switch off the ignition and engage a low gear.","Lower the jockey wheel and then switch off the ignition.","Apply the handbrake, lower the jockey wheel and switch off the engine."],"answer":["option_2"],"explanation":"Before unhitching a trailer, apply the handbrake, switch off the ignition and engage a lower gear, so that the towing vehicle does not move while you are unhitching the trailer."},{"id":"344","category_id":"3","question":"What lighting must be on a tractors trailer during lighting-up hours?","img":"","options":["Indicators, brake lights, rear number plate light, red reflectors and rear tail lights.","Indicators, two white or yellow headlamps and rear number plate lights only.","An unloading light.","Brake lights and indicators only."],"answer":["option_1"],"explanation":"A trailer being towed by a tractor must have rear indicators, brake lights, a rear number plate light, red reflectors and rear tail lights whilst being towed on a public road."},{"id":"345","category_id":"3","question":"What should a driver do to reduce the risk of neck injury in the event of a rear-end collision?","img":"","options":["Use a properly adjusted head restraint.","Ensure the vehicle has a rear spoiler.","Use a properly adjusted seat belt.","Ensure the vehicle has anti-lock brakes."],"answer":["option_1"],"explanation":"It is essential that head restraints be properly adjusted for both the driver and the passengers. Head restraints are designed to protect the neck and spine in a collision and thus prevent or reduce whiplash. If head restraints are not properly adjusted there is an increased risk to the vehicles occupants."},{"id":"346","category_id":"3","question":"What is the minimum legal tread depth for tyres on cars?","img":"","options":["1 millimetre","1.6 millimetres","2.6 millimetres","0.6 millimetres"],"answer":["option_2"],"explanation":"All road vehicles, except motorcycles and vintage vehicles, must have a minimum tyre tread depth of 1.6 mm over the main tread. However, for safety reasons, you should replace the vehicle’s tyres before they become this worn."},{"id":"347","category_id":"3","question":"What does the load index of a tyre indicate?","img":"","options":["The maximum load of the vehicle.","The maximum load per axle.","The maximum air pressure of the tyre.","The maximum load a tyre can carry."],"answer":["option_4"],"explanation":"The load index indicates the maximum weight that a tyre can support safely. When replacing a tyre on your vehicle, you should make sure that the new tyre maintains the proper load index for the vehicle."},{"id":"348","category_id":"3","question":"A driver notices that the wiper blades are worn. What should they do?","img":"","options":["Wipe the windscreen with newspaper.","Have the blades replaced as soon as possible.","Roll down the window and drive slowly.","Use the windscreen washer system while it is raining."],"answer":["option_2"],"explanation":"Use the windscreen wipers to keep the windscreen clear of rain, spray, snow or fog. Check them regularly to ensure that they are in good working order, and replace them when they become worn, before they become ineffective."},{"id":"349","category_id":"3","question":"When a wiper blade fails to clear the windscreen what should the driver do?","img":"","options":["Have the wiper blades replaced as soon as possible.","Switch the wiper control from high speed to low speed repeatedly.","Apply a light film of oil to both of the wiper blades.","Bend the wiper arm to apply more pressure on the windscreen."],"answer":["option_1"],"explanation":"Use the windscreen wipers to keep the windscreen clear of rain, spray, snow or fog. Check them regularly to ensure that they are in good working order, and replace them when they become worn, before they become ineffective."},{"id":"350","category_id":"3","question":"If a vehicle breaks down on a motorway, what should a person do?","img":"","options":["Place a red warning triangle on the motorway to warn other drivers.","Use a roadside phone to contact Gardaí and never try to carry out repairs yourself.","Ask a passenger to stand on the road to warn other traffic.","Turn on the full beam headlights to alert other drivers."],"answer":["option_2"],"explanation":"When a vehicle breaks down on a motorway, a driver should move the vehicle to the hard shoulder, use the roadside phone to contact the Gardaí, and do not place a warning device on the motorway. The driver should never try to do repairs themselves in the hard shoulder."},{"id":"351","category_id":"3","question":"Who is responsible for ensuring that a passenger over 17 years of age is wearing a seat belt while travelling in a car?","img":"","options":["The driver when the passenger is in the front seat.","The passenger only.","Both the driver and the passenger.","The driver only."],"answer":["option_2"],"explanation":"Where the passenger is over the age of 17 and travelling in a car it is their legal responsibility to comply with the seat belt regulations. Below that age, it is the driver’s responsibility."},{"id":"352","category_id":"3","question":"Who is responsible for ensuring that a passenger under 17 years of age is wearing a seat belt while travelling in a car?","img":"","options":["The driver only.","The driver, but only when the passenger is in the front seat.","The passenger only.","The passenger’s parents."],"answer":["option_1"],"explanation":"Where the passenger is over the age of 17 and travelling in a car it is their legal responsibility to comply with the seat belt regulations. Below that age, it is the driver’s responsibility."},{"id":"353","category_id":"3","question":"Who is responsible for ensuring that a child wears a child restraint system in a vehicle?","img":"","options":["The driver only.","Any adult passenger.","The child, if over 12 years of age.","The parents of the child only."],"answer":["option_1"],"explanation":"Where the passenger is over the age of 17 and travelling in a car it is their legal responsibility to comply with the child restraint regulations. Below that age, it is the driver’s responsibility."},{"id":"354","category_id":"3","question":"How should a child restraint system be fitted in a vehicle?","img":"","options":["It should be placed on a front passenger seat only.","It should be left unsecured.","It should be placed on the floor.","It should be fitted in accordance with the manufacturer’s instructions."],"answer":["option_4"],"explanation":"It is recommended to fit the child seat correctly, according to the manufacturer’s instructions, it is safer to fit the seat in the back seat of the car and to buy a child car seat only from a retailer who will check that it fits both the car and the child."},{"id":"355","category_id":"3","question":"On a motorway, when should a driver use the hazard warning lights?","img":"","options":["When parked in the hard shoulder to take a phone call.","When another vehicle is following too closely.","When the vehicle has broken down.","When towing another vehicle."],"answer":["option_3"],"explanation":"Use the hazard warning lights to warn other road users of a danger ahead. For example, if your vehicle has broken down and is stopped on the hard shoulder, you can use the hazard warning lights to warn following vehicles of your presence."},{"id":"356","category_id":"3","question":"If a vehicle breaks down on a motorway, what should a person do?","img":"","options":["Turn on the full beam headlights.","Ask a passenger to stand on the motorway to warn other traffic.","Place a red warning triangle to the left of the vehicle.","Move the vehicle to the hard shoulder."],"answer":["option_4"],"explanation":"Move the vehicle to the hard shoulder. Park as near to the left as possible. If this is not possible, take steps to warn other drivers, such as switching on the hazard warning lights."},{"id":"357","category_id":"3","question":"If a vehicle breaks down on a motorway, what should a person do?","img":"","options":["Turn on the full beam headlights.","Ask a passenger to stand on the motorway to warn other traffic.","Place a red warning triangle to the left of the vehicle.","Wear a high-visibility vest."],"answer":["option_4"],"explanation":"Move the vehicle to the hard shoulder. Park as near to the left as possible. If this is not possible, take steps to warn other drivers, such as switching on the hazard warning lights. Wear a high-visibility vest. Always carry at least two in the vehicle."},{"id":"358","category_id":"3","question":"Where safety belts are fitted to a car when must adult occupants wear them?","img":"","options":["Only when instructed to do so by the driver.","When travelling on long journeys.","At all times."],"answer":["option_3"],"explanation":"The driver and all passengers in a car must wear a safety belt or, in the case of a child, a suitable restraint system."},{"id":"359","category_id":"4","question":"What should a driver be alert to in this area?","img":"a_vyODC.png","options":["Pedestrians may be hitch-hiking.","Parked vehicles may have trailers attached.","Pedestrians may cross between parked cars.","There may be refuse bins between the parked vehicles."],"answer":["option_3"],"explanation":"When driving in a built-up area, you should drive with caution and be prepared to react to pedestrians crossing from between parked vehicles."},{"id":"360","category_id":"4","question":"The silver car is overtaking the parked red car, what should the driver do in this situation?","img":"a_Sktnb.png","options":["The driver should drive on if he does not hit the ball.","The driver should move closer to the red car.","The driver should drive on at the same speed.","Reduce speed considerably and be ready to stop."],"answer":["option_4"],"explanation":"You should read the road and be extra careful while driving through an area where children might be playing. When a ball bounces out on the road you should expect that a child might follow to retrieve the ball."},{"id":"361","category_id":"4","question":"How should a driver overtake the cyclist in this situation?","img":"a_sFKKb.png","options":["Overtake the cyclist, but without crossing any of the lines.","By sounding the horn to warn the cyclist they intend to pass.","By straddling both lines and keeping close to the cyclist.","By crossing the broken white line."],"answer":["option_4"],"explanation":"Where there are two lines in the centre of the road, you must obey the one closest to you. So, if the closest line is a broken white line, by law you may overtake, so long as it is safe to do so."},{"id":"362","category_id":"4","question":"Why might it be dangerous to drive on a poorly-lit street?","img":"a_DjQ45.png","options":["Drivers can only see the traffic coming against them.","Drivers can only see the traffic in front of them.","It may be difficult to make out poorly lit vehicles in the dark areas.","Traffic lights will not be working."],"answer":["option_3"],"explanation":"When you are driving along a poorly-lit street, you should take extra care and be prepared to react to hazards such as unlit parked vehicles."},{"id":"363","category_id":"4","question":"What should a driver do on the approach to this situation?","img":"a_GTp8K.png","options":["Increase speed in order to clear the bridge before the oncoming car.","Reduce speed and stop if necessary.","Give way only if you are towing a trailer or caravan.","Drive on because the oncoming traffic must wait."],"answer":["option_2"],"explanation":"When road priority is unclear you might have to yield to oncoming vehicles. Never drive a vehicle into an area that it might not be able to clear or where it could cause an obstruction or bottleneck."},{"id":"364","category_id":"4","question":"Why must a driver be particularly careful here?","img":"a_mhQvt.png","options":["The vehicle coming from the right has the right of way.","The vehicle coming from the right is not required to signal.","Because there is an increased danger of skidding.","Because a vehicle could come from the left."],"answer":["option_3"],"explanation":"Where there are fallen leaves on the road surface, your tyres might have reduced grip on the road surface and your braking distances might be greater."},{"id":"365","category_id":"4","question":"What should a driver do when turning right at this junction?","img":"a_556VC.png","options":["Proceed ahead of both cars.","Allow the blue car to proceed.","Allow the red car to proceed.","Allow both cars to proceed."],"answer":["option_3"],"explanation":"When you are turning right from a main road into a side road, you must give way to oncoming traffic on the main road even if they are turning left into the same road."},{"id":"366","category_id":"4","question":"What should a driver be aware of when driving at night along a shopping street with many different light sources?","img":"a_0b6eG.png","options":["Parking spaces may be difficult to notice.","Traffic lights may be difficult to distinguish from the other bright lights.","Other vehicles do not need to use their head lights.","It is easier to see pedestrians because of the bright lights."],"answer":["option_2"],"explanation":"When driving at night in an area where there is a variety of light sources, you need to be extra careful, as potential hazards might be more difficult to see."},{"id":"367","category_id":"4","question":"In this situation who should wait?","img":"a_IwyNk.png","options":["The driver behind the stopped van should wait.","Neither vehicle should wait.","Whichever vehicle is furthest away from the van.","The oncoming vehicle must wait."],"answer":["option_1"],"explanation":"When you are overtaking a parked vehicle or obstruction, you should yield to oncoming vehicles so that they don’t have to slow down or take evasive action."},{"id":"368","category_id":"4","question":"In this situation, who should wait?","img":"a_NnSNz.png","options":["Neither driver should wait.","Both drivers should wait.","The driver in the red car should wait.","The driver on the main road should wait."],"answer":["option_3"],"explanation":"A vehicle driving on the main road has priority over vehicles emerging from side roads. However, you must understand that the right of way is not an absolute right of way and you should be considerate of other road users at all times."},{"id":"369","category_id":"4","question":"What should a driver be aware of in this situation?","img":"a_V06TV.png","options":["A minor road to the right ahead.","A sharp dip in the road ahead.","A dangerous right-hand bend ahead.","A minor road to the left ahead."],"answer":["option_3"],"explanation":"You should always read the road ahead and be prepared to react to changing traffic situations – in this case paying attention to the warning sign clearly indicating a right-hand bend ahead."},{"id":"370","category_id":"4","question":"Which vehicle is in the correct position to make a right turn from the major road into the minor road?","img":"a_PKtfs.png","options":["2","1","3","4"],"answer":["option_3"],"explanation":"The correct position from which to turn right from a major road to a minor road is just left of centre. You should take up the correct position in good time and avoid cutting the corner or swan necking – that is going beyond the turning point as car 2 is in the picture."},{"id":"371","category_id":"4","question":"Which vehicle is in the correct position to make a right turn from a minor road onto a major road?","img":"a_IfRXY.png","options":["3","2","1","4"],"answer":["option_3"],"explanation":"The correct position from which to turn right from a minor road to a major road is just left of centre of the road. You should take up the correct position in good time and complete the turn by entering the left-hand side of the major road."},{"id":"372","category_id":"4","question":"What should a driver do if they see a red warning triangle on the road?","img":"","options":["The driver should remove the triangle as it is causing an obstruction on the road.","The driver should stop and await instructions.","The driver should maintain speed, carry on and avoid the triangle.","The driver should slow down and expect a hazard up ahead."],"answer":["option_4"],"explanation":"Warning triangles are used to alert approaching traffic that there is a vehicle breakdown or collision ahead. When you come across a warning triangle, you should slow down and be prepared to stop if necessary. Do not allow yourself to be distracted by the incident."},{"id":"373","category_id":"4","question":"What should drivers be aware of if they meet horses with riders on the road?","img":"","options":["Drivers should be aware that horse riders are obliged to dismount and control their horses while traffic is passing.","Drivers should be aware that all horse riders are experienced at handling horses.","Drivers should be aware that loud noises from their vehicle may frighten the horses and cause them to bolt.","Drivers should be aware that loud noises from their vehicle will not frighten the horses."],"answer":["option_3"],"explanation":"You must know your responsibilities towards animal traffic on the road. Horses are easily startled and any sudden noises or activity could cause them to bolt."},{"id":"374","category_id":"4","question":"There are pedestrians on the footpath ahead and there are pools of water on the road. What should a driver do?","img":"","options":["Reduce speed and try to avoid the pools of water so as not to splash the pedestrians.","Sound the horn as a warning to the pedestrians and continue on.","Flash the headlights as a warning to the pedestrians.","Brake suddenly as you approach the pools of water."],"answer":["option_1"],"explanation":"During wet conditions, you should be aware that surface water can affect the stability of your vehicle. This is particularly so where the water lies in pools. As you drive through surface water, you should show consideration to pedestrians and cyclists and try not to splash them as you pass."},{"id":"375","category_id":"4","question":"When is it permitted to force oncoming traffic onto the hard shoulder on the opposite side of the road while overtaking?","img":"","options":["When the hard shoulder is wide enough.","When none of the oncoming traffic is overtaking.","When the vehicle being overtaken is driving too slow.","It is not permitted to force oncoming traffic onto the hard shoulder while overtaking."],"answer":["option_4"],"explanation":"Overtaking in the manner described here is dangerous. You should overtake another vehicle only when it is safe to do so, both for you and for all other traffic. Before you overtake, make sure the road ahead is clear and that you have enough room to complete the overtaking manoeuvre and return to your own side of the road without forcing any other road user to alter speed or course."},{"id":"376","category_id":"4","question":"What does a 2-plus-1 road have?","img":"","options":["Two non-motorway lanes in one direction and one non-motorway lane in the opposite direction.","Two motorway lanes and one non-motorway lane in two directions.","Two motorway lanes in one direction and one non-motorway lane in the opposite direction.","Two non-motorway lanes and one motorway lane in two directions."],"answer":["option_1"],"explanation":"A 2-plus-1 road consists of two lanes in one direction of travel and one lane in the other direction. The two-lane section allows for safe overtaking and alternates with a one-lane section roughly every 2 kilometres."},{"id":"377","category_id":"4","question":"Where may a driver overtake on a 2-plus-1 road?","img":"","options":["In the two-lane stretch.","In the one-lane stretch if there is no oncoming traffic.","In the one-lane stretch.","In either the one-lane stretch or the two-lane stretch."],"answer":["option_1"],"explanation":"A 2-plus-1 road consists of two lanes in one direction of travel and one lane in the other direction. When you need to overtake, you should wait until you reach the 2-lane section which occurs approximately every 2 kilometres."},{"id":"378","category_id":"4","question":"At road junctions, what type of road users are particularly vulnerable?","img":"","options":["Car drivers.","Pedestrians.","Tractor drivers.","Van drivers."],"answer":["option_2"],"explanation":"Vehicles do not have an automatic right of way at junctions. As a driver you should pay particular attention to vulnerable road users such as pedestrians, cyclists and motorcyclists and be aware that they are entitled to use the road in safety."},{"id":"379","category_id":"4","question":"What should a driver do to ensure better fuel efficiency from their vehicle?","img":"","options":["Ensure that the vehicle is regularly serviced.","Ensure any load carried is equally distributed on the vehicle.","Drive at higher speeds in order to reduce the time spent on the road.","Ensure that heavier items are carried at the rear of the vehicle."],"answer":["option_1"],"explanation":"One of the keys to good fuel efficiency is making sure that your vehicle is well maintained. Servicing should be carried out as recommended by the manufacturer. Checking the tyre pressure regularly can also help ensure good fuel efficiency."},{"id":"380","category_id":"4","question":"In what way do motor vehicles harm the environment?","img":"","options":["By decreasing radon levels.","By increasing carbon monoxide levels.","By decreasing carbon monoxide levels.","By increasing radon levels."],"answer":["option_2"],"explanation":"Carbon monoxide is a poisonous gas emitted by vehicle exhausts into the atmosphere. Driving economically and keeping a vehicle well maintained can reduce the level of carbon monoxide emissions."},{"id":"381","category_id":"4","question":"What can be achieved by the driving style known as ‘Eco-Driving’?","img":"","options":["Increased fuel consumption.","Reduced fuel consumption.","Increased journey times.","Reduced journey times."],"answer":["option_2"],"explanation":"The advantages of eco-driving include improved road safety, improved fuel consumption and reduced emissions. The eco-conscious driver becomes a more efficient driver because they learn to read the road further ahead and display better anticipation skills. This reduces the need for harsh acceleration and braking which results in a more economical style of driving and a smoother drive."},{"id":"382","category_id":"4","question":"Which action contributes to eco-driving?","img":"","options":["Braking harshly.","Selecting a high gear as soon as possible.","Driving in a low gear at high speed.","Fitting a roof rack."],"answer":["option_2"],"explanation":"Eco-driving contributes to road safety and also reduces fuel consumption and harmful emissions. Eco-conscious drivers will read the road well in advance and avoid harsh acceleration and braking. Fuel consumption can be reduced by using the highest gear possible without causing the engine to labour."},{"id":"383","category_id":"4","question":"When should a driver use dipped headlights?","img":"","options":["From just after dusk to just before dawn.","From 00:00 hrs to 06:00 hrs.","When visibility is less than 200 metres.","When visibility is less than 300 metres."],"answer":["option_1"],"explanation":"Lighting up hours are defined as the period of time during which drivers should turn on dipped headlights in order to be seen. This period normally starts half an hour after sunset and ends half an hour before sunrise."},{"id":"384","category_id":"4","question":"What lights should a vehicle show at dusk?","img":"","options":["Dipped headlights.","Fog lights.","Full headlights.","Daytime Running Lights (DRLs) only."],"answer":["option_1"],"explanation":"Drivers need to see and be seen during all periods of low light levels – for example, at dusk and dawn and in some bad weather conditions. At times of low light, you should turn on dipped headlights. The Road Safety Authority recommends that motorcyclists and drivers turn on their dipped headlights or daytime running lights during daylight hours."},{"id":"385","category_id":"4","question":"An approaching driver notices that the boy on the children’s bicycle has said goodbye to his friend. What is the correct action for the driver to take?","img":"a_Sd6Gv.png","options":["Be prepared for the boy setting off at any moment.","Proceed as the boy is on the footpath.","Slow down and beckon the boy to cross the road.","Stop the car until the boy has moved off."],"answer":["option_1"],"explanation":"Because it is difficult to predict children’s behaviour, you should always be prepared to react to a change in the traffic situation or to stop."},{"id":"386","category_id":"4","question":"What should a driver be aware of in this situation?","img":"a_dkKht.png","options":["The pedestrian may leave the traffic island without paying attention.","The tram may move away without warning.","The pedestrian always has the right of way to cross in front of traffic.","There is no danger as the tram is on rails."],"answer":["option_1"],"explanation":"You should read the road ahead and expect extra pedestrian activity when the tram is at the stop."},{"id":"387","category_id":"4","question":"What should the driver be most conscious of in this situation?","img":"a_okwFl.png","options":["The pedestrian always has right of way to cross the road.","The pedestrian may suddenly cross the road in front of the vehicle.","No vehicles should be parked on the left-hand side of the road.","One of the parked vehicles may reverse into the driver’s path."],"answer":["option_2"],"explanation":"It is often difficult to predict other road users behaviour. Where there are parked vehicles on both sides of the road you should approach with caution, and be prepared to react to a change in the traffic situation and to stop."},{"id":"388","category_id":"4","question":"What should the driver do when approaching this situation?","img":"a_GtmJv.png","options":["The driver should maintain current speed and reduce distance from the silver car.","The driver may overtake the car and the girl as the road is marked with a broken white line.","The driver should be prepared for the vehicle in front to increase speed.","Reduce speed and remain ready to brake since the girl on the footpath could suddenly cross the road."],"answer":["option_4"],"explanation":"It is often difficult to predict other road users behaviour. You should be prepared in case the pedestrian steps onto the road and the silver car stops suddenly."},{"id":"389","category_id":"4","question":"What should a driver be aware of in this situation?","img":"a_zxAP6.png","options":["A driver should move to the left-hand side (nearside) in case the cyclist moves out.","The cyclist may move onto the roadway without paying attention to moving traffic.","The cyclist will stop at the end of the cycle path to allow traffic to pass by.","The cyclist will stay on the cycle path."],"answer":["option_2"],"explanation":"You should show extra care when approaching cyclists who are about to exit from a cycle lane and join the roadway."},{"id":"390","category_id":"4","question":"What should a driver be aware of when following the motorcyclist, and the white car is reversing onto the road?","img":"a_p0du3.png","options":["The reversing driver will stop when they see the motorcyclist.","The driver following the motorcycle may need a longer braking distance than normal.","The motorcyclist may signal the reversing driver to stop.","The brake lights on the motorcycle may not be working."],"answer":["option_2"],"explanation":"You should always keep a safe distance from the vehicle in front if it is slowing down or stopping. Always read the road and be prepared to react correctly to changes in the traffic ahead."},{"id":"391","category_id":"4","question":"After a heavy downpour, why should a driver keep a greater distance from the vehicle in front?","img":"a_Gzfuj.png","options":["Because required stopping distances are decreased.","Because wheels rotate at a greater speed after rain.","Because wheels rotate at a slower speed after rain.","Because wheel-spray may impair visibility."],"answer":["option_4"],"explanation":"Heavy rain can affect how well you can see and how well you can be seen by other road users. Because of that you should slow down in heavy rain and keep a greater distance from the vehicle in front."},{"id":"392","category_id":"4","question":"What should the car driver be aware of in this situation?","img":"a_pMwJg.png","options":["Slowing down and being prepared to react.","Following traffic may cut the corner.","The road ahead becomes a dual carriageway.","Road marking is taking place ahead."],"answer":["option_1"],"explanation":"When you are approaching a bend or corner with a restricted view you should slow down if necessary and be prepared to react to any changes in the traffic situation."},{"id":"393","category_id":"4","question":"What should a driver be most aware of in this situation?","img":"a_k6p9n.png","options":["A car might appear unexpectedly at the brow of the hill.","Children may unexpectedly run out from between parked cars.","One of the parked vehicles may reverse into the driver’s path.","Parking opposite double yellow lines is prohibited."],"answer":["option_2"],"explanation":"When driving in a residential area you need to take account of the danger you might pose to children playing. You should always observe warning signs relating to children and drive accordingly."},{"id":"394","category_id":"4","question":"What should a driver who wants to turn right do in this situation?","img":"a_Wkvqu.png","options":["Reverse and get into the right lane.","Proceed straight ahead and take a wide turn to the right.","Turn right from the left lane.","Proceed straight ahead or turn left."],"answer":["option_4"],"explanation":"As you approach a junction where you want to turn right, you should read the road ahead and take up the correct position for turning in good time."},{"id":"395","category_id":"4","question":"What should the driver do when there is a sharp dip in the road ahead?","img":"","options":["Move to the centre of the road in order to avoid any vehicles that might be parked on the left.","Increase speed and make progress through the dip.","Pull in, stop and switch on hazard warning lights.","Reduce speed, keep to the left and be alert for hazards ahead."],"answer":["option_4"],"explanation":"As you approach a sharp dip in the road, you should be aware that there might be hidden dangers ahead. For example, there might be pedestrians, cyclists or other approaching traffic, or the road could be flooded in the dip. You should always read the road ahead and be prepared to react to changing traffic situations – you might need to reduce your speed and drive with extra care."},{"id":"396","category_id":"4","question":"The driver is approaching traffic lights that they know have been green for some time. What should the driver do?","img":"","options":["The driver should be aware that the lights may change before they reach them and be prepared to stop.","The driver should stop as the lights are about to change to red.","The driver should be aware that the lights may change and accelerate to clear the lights before they do.","The driver should maintain speed until the light changes to amber."],"answer":["option_1"],"explanation":"You should always read the road ahead and be prepared to react to changing traffic situations. Where traffic lights have been green for some time, you should be prepared to stop, as the lights are probably about to change to amber."},{"id":"397","category_id":"4","question":"What should a driver do when approaching a junction normally controlled by traffic lights and the traffic lights are not lighting?","img":"","options":["Switch on headlights, move to centre of the junction and proceed as quickly as possible.","Treat it as an unmarked junction and proceed cautiously while watching out for other traffic.","Stop at the junction and give way to traffic on the left.","Proceed smartly through the junction to avoid delay."],"answer":["option_2"],"explanation":"You should always read the road ahead and be prepared to react to changing traffic situations. If the traffic lights are not working, you should approach the junction with extra care, and you should proceed only if it is safe to do so."},{"id":"398","category_id":"4","question":"What should the driver do if there are cattle on the road ahead?","img":"","options":["The driver should sound the horn to try to get the cattle to move aside.","The driver should switch on the headlights and try to pass as quickly as possible.","The driver should sound the horn, switch on headlights, reduce speed and pass with care.","The driver should reduce speed and pass them with care."],"answer":["option_4"],"explanation":"You should always read the road ahead and be prepared to react to changing traffic situations. If you meet cattle or other animals on the road, you should slow down and be prepared to stop. Don’t use the horn or do anything that might frighten the animals. You must stop if directed to do so by the person in charge of animals."},{"id":"399","category_id":"4","question":"What should a driver do if they see horse riders on the road ahead?","img":"","options":["The driver should increase speed and allow extra clearance.","The driver should reduce speed, allow extra clearance and pass with care.","The driver should turn on hazard warning lights and continue at normal speed.","The driver should reduce speed and sound the horn."],"answer":["option_2"],"explanation":"You should always read the road ahead and be prepared to react to changing traffic situations. If you meet horses or other animals on the road, you should slow down and be prepared to stop. Don’t use the horn or do anything that might frighten the animals. You must stop if directed to do so by the person in charge of animals."},{"id":"400","category_id":"4","question":"What should the driver do when approaching a humpbacked hill?","img":"","options":["The driver should reduce speed, keep to the left and be alert for hazards ahead.","The driver should move to the centre in order to avoid vehicles that may be parked on the left.","The driver should increase speed and make progress over the humpbacked hill.","The driver should maintain normal speed and road position."],"answer":["option_1"],"explanation":"As you approach a humpbacked bridge or hill, you should be aware that there might be hidden dangers ahead – for example, overtaking traffic coming towards you. You should always read the road ahead and be prepared to react to changing traffic situations such as this."},{"id":"401","category_id":"4","question":"What do flashing amber beacons on an oncoming vehicle alert a driver to?","img":"","options":["That the oncoming vehicle is fast moving.","That the oncoming vehicle is an emergency vehicle.","That the oncoming vehicle may be slow moving or extra wide.","That the oncoming vehicle is a military vehicle."],"answer":["option_3"],"explanation":"Flashing amber beacons are used by recovery vehicles and vehicles carrying abnormal loads. You should be aware that these vehicles may need extra room and could conceal following traffic. When you come across such vehicles, slow down and be prepared to stop if necessary."},{"id":"402","category_id":"4","question":"What should a driver do if they meet a vehicle with flashing amber beacons?","img":"","options":["Flash their headlights to acknowledge the beacons.","Slow down and prepare to stop.","Increase speed while keeping left.","Stop because it is an emergency vehicle."],"answer":["option_2"],"explanation":"Flashing amber beacons are used by recovery vehicles and vehicles carrying abnormal loads. You should be aware that these vehicles may need extra room and could conceal following traffic. When you come across such vehicles, slow down and be prepared to stop if necessary."},{"id":"403","category_id":"4","question":"What should a driver be aware of before crossing railway or tram lines?","img":"","options":["The wheels may become caught in the rails, causing the tyres to deflate.","There may be a reduction in tyre noise while crossing the rails.","The tyre grip may be improved crossing the rails.","There may be an uneven surface and tyre grip may be reduced when crossing the rails."],"answer":["option_4"],"explanation":"You should be aware of the impact of changes in the road surface. For example, at railway and tram crossings the uneven surface or oil deposits could reduce the grip of your tyres. Slow down as you approach railway or tram crossings and increase your distance from the vehicle in front."},{"id":"404","category_id":"4","question":"What should the driver be aware of when crossing road markings such as lines and directional arrows in wet weather?","img":"","options":["The required stopping distance is reduced due to improved tyre grip.","The tyre grip is improved.","The required stopping distance is increased due to reduced tyre grip.","Steering control is improved."],"answer":["option_3"],"explanation":"You should be aware of the impact of changes in the road surface. For example, road markings and directional arrows can become slippery when wet. Where possible, avoid driving on road markings, and be aware of the increased risk of skidding."},{"id":"405","category_id":"4","question":"What should a driver do on a narrow road when another vehicle is coming in the opposite direction?","img":"","options":["Maintain position and expect the other vehicle to move over.","Reduce speed and allow reasonable clearance between their vehicle and the oncoming one before proceeding.","Position your vehicle along the middle of the road to encourage the other driver to pull in.","Maintain road position and speed. Then flash the vehicle’s lights to alert the other driver to your presence."],"answer":["option_2"],"explanation":"You should always be prepared to react to hazards ahead. When you meet a vehicle coming against you on a narrow road, you should show consideration and slow down to a appropriate speed so that the two vehicles can pass each other safely."},{"id":"406","category_id":"4","question":"When a driver is driving behind another vehicle that they do not intend to overtake, what should the driver do?","img":"","options":["Keep well back and to the centre of the road.","Drive close behind it in order to let following traffic overtake both vehicles.","Signal to following traffic to overtake both vehicles.","Keep well back to allow following traffic to overtake."],"answer":["option_4"],"explanation":"You should always allow sufficient distance between your vehicle and the vehicle in front. This will enable you to stop safely (within the distance you can see clear). It will also give overtaking vehicles enough room to pull in safely to the left lane after they have passed you."},{"id":"407","category_id":"4","question":"When a driver is driving in a line of traffic and does not intend to overtake, what should the driver do?","img":"","options":["Drive close to the vehicle in front.","Stay back and leave a gap for other drivers to overtake.","Indicate left as a signal to following traffic to overtake.","Beckon to following traffic to overtake."],"answer":["option_2"],"explanation":"You should always allow sufficient distance between your vehicle and the vehicle in front. This will enable you to stop safely (within the distance you can see clear). It will also give overtaking vehicles enough room to pull in safely to the left lane after they have passed you."},{"id":"408","category_id":"4","question":"Is tailgating allowed on a motorway or dual carriageway?","img":"","options":["Yes, because all traffic moves in the one direction at the same time.","No, because the vehicle in front may stop suddenly.","No, because other vehicles do not have room to overtake.","Yes, because there is oncoming traffic."],"answer":["option_2"],"explanation":"If you drive too close to the vehicle in front and it brakes suddenly, you will not have enough time to react. For that reason you should always keep a safe distance from the vehicle in front. One way of calculating a safe distance in dry weather is the two-second rule: Allow at least two seconds to elapse between the vehicle in front and your own vehicle passing a fixed point such as a lamp post or sign post."},{"id":"409","category_id":"4","question":"What danger can arise during daylight when a driver enters an area that is heavily shaded by overhanging trees?","img":"","options":["Visibility could suddenly be reduced.","The vehicle’s windscreen could fog up.","The tyre pressure could be reduced.","The vehicle engine could suddenly run cold."],"answer":["option_1"],"explanation":"When you enter a heavily shaded area after driving in bright sunlight, it might take a while for your eyes to adjust to the change, and you might not see a hazard immediately ahead."},{"id":"410","category_id":"4","question":"When driving into a narrow gap between oncoming vehicles and vehicles parked on the left. What should a driver do?","img":"","options":["Indicate and drive on enforcing your priority.","Signal to oncoming traffic to stop, and then move to the right and drive as normal.","Always slow down, stop and wait to be beckoned forward.","Indicate right, stopping if necessary until oncoming traffic has passed by."],"answer":["option_4"],"explanation":"When you meet approaching traffic at a narrow gap, you should show consideration and slow down to an appropriate speed so that you and the other vehicles can pass each other safely. If necessary, give way to the other vehicles."},{"id":"411","category_id":"4","question":"What should a driver do when approaching traffic lights stuck on red?","img":"","options":["Stop and proceed with great caution.","Check that there are no oncoming vehicles and increase speed.","Sound the horn and proceed ahead.","Indicate and increase speed."],"answer":["option_1"],"explanation":"On approach to traffic lights that are stuck on red, a driver should stop and proceed with caution when the way is clear."},{"id":"412","category_id":"4","question":"What should a driver do when there are dark clouds and visibility is reduced during daylight hours?","img":"","options":["Drive with dipped headlights switched on.","Keep close to any vehicle in front with headlights off.","Driver should not switch on lights until lighting up hours.","Drive with main beam headlights switched on."],"answer":["option_1"],"explanation":"Drivers need to see and be seen during all periods of low light levels – for example, at dusk and dawn and in some bad weather conditions. At times of low light, you should turn on dipped headlights."},{"id":"413","category_id":"4","question":"When driving behind a bus that is signalling to turn left and there is oncoming traffic, what should a driver do?","img":"","options":["Stay back and allow it to complete the turn.","Overtake it on the left-hand side.","Overtake it on the right-hand side.","Tap the brakes and sound the horn to signal to other vehicles to slow down."],"answer":["option_1"],"explanation":"Always allow a bus to complete a left-hand turn, because your field of view is restricted, and it could be dangerous to attempt overtaking it."},{"id":"414","category_id":"4","question":"What should a driver do when driving on a wide road behind a vehicle that has signalled to turn right ahead?","img":"","options":["Overtake on the right-hand side and carry on.","Stay behind and tap the brakes to signal other drivers to slow down.","Overtake on the left-hand side and carry on if safe to do so.","Overtake on the left, but only if turning left a short distance ahead."],"answer":["option_3"],"explanation":"You may overtake on the left when the driver in front has moved out and signalled their intent to turn right and you intend to go straight ahead – provided there is enough room to do so safely and your path will not be obstructed by the swing of a large vehicle turning right."},{"id":"415","category_id":"4","question":"When is it permissible to overtake another vehicle on the nearside (left-hand side)?","img":"","options":["Only when there is no cycle lane.","A driver must never overtake on the left.","When the vehicle in front is signalling to turn right.","When there are three lanes available in fast moving traffic."],"answer":["option_3"],"explanation":"You may overtake on the left when the driver in front has moved out and signalled their intent to turn right and you intend to go straight ahead – provided there is enough room to do so safely and your path will not be obstructed by the swing of a large vehicle turning right."},{"id":"416","category_id":"4","question":"What should a driver who wishes to perform a U-turn do?","img":"","options":["Check ahead for approaching traffic and signal them to stop.","Only perform a U-turn outside the urban speed limit area.","Check that the road is not one way.","Check behind for approaching traffic and signal them to stop."],"answer":["option_3"],"explanation":"If you want to do a U-turn you must first choose a place where it is safe and legal to do it. Check all around for other road users and do not impede their right of way. Complete the manoeuvre efficiently and safely."},{"id":"417","category_id":"4","question":"What should a driver do if they are not travelling as fast as the vehicle in front?","img":"","options":["The driver should keep to the left and allow vehicles to overtake if they wish.","The driver should keep their position and not allow following vehicles to overtake.","The driver should invite traffic to overtake them by giving a hand signal.","The driver should switch on hazard warning lights and keep to the left."],"answer":["option_1"],"explanation":"Always read the road ahead and be prepared to react to any traffic situation. You should not drive so slowly that your vehicle unnecessarily blocks other road users. Keep as near to the left as is safe to allow other vehicles to pass safely if they wish."},{"id":"418","category_id":"4","question":"What should a driver do if they wish to drive across a busy road and the traffic lights which normally control the junction are temporarily out of action?","img":"","options":["Take good observation, wait for a clear break in the traffic and proceed to cross the road safely.","Switch on headlights and use hand signals to show other drivers their intention to cross and then proceed.","Slowly force their way across using hazard warning lights if necessary.","Sound the horn and proceed slowly to cross the road."],"answer":["option_1"],"explanation":"Always read the road ahead and be prepared to react to any traffic situation. In this case, do not proceed until it is clear and safe to do so. Do not assume that you have the right of way."},{"id":"419","category_id":"4","question":"What should a driver do if they see a school bus stopped on the nearside (left side) of the road ahead?","img":"","options":["Signal and maintain current speed.","Reduce speed and overtake with caution.","Sound the horn as a warning and continue on.","Switch on hazard warning lights and stop behind the bus."],"answer":["option_2"],"explanation":"Always read the road and be prepared to react to any traffic situation – in this case, be aware of vulnerable road users such as school children boarding or alighting from school buses."},{"id":"420","category_id":"4","question":"What should the driver do when driving behind a vehicle that is going from side to side on the road in an unsafe manner?","img":"","options":["The driver should signal and go around to the right of the vehicle.","The driver should stay well back in a safe position.","The driver should signal and go around to the left of the vehicle.","The driver should drive close behind the vehicle with a view to overtaking."],"answer":["option_2"],"explanation":"You should always be prepared to react to hazards ahead. If the vehicle in front is moving from side to side, it may indicate that the driver is not paying full attention or that their driving is impaired by drink, drugs or tiredness. If you think the vehicle is a risk to the public safety, the matter should be reported to the Gardaí or to Traffic Watch (lo-call 1890 205 805), but not while driving."},{"id":"421","category_id":"4","question":"What should a driver do if a heavy goods vehicle in front has moved out to make a left turn ahead?","img":"","options":["Move to the right but do not overtake.","Stay behind it and allow it to complete the turn.","Drive into the space on its left-hand side.","Move out immediately and overtake as quickly as possible."],"answer":["option_2"],"explanation":"Always read the road ahead and be prepared to react to any traffic situation. In this case, you should be aware that the heavy goods vehicle will need extra space to complete the left-hand turn and you should remain behind the vehicle until it has completed its turn."},{"id":"422","category_id":"4","question":"What should a driver do if a bus in front has moved out to make a left-hand turn and there is oncoming traffic?","img":"","options":["Overtake on the left-hand side.","Overtake on the right-hand side.","Maintain speed until up close behind the bus.","Stay back and allow the bus to complete the turn."],"answer":["option_4"],"explanation":"Always read the road ahead and be prepared to react to any traffic situation. In this case, you should be aware that the bus will need extra space to make the turn. So you should not overtake it if by doing so you would cause oncoming traffic to alter speed or course. Remember, you should never overtake when approaching a junction."},{"id":"423","category_id":"4","question":"What should a driver do if they are first in line to turn right at traffic lights while the green light is showing and there is oncoming traffic approaching?","img":"","options":["Wait at the stop line for the light to turn amber and then make the turn.","Go forward towards the centre of the junction and turn safely when a suitable gap appears.","Remain at the stop line until a green arrow comes on.","Remain at the stop line until a suitable gap in the oncoming traffic appears before making the turn."],"answer":["option_2"],"explanation":"If you wish to turn right at a set of traffic lights, drive into the junction when you see a green light, taking care not to block any oncoming traffic. Then complete the turn when it is safe to do so."},{"id":"424","category_id":"4","question":"When meeting oncoming traffic on a national road, is it permitted to move into the hard shoulder to allow following traffic to overtake?","img":"","options":["Yes, when a truck or bus is oncoming.","No, except on ‘2-plus-1 roads’.","No, it is never permitted to drive on a hard shoulder except in the case of an emergency.","Yes, temporarily when the hard shoulder is clear and it is safe to drive there."],"answer":["option_4"],"explanation":"On national roads, the hard shoulder is normally for the use of pedestrians and cyclists only. If you want to allow a vehicle behind to overtake, you may pull into the hard shoulder briefly as long as no pedestrians or cyclists are using it and there are no junctions or entrances nearby. In the case of motorways, however, you must not drive on the hard shoulder, except in an emergency."},{"id":"425","category_id":"4","question":"When driving on a national road is it permitted to drive on the hard shoulder in order to allow faster-moving traffic to overtake?","img":"","options":["Only when driving on a dual carriageway.","No, except when driving on a ‘2-plus-1 road’.","Yes, temporarily when the hard shoulder is clear and it is safe to drive there.","Only when a truck or bus wants to overtake."],"answer":["option_3"],"explanation":"On national roads, the hard shoulder is normally for the use of pedestrians and cyclists only. If you want to allow a vehicle behind to overtake, you may pull into the hard shoulder briefly as long as no pedestrians or cyclists are using it and there are no junctions or entrances nearby. In the case of motorways, however, you must not drive on the hard shoulder, except in an emergency."},{"id":"426","category_id":"4","question":"What should a driver do in a queue of traffic controlled by traffic lights?","img":"","options":["Put on a right signal to prevent following vehicles from overtaking.","Overtake on the right and move to the head of the queue if there is space available.","A driver should maintain their position in the queue.","Overtake on the left and move to the head of the queue if there is space available."],"answer":["option_3"],"explanation":"Always read the road ahead and be prepared to react to any traffic situation. From time to time you may have to queue in traffic. In this situation, you should try to remain patient and considerate of other road users. Jumping the queue is inconsiderate, it could be dangerous, and it could even provoke a road rage incident or cause a collision."},{"id":"427","category_id":"4","question":"Subject to the speed limit, what is the ‘safest’ speed to drive at?","img":"","options":["The speed of the slowest vehicle on the road.","A driver should always try to drive at the speed limit for the road that they are on.","The speed that will enable the driver to stop the vehicle within the distance ahead that they can see to be clear.","A driver should always try to drive at the speed of other road users, regardless of the speed limit."],"answer":["option_3"],"explanation":"You should always drive at a speed that allows you to stop within the distance that you can see to be clear ahead. If you don’t think you could safely bring the vehicle to a stop within the range of what you can see, then you’re driving too fast – slow down."},{"id":"428","category_id":"4","question":"When driving along and wishing to use a hand-held mobile phone, what should a driver do?","img":"","options":["Secure the phone between head and shoulders while steering with both hands.","Move the phone as needed and keep the call to just a few minutes.","Steer with one hand.","Stop at a safe location before using the phone."],"answer":["option_4"],"explanation":"It is an offence and very unsafe to use a hand-held mobile phone while driving a vehicle or riding a motorbike as it prevents you from concentrating fully on your driving. While using a hands-free phone kit is not illegal, in some circumstances it could be a dangerous distraction, and you could be prosecuted for dangerous driving, careless driving or driving without due care and attention. If a driver needs to make a call they should pull in and stop in a place where it is safe to do so."},{"id":"429","category_id":"4","question":"When stopped at traffic lights and the green light comes on, what should a driver do?","img":"","options":["Accelerate at a greater rate than other drivers so as to facilitate overtaking.","Move off slowly and then check the mirrors.","Check that other road users have cleared the junction and move off with care.","Move off quickly and then check the mirrors."],"answer":["option_3"],"explanation":"When stopped at traffic lights and the green light comes on, you should check to ensure the way is clear and proceed only if it is safe to do so."},{"id":"430","category_id":"4","question":"What should a driver do if another vehicle blocks their right of way at a junction?","img":"","options":["Pursue the vehicle and express displeasure.","Be patient and show restraint.","Flash the headlights to express displeasure.","Sound the horn and flash the lights to show your frustration."],"answer":["option_2"],"explanation":"You should always try to show restraint. It is important to understand that the right of way is not an absolute right of way, and you must always proceed with caution and with regard for other road users. It’s safer and more socially responsible."},{"id":"431","category_id":"4","question":"When being overtaken and there is oncoming traffic, what should a driver do?","img":"","options":["Allow the overtaking vehicle to pass and return safely to the left side of the road.","Maintain position because other drivers should not have attempted to overtake.","Speed up so the following vehicle cannot overtake.","Maintain position and flash the headlights to warn the oncoming traffic."],"answer":["option_1"],"explanation":"When you are being overtaken and there are oncoming vehicles, you should show consideration for all the other traffic and allow the overtaking vehicle to move in front of you to avoid the risk of a collision."},{"id":"432","category_id":"4","question":"What should a driver do when they get a puncture while driving?","img":"","options":["Continue on your journey and arrange for repair when convenient.","If on a motorway, stop and change the wheel immediately.","Stop at a safe place and change the wheel.","Maintain speed until a place to change the wheel is identified."],"answer":["option_3"],"explanation":"If you get a puncture while driving, find a suitable and safe place to stop and change the wheel. If you cant find a suitable place immediately, drive slowly (with your hazard warning lights turned on) to avoid further damage to the tyre or rim until a safe place is found."},{"id":"433","category_id":"4","question":"What should a driver do when they want to safely change to the lane on the right in which there is other traffic?","img":"","options":["Move gradually into the right-hand lane, indicate and then check mirrors.","Pull in and stop, wait until a suitable gap appears and then move out to the right-hand lane.","Increase speed until travelling at the same speed as the traffic in the right lane, then move over and check mirrors.","Use the mirror, signal and move into the right-hand lane when a suitable gap appears in the traffic in that lane."],"answer":["option_4"],"explanation":"Any time you change lanes, you should use the Mirror–Signal–Mirror (blind spots)–Manoeuvre routine. Check your mirrors, signal your intention, check your mirrors again (and your blind spots), and when a suitable gap becomes available manoeuvre the vehicle into the next lane, giving way to traffic already in that lane."},{"id":"434","category_id":"4","question":"What effect does alcohol have on driver behaviour?","img":"","options":["It can increase perception and awareness.","It slows down a driver’s reactions.","It does not affect driver behaviour or ability.","It can reduce a driver’s confidence."],"answer":["option_2"],"explanation":"Alcohol is a major factor in collisions that can lead to death and injury. Even small amounts of alcohol affect your judgement and ability to drive."},{"id":"435","category_id":"4","question":"What effect does drinking alcohol have on a driver?","img":"","options":["It increases concentration.","It improves coordination.","It reduces concentration.","It increases awareness."],"answer":["option_3"],"explanation":"Alcohol is a major factor in collisions that lead to death and injury. Even small amounts of alcohol affect your judgement, your concentration and your ability to react to hazards. A driver should never ever drink and drive."},{"id":"436","category_id":"4","question":"If a motorist or a motorcyclist is taking medication which may affect their driving, what should they do?","img":"","options":["Drink plenty of water while driving.","Seek medical advice in relation to driving.","Drive slower when under the influence of medication that affects driving.","Drive for short distances only."],"answer":["option_2"],"explanation":"Some medication can affect a driver’s ability to drive safely. If you are on medication of any kind, you should ask your doctor or pharmacist to tell you if it is safe to drive while taking it. Read the patient information leaflet supplied with the medication."},{"id":"437","category_id":"4","question":"What effect does a wet road surface have on a vehicle’s braking ability?","img":"","options":["It reduces the braking distance of that required on a dry surface.","Modern tyres provide grip on a wet road as effectively as on a dry road.","It makes no difference to the required braking distance.","Generally, it doubles the braking distance of that required on a dry surface."],"answer":["option_4"],"explanation":"When it is wet, your tyres do not grip the road surface as well as when it is dry and your stopping distance is increased. For these reasons you should slow down during or after rain and keep a greater distance from the vehicle in front."},{"id":"438","category_id":"4","question":"After overtaking another vehicle, what should a driver do?","img":"","options":["Continue to signal right for a distance.","Move back in front of the vehicle and reduce speed.","Gradually move back into the left when the vehicle has been passed.","Move immediately into the left after passing the vehicle."],"answer":["option_3"],"explanation":"After overtaking, check your mirrors, signal and return to your normal lane position as soon as it is safe. Take a smooth easy line, gradually moving back in and allowing the other vehicle plenty of space and don’t cut in sharply."},{"id":"439","category_id":"4","question":"What would happen if a driver cuts in too soon when overtaking another vehicle?","img":"","options":["It will force oncoming vehicles to suddenly slow causing danger.","The driver would not need to indicate when moving in.","The safety gap between the vehicles increases.","It would force the other vehicle to suddenly slow or change direction causing danger."],"answer":["option_4"],"explanation":"When overtaking make sure the road ahead is clear so you have enough distance to overtake and get back to your own side of the road without forcing any other road user to adjust speed or direction. When you are well past the vehicle, check the mirrors, signal and gradually return to the original lane, making sure not to cut across the vehicle you have passed."},{"id":"440","category_id":"4","question":"What stopping distance should a driver allow for when driving in snow or icy conditions?","img":"","options":["Up to half the normal distance.","The normal distance.","Up to ten times the normal distance.","Twice the normal distance."],"answer":["option_3"],"explanation":"When driving in snow or icy conditions a driver should allow a greater distance from the vehicle in front as stopping distances can be increased by up to ten times the normal."},{"id":"441","category_id":"4","question":"What clearance should drivers normally allow for when passing parked vehicles?","img":"","options":["A door width.","The width of an average person.","The width of a side mirror.","A car width."],"answer":["option_1"],"explanation":"When you are passing parked vehicles, you should leave at least a door’s width of clearance in case somebody opens their car door unexpectedly, this will also increase visibility of pedestrians in the area."},{"id":"442","category_id":"4","question":"Why does it take longer to stop the vehicle on a wet road?","img":"","options":["The tyres have less road grip than in dry weather.","The suspension of the vehicle is lighter in wet weather.","The tyres have more grip than in dry weather.","The brake fluid is less effective in wet weather."],"answer":["option_1"],"explanation":"When driving on wet road surfaces the grip of your tyres is reduced which may lead to significantly longer stopping distances. Drivers should be aware of these conditions and reduce speed as stopping quickly may result in skidding."},{"id":"443","category_id":"4","question":"What is the effect on the control of the vehicle if there is a film of water between the vehicle’s tyres and the road surface?","img":"","options":["Steering and braking will be more effective.","Steering will be more effective.","Braking only will be less effective.","Steering and braking will be less effective."],"answer":["option_4"],"explanation":"When driving on a road where there is a lot of surface water, a film of water can build up between the tyres and the road surface. When this occurs it is called aquaplaning, it reduces the grip of the tyres on the road and can result in the total loss of control over the vehicle’s steering and braking."},{"id":"444","category_id":"4","question":"What should a driver do if they encounter loose chippings on a road?","img":"","options":["Slow down and allow extra clearance to other traffic.","A driver should press their hand against the windscreen.","Increase speed so as to avoid causing damage to the vehicle.","Stop the vehicle until the loose chippings can be removed."],"answer":["option_1"],"explanation":"Where there are loose chippings on the road, you should slow down and comply with any reduced speed limit and leave extra room (or clearance) between your vehicle and other traffic. This will also give you more time to stop if you need to, and it will help to reduce the amount of chippings your vehicle throws up against other vehicles and possible injury to pedestrians."},{"id":"445","category_id":"4","question":"What should a driver do when driving in slippery road conditions?","img":"","options":["Drive at normal speed but allow extra stopping distance.","Maintain a normal distance from the vehicle in front.","Apply the brakes sharply from time to time to test the road surface.","Drive at lower speeds and use gentle acceleration and braking."],"answer":["option_4"],"explanation":"When driving in slippery road conditions, drivers should be particularly smooth and gradual in the way they accelerate and brake. This will help to avoid skidding or slipping and helps to maintain control of the vehicle."},{"id":"446","category_id":"4","question":"What should a driver do when travelling downhill on snow or ice?","img":"","options":["Select an appropriate gear and brake gently to control speed.","Use a higher gear than normal in order to avoid wheel spin.","Avoid using the brake and use a high gear.","Keep close to the left and brake sharply to reduce speed."],"answer":["option_1"],"explanation":"When travelling downhill in snow or ice, you should select a lower gear to take advantage of engine braking and use the brakes very gently when you need to."},{"id":"447","category_id":"4","question":"What is the recommended minimum stopping distance for a car travelling at 50 km/h on a dry road?","img":"","options":["55 metres.","15 metres.","25 metres.","5 metres."],"answer":["option_3"],"explanation":"The total minimum stopping distance of a vehicle depends on four things: Perception time, reaction time, the vehicle’s speed and the vehicle’s braking capability. The recommend minimum stopping distance of a car driving at 50 km/h under dry conditions is 25 metres."},{"id":"448","category_id":"4","question":"What is the recommended minimum stopping distance for a car travelling at 50 km/h on a wet road?","img":"","options":["56 metres.","76 metres.","36 metres.","16 metres."],"answer":["option_3"],"explanation":"The total minimum stopping distance of a vehicle depends on four things: Perception time, reaction time, the vehicle’s speed and the vehicle’s braking capability. The recommend minimum stopping distance of a car driving at 50 km/h under wet conditions is 36 metres."},{"id":"449","category_id":"4","question":"What is the recommended minimum stopping distance for a car travelling at 100 km/h on a dry road?","img":"","options":["70 metres.","120 metres.","90 metres.","30 metres."],"answer":["option_1"],"explanation":"The total minimum stopping distance of a vehicle depends on four things: Perception time, reaction time, the vehicle’s speed and the vehicle’s braking capability. The recommend minimum stopping distance of a car driving at 100 km/h under dry conditions is 70 metres."},{"id":"450","category_id":"4","question":"In dry weather how might a driver judge what is a safe following distance to vehicle in front?","img":"","options":["By allowing at least two vehicle lengths between the vehicles.","Drive at the same speed as the vehicle in front.","Allow a least two vehicle lengths for each kilometre per hour.","By using a fixed point and applying the two second rule."],"answer":["option_4"],"explanation":"A driver can judge a safe distance from the vehicle in front by using the two second rule. This is measured by picking a fixed point. As the vehicle in front passes it, begin saying “only a fool breaks the two second rule”. If you pass the fixed point before you have finished the phrase, then your vehicle is too close, safely slow and increase your distance from the vehicle in front."},{"id":"451","category_id":"4","question":"In wet weather how might a driver judge what is a safe following distance from the vehicle in front?","img":"","options":["By allowing at least two seconds to elapse between the vehicle in front and the driver’s own vehicle passing a fixed point.","By allowing four vehicle lengths between the vehicles.","By allowing two vehicle lengths between the vehicles.","By allowing at least four seconds to elapse between the vehicle in front and the driver’s own vehicle passing a fixed point."],"answer":["option_4"],"explanation":"In wet conditions you should maintain a gap of at least four seconds from the vehicle in front – at least twice as long as in dry conditions."},{"id":"452","category_id":"4","question":"What phrase is recommended for drivers to help them determine a safe distance from the vehicle in front on a dry road?","img":"","options":["“Only a fool breaks the two second rule.”","“Only a fool breaks the one second rule.”","“Only a fool breaks the four second rule.”","“Only a fool breaks the three second rule.”"],"answer":["option_1"],"explanation":"A driver can judge a safe distance from the vehicle in front by using the two second rule. This is measured by picking a fixed point. As the vehicle in front passes it, begin saying “only a fool breaks the two second rule”. If you pass the fixed point before you have finished the phrase, then your vehicle is too close. Safely slow and increase your distance from the vehicle in front."},{"id":"453","category_id":"4","question":"What lights should a driver use when driving in dense fog?","img":"","options":["Drive with sidelights and hazard warning lights.","Drive with dipped headlights and fog lights.","Drive with full headlights and fog lights.","Drive with sidelights and fog lights."],"answer":["option_2"],"explanation":"In dense fog you should use dipped headlights and fog lights (where fitted). Sidelights are not strong enough in fog, and full headlights can reflect off the fog and make it harder to see where you are going."},{"id":"454","category_id":"4","question":"What are the possible consequences of having incorrectly adjusted headlights?","img":"","options":["Oncoming road users could be dazzled.","The wattage of the headlights could be reduced.","Visibility could be increased.","The headlights could overheat."],"answer":["option_1"],"explanation":"You are responsible for making sure that your vehicle is roadworthy and that its headlights are adjusted correctly. If the headlights are out of line they are less effective and may dazzle oncoming traffic, even when dipped."},{"id":"455","category_id":"4","question":"When driving at night and blinded by the lights of an oncoming vehicle, what should a driver do?","img":"","options":["Look towards the verge and slow down and stop if necessary.","Drive well to the left and maintain normal speed.","Repeatedly flash the headlights to warn the offending driver.","Reduce speed and switch on the full headlights."],"answer":["option_1"],"explanation":"If you are dazzled by the lights of an oncoming vehicle, look towards the verge until the vehicle has passed. Slow down and stop if necessary."},{"id":"456","category_id":"4","question":"A driver has been driving regularly in daylight and must now undertake a journey at night. What should the driver do?","img":"","options":["Drive at a higher speed than during the day to minimise the chances of falling asleep.","Drive at a higher speed than during the day as traffic is lighter at night.","Drive at a slower speed than in the day as visibility is reduced at night.","Drive at the same speed as during the day as there is no extra danger."],"answer":["option_3"],"explanation":"If you are not familiar with driving at night time, it can take quite a while to adjust to conditions. For that reason, you might need to drive slower until you get used to the reduced visibility at night."},{"id":"457","category_id":"4","question":"With regard to vehicle speed, what should a driver do when driving at night?","img":"","options":["Maintain normal vehicle speed and drive with full headlights.","Drive at a higher speed than during the day to reduce the chances of falling asleep.","Drive at a speed that enables the driver to stop within the distance ahead that they can see to be clear.","Increase vehicle speed as traffic is lighter at night."],"answer":["option_3"],"explanation":"When driving at night in good driving conditions the full headlights of a car will typically let you see 100 metres ahead. So, you should travel at a speed that allows you to stop in that distance."},{"id":"458","category_id":"4","question":"When driving at night, what is the safest approach for a driver to adopt?","img":"","options":["Drive with full headlights on at all times.","Drive at the maximum speed limit with full headlights on to see clearly ahead.","Drive at the maximum speed limit with dipped headlights on at all times.","Drive at a speed that enables the driver to stop within the distance ahead that they can see to be clear."],"answer":["option_4"],"explanation":"When driving at night in good driving conditions the dipped headlights of a car will typically let you see 30 metres ahead. So, you should travel at a speed that allows you to stop in that distance."},{"id":"459","category_id":"4","question":"When is it safe for a driver to use the main beam headlights when driving at night?","img":"","options":["In built up areas where there is good street lighting.","This practice is not permitted.","When there is no oncoming traffic.","When following a vehicle a short distance ahead."],"answer":["option_3"],"explanation":"Drivers should use the main beam headlights, to improve visibility, when driving at night in unlit rural areas – this will enable them to see as far ahead as possible. Making sure, however, that these lights are dimmed where necessary to avoid dazzling or inconveniencing other road users."},{"id":"460","category_id":"4","question":"What lights should a driver have on when driving behind other traffic at night?","img":"","options":["Side lights.","Dipped headlights.","Main beam headlights.","Front fog lights."],"answer":["option_2"],"explanation":"Drivers should dip their headlights when driving behind another vehicle so the driver in front is not dazzled by your lights in their mirror."},{"id":"461","category_id":"4","question":"When driving at night, when must a driver use dipped headlights?","img":"","options":["When there is no oncoming traffic.","When meeting or driving behind other traffic.","When driving at more than 100 km/h.","When driving at less than 50 km/h."],"answer":["option_2"],"explanation":"When driving at night drivers should dip their main beam headlights when meeting or following traffic to avoid dazzling or endangering other road users."},{"id":"462","category_id":"4","question":"When dazzled by the lights of an oncoming vehicle, what should a driver do?","img":"","options":["Do not look directly at the lights.","Shield their eyes with their hand.","Look at the dashboard momentarily.","Turn their head to the right."],"answer":["option_1"],"explanation":"If dazzled by the lights of an oncoming vehicle, do not look directly at the oncoming lights. Instead glance towards the verge until the vehicle has passed and/or slow down and stop if necessary. This will avoid any temporary blindness caused by the brightness of the oncoming lights."},{"id":"463","category_id":"4","question":"When should a driver use fog lights on their vehicle?","img":"","options":["Use fog lights to improve visibility during light rain.","Switch on fog lights as a warning to pedestrians.","Use fog lights only in dense fog and falling snow.","Use fog lights on a badly lit country road."],"answer":["option_3"],"explanation":"A driver should use fog lights only during dense fog or falling snow. They must be switched off at all other times."},{"id":"464","category_id":"4","question":"When can a driver expect to encounter black ice?","img":"","options":["Only late at night.","When the temperature drops close to freezing.","Black ice only occurs on motorways.","Only in the early hours of the morning."],"answer":["option_2"],"explanation":"Black ice is an almost invisible and thin coating of ice on the surface of the road. Sometimes it can look like a sheet of water or as if the road is wet."},{"id":"465","category_id":"4","question":"What should a driver do if there is black ice on the road?","img":"","options":["Apply the brakes regularly to prevent them from freezing.","Only use a low gear to improve traction.","Avoid harsh braking, steering and acceleration.","Apply the brakes regularly to check road surface."],"answer":["option_3"],"explanation":"If a driver suspects black ice, they should avoid harsh braking, steering and acceleration. This will help reduce the risk of skidding."},{"id":"466","category_id":"4","question":"Where is black ice likely to occur on the road?","img":"","options":["In mild weather on a coastal road.","On a hard shoulder only.","In sheltered or shaded areas.","Only in built-up areas."],"answer":["option_3"],"explanation":"Black ice occurs when moisture freezes on a very cold surface. Exposed roads and bridges can have black ice when other sections of the same road may be clear. Black ice is virtually invisible, and so presents a particular hazard for motorcyclists and drivers. In wintry conditions, if you notice a reduction in tyre noise or if the steering becomes lighter, you should suspect that there may be black ice on the road."},{"id":"467","category_id":"4","question":"What is the safest practice when driving on icy roads?","img":"","options":["Drive at normal speed but apply the brakes from time to time to check for grip.","Rely completely on the ABS or other advanced driver assistance systems.","Drive at a slower speed than usual using gentle acceleration and braking.","Drive in a low gear at all times using maximum acceleration."],"answer":["option_3"],"explanation":"When driving on icy roads a driver should avoid harsh braking, steering and acceleration. This will help reduce the risk of skidding."},{"id":"468","category_id":"4","question":"When driving, what effect could icy roads have on the vehicle?","img":"","options":["The vehicle would be more likely to skid.","Front tyre pressure increases.","Tyre grip improves in lower temperatures.","Rear tyre pressure increases."],"answer":["option_1"],"explanation":"Icy roads can have a dramatic effect on the way a vehicle handles, and there can be an increased risk of skidding. When driving on icy roads a driver should avoid harsh braking, steering and acceleration. This will help reduce the risk of skidding."},{"id":"469","category_id":"4","question":"What should a driver do when driving in slippery road conditions?","img":"","options":["Accelerate harder using only the lower gears.","Drive slower than normal keeping a close distance to the vehicle in front.","Use gentle acceleration and braking.","Brake regularly to improve tyre grip."],"answer":["option_3"],"explanation":"Tyres have less grip on the road when it is wet or icy. Slow down in slippery conditions, and keep a greater distance from the vehicle in front."},{"id":"470","category_id":"4","question":"Apart from the risk of skidding, what should the driver be aware of when driving in snow?","img":"","options":["Road signs and road markings may become obscured.","The power steering fluid may freeze causing the steering to fail.","The air in the tyres may freeze, causing them to burst.","The brake fluid may freeze, causing the brakes to fail."],"answer":["option_1"],"explanation":"Road signs and road markings may become obscured by snow. If this happens you may have difficulty reading regulatory, warning and information signs. This is the main reason why these signs are different shapes. Drivers should pay particular attention when travelling in these conditions."},{"id":"471","category_id":"4","question":"What should a driver do when driving in heavy rain?","img":"","options":["Maintain normal speeds as on a dry road.","Weave the vehicle slightly in order to improve tyre grip.","Increase speed so that the vehicle will glide over any standing water.","Be aware that the vehicle may slide or ‘aquaplane’."],"answer":["option_4"],"explanation":"On a wet road, a film of water can build up between the tyres and the road surface. This is called aquaplaning and it has the effect of reducing the grip of the tyres on the road, and this affects the steering and braking. For these reasons the driver should slow down during and after rain and keep a greater distance from the vehicle in front."},{"id":"472","category_id":"4","question":"What is the danger in driving at high speeds on wet roads?","img":"","options":["There is no danger provided that the tyre pressure has been reduced to take account of weather conditions.","There is no danger provided that the tyre pressure has been increased to take account of weather conditions.","Danger of ‘aquaplaning’ or sliding across the road surface.","Danger that tyre pressure will automatically increase."],"answer":["option_3"],"explanation":"The driver should moderate their speed during heavy rain or where water is building up on the road surface. This will help to avoid ‘aquaplaning’ which has the effect of reducing the grip of the tyres on the road, and this affects the steering and braking. For these reasons the driver should slow down during and after rain and keep a greater distance from the vehicle in front."},{"id":"473","category_id":"4","question":"What should a driver do when they encounter mud on the road?","img":"","options":["Change to a lower gear and pump the brakes to see how slippery the surface is.","Apply the brakes immediately and put on the hazard warning lights.","Reduce speed and be aware of farm or works vehicles on the road.","Gradually increase speed so that the mud on the road will not stick to the tyres."],"answer":["option_3"],"explanation":"Where there is mud on the road you should slow down and be aware that there is a danger of skidding. Your stopping distance will also be greater where there is mud on the road."},{"id":"474","category_id":"4","question":"What should a driver do after passing through a flooded section of road?","img":"","options":["Apply the handbrake gradually to dry out the rear brakes only.","Apply the brake pedal lightly at slow speed for a short distance to dry the brakes.","Increase the speed of the vehicle to dry out the brakes.","Apply the brakes firmly to check if they are still effective."],"answer":["option_2"],"explanation":"When driving through a flooded section of road, brakes may become less effective. If this happens, test brakes to ensure that they have not been affected by the water – check mirrors before doing so. If they have been affected, press gently on the brake pedal when driving until they dry out and return to normal."},{"id":"475","category_id":"4","question":"What should a driver do where a section of road ahead has a shallow flooded area?","img":"","options":["Use a high gear and maintain the same speed keeping the engine revs low.","Decrease speed and use a higher gear.","Drive in a low gear as slowly as possible keeping the revs high.","Increase speed and use a higher gear."],"answer":["option_3"],"explanation":"When approaching a stretch of road with shallow flooding, reduce speed and assess the area for any danger. When driving through surface water, drive in a low gear as slowly as possible keeping the revs high to avoid stalling."},{"id":"476","category_id":"4","question":"When a driver wants to turn left into a property and there is a bus lane on the left, what should the driver do?","img":"","options":["Give way to cyclists, taxis and buses which may be using the bus lane.","Give way to cyclists and taxis which may be using the bus lane.","A driver should never turn left across a bus lane.","A driver should give way to buses only."],"answer":["option_1"],"explanation":"If a driver needs to cross a bus lane on their left in order to enter a property, they should take extra care that there are no buses, taxis or cyclists in the bus lane. They should check mirrors, signal and turn into the property when it is safe to do so."},{"id":"477","category_id":"4","question":"What traffic may use a contra-flow bus lane?","img":"","options":["Buses on a scheduled service.","Buses and motorised wheelchairs only.","Buses, taxis and cyclists.","Buses, taxis and motorcycles."],"answer":["option_1"],"explanation":"A contra-flow bus lane is one that runs in the opposite direction to traffic beside it. Only buses on a scheduled service may use a contra-flow bus lane."},{"id":"478","category_id":"4","question":"What traffic may use a with-flow bus lane during the times specified on information signs at the start of the lane?","img":"","options":["Vehicles with more than one passenger.","Buses only.","All traffic.","Buses, taxis and cyclists."],"answer":["option_4"],"explanation":"A bus lane is a special lane for the use of buses. A with-flow bus lane is one that runs in the same direction as the traffic beside it. Taxis and cyclists may also use with-flow bus lanes. Other traffic may use them outside the hours posted on the accompanying plate."},{"id":"479","category_id":"4","question":"When driving along a dual carriageway in normal driving conditions, which lane should a driver be in?","img":"","options":["In the right-hand lane except when driving a works vehicle or HGV.","In the right-hand lane.","In the left-hand lane unless the driver wishes to overtake or turn right.","In either lane."],"answer":["option_3"],"explanation":"You must normally drive in the left-hand lane of a dual carriageway, except when overtaking or turning right a short distance ahead."},{"id":"480","category_id":"4","question":"What does a 2-plus-1 road have?","img":"","options":["Two lanes of traffic in one direction and one in the opposite direction.","Barriers between the hard shoulder and the verge.","Barriers between lanes of traffic going in the same direction.","Two lanes for cars and one lane for trucks and buses."],"answer":["option_1"],"explanation":"A 2–plus-1 road consists of two lanes in one direction of travel and one lane in the other direction. The two-lane section allows for safe overtaking and alternates with a one-lane section roughly every 2 kilometres."},{"id":"481","category_id":"4","question":"What should a driver do when travelling on a motorway or dual carriageway?","img":"","options":["Relax because there will be no oncoming traffic.","Be alert for other drivers who may suddenly change lanes or reduce speed.","Match the speed to that of the vehicle in front.","Match the speed to that of the vehicle in the adjoining lane."],"answer":["option_2"],"explanation":"Motorways and dual carriageways are designed to help traffic travel faster and more safely between destinations. Traffic conditions can change very quickly because of the speed and increased volumes of traffic and lanes, and you need to be particularly alert to other drivers changing lanes or reducing speed."},{"id":"482","category_id":"4","question":"In normal driving conditions on a motorway, which lane should the driver occupy?","img":"","options":["Drive in the offside (right-hand) lane as the nearside (left-hand) lane is for HGVs and buses only.","Constantly manoeuvre between whichever lane has the least volume of traffic.","Drive in the offside (right-hand) lane unless intending to take a left exit.","Drive in the nearside (left-hand) lane unless intending to overtake."],"answer":["option_4"],"explanation":"The normal keep left rules apply when you are driving on a motorway – a driver should stay in the nearside (left-hand) lane unless they are overtaking."},{"id":"483","category_id":"4","question":"What should a driver do when joining a motorway from a slip road?","img":"","options":["Drive directly onto the motorway as the driver on the acceleration lane has right of way.","Try to match the vehicle speed to that of traffic already on the motorway and merge into it in a suitable gap.","Drive along the hard shoulder until a suitable gap appears in the motorway traffic to allow the driver to merge into it.","Always stop at the end of the acceleration lane and yield to traffic on the motorway."],"answer":["option_2"],"explanation":"When joining a motorway a driver should try to match their speed to that of the motorway traffic and merge into it when a suitable gap appears, avoiding driving in the hard shoulder, while yielding to traffic already on the motorway."},{"id":"484","category_id":"4","question":"Is a driver permitted to pick up or set down a passenger on a motorway?","img":"","options":["It is only permitted within 200 metres of a slip-road.","A driver is never permitted to pick up or set down passengers on a motorway.","It is not permitted, except during daylight hours.","It is permitted provided that the driver stops on the hard-shoulder."],"answer":["option_2"],"explanation":"Motorways are designed so that traffic can move faster and more freely. It is illegal and dangerous to stop a vehicle on any part of a motorway except in an emergency or when signalled to do so by a Garda."},{"id":"485","category_id":"4","question":"When driving on a motorway, what should a driver do if they miss their exit?","img":"","options":["Wait on the hard shoulder until a suitable gap appears in traffic from both directions and then cross to the opposite side of the motorway.","Stop on the hard shoulder, switch on their hazard lights and reverse back to the desired exit.","Leave the motorway at the next exit and cross to the other side using the fly-over (or underpass).","Cross to the opposite side of the motorway when there is a suitable gap in the oncoming traffic."],"answer":["option_3"],"explanation":"If a driver misses their intended exit when driving on a motorway, they should proceed to the next junction exit where they can leave the motorway and then rejoin it on the opposite side of the motorway."},{"id":"486","category_id":"4","question":"What should a driver do when entering a slip road after leaving a motorway?","img":"","options":["There is never a need to adjust speed when on a slip road.","Brake severely when entering the slip road in order to slow down.","Comply with the speed limit on the road the driver is joining.","Always reduce speed gradually for a few kilometres."],"answer":["option_3"],"explanation":"When a driver is leaving a motorway, they should enter the deceleration lane and reduce their speed. They should comply with the speed limit of the road they are entering."},{"id":"487","category_id":"4","question":"What should a driver do if they drive past their intended exit by mistake?","img":"","options":["Stop on the hard shoulder and reverse back to the exit.","Use the emergency telephone to ask for advice.","Drive on and leave at the next exit.","Carefully complete a U-turn."],"answer":["option_3"],"explanation":"If a driver misses their intended exit when driving on a motorway, they should proceed to the next junction exit where they can leave the motorway and then rejoin it in the opposite direction."},{"id":"488","category_id":"4","question":"What is the main difference between driving on a motorway and driving on other types of road?","img":"","options":["Traffic travelling at 120 km/h must only use the outside lane of a motorway.","Traffic is generally permitted to travel at a higher speed on a motorway.","Traffic generally travels at lower speeds on a motorway than on a dual-carriageway.","Learner permit holders must be accompanied by a full licence holder."],"answer":["option_2"],"explanation":"Motorways are designed so that traffic can move faster and more freely, without traffic lights, crossroads, level crossings and other road features that might slow down traffic. There are also restrictions on who may use a motorway – for example learner-drivers and motorcycles under 50 cc are prohibited."},{"id":"489","category_id":"4","question":"On a 2-lane motorway, what procedure should a driver adopt when wishing to overtake another vehicle safely?","img":"","options":["Check for following traffic and overtake in either lane.","Use their mirrors, signal and overtake in the right-hand lane when it is safe to do so.","Use their mirrors, signal and overtake in the left-hand lane only.","Signal, use their mirrors and overtake in any available lane when it is safe to do so."],"answer":["option_2"],"explanation":"When a driver wants to overtake on a motorway, they should generally only overtake on the right unless traffic is travelling in slow moving queues. The driver should use the Mirror–Signal–Mirror (blind spots)–Manoeuvre routine. Check mirrors, signal intention, check mirrors again (and blind spots), and complete the manoeuvre when it is safe to do so. They should pay particular attention to the speed of the traffic behind them before they move out. When they have finished overtaking, they should move back into the left-hand lane smoothly."},{"id":"490","category_id":"4","question":"What may the hard shoulder of a motorway be used for?","img":"","options":["Joining the motorway.","Stopping to use a mobile phone.","Stopping in an emergency.","Exiting the motorway."],"answer":["option_3"],"explanation":"There are extra dangers when driving on a motorway because of the increased volume of traffic and higher speed. For safety reasons a driver should not drive or stop on the hard shoulder of a motorway except in an emergency or breakdown."},{"id":"491","category_id":"4","question":"After exiting the motorway and coming towards a junction at the end of the deceleration lane (slip road) what should a driver do?","img":"","options":["Maintain motorway speeds to the end of the slip road.","The driver must always stop at the end of a slip road.","The driver should continue at the junction as traffic on the slip road has right of way.","Be alert for oncoming and crossing traffic at the end of the slip road."],"answer":["option_4"],"explanation":"The driver should check for signs showing a lower speed; use the speedometer to make sure that they are obeying the reduced speed limit; remember that the slip roads and link roads between motorways may include sharp bends and that they may encounter junctions and other traffic. Remember that motorway rules no longer apply."},{"id":"492","category_id":"4","question":"A driver wishes to go straight ahead at a cross junction of equal importance. If they encounter other traffic, what is the general rule that applies?","img":"","options":["Give way to traffic approaching firstly from the left and then the right.","Carry on as normal as they always have the right of way.","Give way to traffic approaching from the left only.","Traffic approaching from the driver’s right has right of way."],"answer":["option_4"],"explanation":"If a driver is at a junction where the roads are of equal importance, traffic on the driver’s right has the right of way. The driver must let that traffic pass before moving on. It is important to understand that the right of way is not an absolute right. Drivers must proceed with caution whilst showing regard for other users of the road."},{"id":"493","category_id":"4","question":"In general, where two lanes are provided on the approach to a roundabout, which lane should a driver select when they intend taking an exit to the right (past the 12 o’clock position) of the roundabout?","img":"","options":["By straddling both lanes.","Either lane.","The left-hand lane.","The right-hand lane."],"answer":["option_4"],"explanation":"When a driver approaches a roundabout where two lanes are provided, they should choose the most suitable one based on the road markings and the exit they intend to take off the roundabout. The left lane is generally used for vehicles exiting to the left (9 o’clock) or straight ahead (12 o’clock) and the right is for vehicles exiting at any exit after 12 o’clock."},{"id":"494","category_id":"4","question":"What position should a driver generally adopt on approach to a roundabout when intending to take the first exit to the left?","img":"","options":["Approach in the left-hand lane.","Approach by straddling both lanes.","Approach in any lane available.","Approach in the right-hand lane."],"answer":["option_1"],"explanation":"When a driver intends to take any exit between the 6 o’clock and 12 o’clock positions they should generally approach the roundabout in the left lane unless road markings dictate otherwise."},{"id":"495","category_id":"4","question":"In general, when turning right on a two-way road, where should a driver position the vehicle?","img":"","options":["At either side of the middle of the road.","At the far left-hand side of the road.","Just left of the middle of the road.","At the far right-hand side of the road."],"answer":["option_3"],"explanation":"In general, the correct position to be in before turning right is just left of the centre of the road. Where the road is wide enough, this position allows traffic coming from behind and going straight ahead to pass safely on the left. The driver should be alert for road markings which direct them to follow a certain course."},{"id":"496","category_id":"4","question":"What should a driver do before turning right from a major road into a minor road?","img":"","options":["Stop and signal traffic to exit right from the minor road.","Yield right of way to oncoming traffic and to pedestrians crossing at the junction.","Commence turn in front of oncoming traffic as they must yield to traffic turning right.","Stop and signal traffic to exit left from the minor road."],"answer":["option_2"],"explanation":"The driver must yield to oncoming traffic and to pedestrians who are already crossing when turning right from a major road to a minor road."},{"id":"497","category_id":"4","question":"In general, which of the following should a driver do before entering a tunnel?","img":"","options":["Ensure that full headlights are switched on.","Switch on hazard warning lights to alert other traffic of their presence.","Ensure that dipped headlights are switched on.","Only use dipped headlights if there is other traffic in the tunnel."],"answer":["option_3"],"explanation":"In general, a driver should switch on their dipped headlights before entering a tunnel."},{"id":"498","category_id":"4","question":"What should a driver do when entering a tunnel?","img":"","options":["Always switch off your radio to avoid distractions.","Drive closer to the vehicle in front.","Never drive below the posted speed limit.","Keep a safe distance from the vehicle in front."],"answer":["option_4"],"explanation":"The driver should keep a safe distance from the vehicle in front remembering that they are entering a tunnel and tailgating could create an emergency. The minimum recommended safe distance for a car or motor cycle is 50 metres and is 100 metres for all other vehicles. Always remember the 2 second rule."},{"id":"499","category_id":"4","question":"What should a driver do if there is very heavy traffic congestion in a tunnel?","img":"","options":["Switch on hazard warning lights.","Keep close to the vehicle in front.","Leave the vehicle.","Stop at the nearest emergency exit."],"answer":["option_1"],"explanation":"If there is traffic congestion in a tunnel, you should switch on hazard lights and remain patient. Keep a safe distance from the vehicle in front even in slow-moving traffic. Listen for traffic messages on the tunnel radio station, if available."},{"id":"500","category_id":"4","question":"When stopped at traffic lights and the green light comes on but pedestrians are still crossing the road, what should a driver do?","img":"","options":["Move forward to encourage them to complete the crossing quickly.","Sound the horn as a warning to them that lights have changed.","Signal the pedestrians that the lights have changed and drive on.","Wait as long as necessary to enable them to complete the crossing."],"answer":["option_4"],"explanation":"A green traffic light means you may go if the way is clear. If pedestrians are crossing, give way to them and let them safely cross before proceeding."},{"id":"501","category_id":"4","question":"How is a learner driver likely to react in unusual traffic situations?","img":"","options":["Better than an experienced driver.","Quicker than an experienced driver.","Slower than an experienced driver.","In the same way as an experienced driver."],"answer":["option_3"],"explanation":"You should be patient when driving behind a learner driver. Learners may not anticipate and react to unusual traffic situations as well as an experienced driver might."},{"id":"502","category_id":"4","question":"When negotiating junctions, which road users are particularly vulnerable?","img":"","options":["Minibus drivers.","Van drivers.","Tractor drivers.","Motorcyclists."],"answer":["option_4"],"explanation":"Drivers should be aware that no vehicle has an automatic right of way at a junction. Drivers must pay particular attention to vulnerable road users such as motorcyclists whose presence on the road may be less visible than other vehicle types due to their smaller size or obstructions."},{"id":"503","category_id":"4","question":"In slow-moving city traffic, a driver should occasionally check their blind spots for which road users in particular?","img":"","options":["Cars.","Vans.","Cyclists.","Taxis."],"answer":["option_3"],"explanation":"Drivers should be aware of and check blind spots before moving off and changing direction where appropriate. Cyclists can easily become hidden in a blind spot, and in slow-moving traffic, they might be moving faster than you are."},{"id":"504","category_id":"4","question":"When driving on a road that has a potholed surface and there is a cyclist ahead, what should a driver do?","img":"","options":["Allow extra clearance in case the cyclist swerves to avoid a pothole.","Expect the cyclist to keep to the left and maintain speed.","Maintain course and sound the horn to alert the cyclist of their approach.","Change to a lower gear and overtake quickly."],"answer":["option_1"],"explanation":"You should always be aware of how vulnerable cyclists are. When you are driving on a road with potholes or bad surfaces, give plenty of clearance to the cyclists when overtaking them. Take into account that they may swerve suddenly to avoid potholes."},{"id":"505","category_id":"4","question":"What should a driver be aware of when making a left turn into a side road?","img":"","options":["To approach as close to the kerb as possible.","Following traffic must have room to overtake.","Cyclists may come up on the left (nearside).","Cyclists might come up on the right (offside)."],"answer":["option_3"],"explanation":"When turning left, drivers should be aware that cyclists and pedestrians may come up on the left (nearside). Always check to your left (nearside) before you make a left turn."},{"id":"506","category_id":"4","question":"When driving on a country road without footpaths, what should a driver expect coming towards them on their side of the road?","img":"","options":["Tractors.","Pedestrians.","Cyclists.","Motorcyclists."],"answer":["option_2"],"explanation":"Where there is no footpath, pedestrians are required to walk on the side of the on-coming traffic and drivers should be aware of this. Pedestrians are vulnerable road users so drivers should always be aware of their presence, especially on country roads."},{"id":"507","category_id":"4","question":"What should a driver do when driving at night on an unlit road?","img":"","options":["Drive close to the left to avoid oncoming traffic.","Watch out for pedestrians wearing dark clothing.","Drive on the centre of the road.","Drive as close as possible to the line of reflective studs."],"answer":["option_2"],"explanation":"While driving at night and even with the best headlights, it can be very difficult to see all the hazards that you might come across – for example, pedestrians wearing dark clothing. As always drivers should drive at a speed that will enable them to stop safely within the distance they can see to be clear ahead."},{"id":"508","category_id":"4","question":"What procedure should a driver follow when intending to overtake a cyclist travelling in the same direction up ahead?","img":"","options":["Indicate, move out and check the mirror for following traffic.","Indicate, check the mirror, move out and overtake when safe to do so.","Mirror check, indicate and move out if it is safe to do so.","Mirror check, and move out to overtake without indicating."],"answer":["option_3"],"explanation":"The sequence drivers should follow the mirror - signal - manoeuvre routine when overtaking. Drivers should overtake only when it is safe to do so. Give extra space to cyclists when overtaking them, as they may need to move out to avoid a pothole, or they could be blown into your path on windy days."},{"id":"509","category_id":"4","question":"What should a driver do when travelling on a country road with following traffic, and they meet pedestrians?","img":"","options":["Gesture to the pedestrians to move in off the road.","Flash the lights to alert following traffic of a pedestrian on the road.","Leave a minimum clearance of 30 centimetres.","Signal their intention to overtake the pedestrians."],"answer":["option_4"],"explanation":"When you are driving on a road without footpaths, drivers should take extra care when they come upon pedestrians on the road. When they intend to move out and overtake, they should check the mirrors and signal to following traffic in good time to alert drivers behind that they are changing direction because of the hazard ahead."},{"id":"510","category_id":"4","question":"When driving on dark winter mornings and evenings on unlit country roads, what should a driver be aware of?","img":"","options":["On country roads, cyclists have space in the margin of the road so that a driver can overtake them without reducing speed or moving out.","Cyclists are much more vulnerable in poor lighting conditions.","Cyclists all wear reflective belts, have the correct lighting on their bicycles and are clearly visible.","An oncoming cyclist could never be dazzled by the vehicle lights and wobble off course into the driver’s path."],"answer":["option_2"],"explanation":"Drivers should take extra care when driving on dark winter mornings and evenings – vulnerable road users such as cyclists and pedestrians (particularly schoolchildren) might not be so easy to see in low light conditions."},{"id":"511","category_id":"4","question":"When driving on dark winter mornings and evenings on unlit country roads, what should a driver be aware of?","img":"","options":["That there will be no pedestrians walking on the road.","That all pedestrians will be wearing reflective armbands and bright clothing.","That there could be vulnerable pedestrians walking on the road.","That the lack of light will not affect the driver’s ability to see vulnerable pedestrians."],"answer":["option_3"],"explanation":"Drivers should take extra care when driving on dark winter mornings and evenings – vulnerable road users such as cyclists and pedestrians (particularly schoolchildren) might not be so easy to see in low light conditions."},{"id":"512","category_id":"4","question":"When driving on dark winter mornings and evenings on unlit country roads, what should a driver be aware of?","img":"","options":["That a driver should drive at all times with sidelights on in order to see pedestrians walking on unlit country roads.","Schoolchildren are more vulnerable on unlit country roads on dark winter mornings and evenings.","A driver should expect that pedestrians will be on the footpath and not be in danger of being hit.","That the lack of light will not effect the driver’s ability to see stray animals on the road."],"answer":["option_2"],"explanation":"Drivers should take extra care when driving on dark winter mornings and evenings – vulnerable road users such as cyclists and pedestrians (particularly schoolchildren) might not be so easy to see in low light conditions."},{"id":"513","category_id":"4","question":"What should a driver do if a front tyre bursts while driving?","img":"","options":["Relax the hold on the steering wheel.","Grip the steering wheel firmly.","Apply the handbrake immediately.","Brake firmly and quickly."],"answer":["option_2"],"explanation":"If a front tyre bursts on a vehicle, the steering on the vehicle will become unstable. Don’t panic – slow down gradually while keeping a firm hold on the steering wheel. Stop in a safe place to change the wheel, and alert other road users by switching on your hazard warning lights."},{"id":"514","category_id":"4","question":"What precautions could a driver take against the risk of fire in their vehicle?","img":"","options":["Avoid driving the vehicle with a full tank of fuel.","Keep all water levels filled to the maximum at all times.","Carry a suitable fire extinguisher in the vehicle.","Use low-octane unleaded petrol in the vehicle."],"answer":["option_3"],"explanation":"A strong smell of fuel is usually an indication that something is wrong, and you should stop and investigate as soon as possible. Leaking or spilling petrol can be dangerous because it is so combustible. It is good practice to carry a fire extinguisher in your vehicle, so that you can deal with any small fires."},{"id":"515","category_id":"4","question":"What should a driver do if their vehicle is broken down on a motorway and they are awaiting assistance?","img":"","options":["Stand out on the roadway and direct traffic to pass.","Switch on the vehicle hazard warning lights, get out of the vehicle and stand safely to the side.","Get out of the vehicle and wait at the rear of it.","Try to flag down other traffic from the rear of the vehicle for assistance."],"answer":["option_2"],"explanation":"If your vehicle breaks down on the road, always switch on the hazard warning lights and stand clear of the vehicle while awaiting assistance – this will warn other traffic that there is a vehicle stopped on the road."},{"id":"516","category_id":"4","question":"What does this dial provide information on?","img":"a_Hxjzh.png","options":["Fuel level.","Gearbox revolution.","Oil level.","Engine revolution."],"answer":["option_4"],"explanation":"The rev counter measures the speed of the engine, in revolutions per minute. Generally, the higher the revs, the more fuel the engine is using, so drivers should keep an eye on the rev counter to help drive in a more eco-friendly manner."},{"id":"517","category_id":"4","question":"What does a rev counter provide information on?","img":"a_IP3h1.png","options":["Engine revolutions.","Gear box revolutions.","Wheel revolutions.","Heater-fan revolutions."],"answer":["option_1"],"explanation":"The rev counter measures the speed of the engine, in revolutions per minute. Generally, the higher the revs, the more fuel the engine is using, so drivers should keep an eye on the rev counter to help drive in a more eco-friendly manner."},{"id":"518","category_id":"4","question":"What should the driver be able to see in the vehicle mirrors when they are properly adjusted?","img":"","options":["The passenger area of the vehicle.","The position of all the wheels.","The position of the left-side wheels.","The area behind and to each side of the vehicle."],"answer":["option_4"],"explanation":"Properly adjusted vehicle mirrors enable drivers to see the road behind and to the sides. This helps drivers to take into account what’s happening behind them, so that they can make informed, correct and safer decisions."},{"id":"519","category_id":"4","question":"What should the driver be able to see in the exterior mirrors of a vehicle when they are properly adjusted?","img":"","options":["The sides of the vehicle only.","60% angled to the vehicle and 40% to the road.","The area to each side of the vehicle.","The back of the vehicle only."],"answer":["option_3"],"explanation":"Exterior mirrors enable drivers to see the area on each side of the vehicle. Drivers must take into account all visible hazards in order to make informed, correct and safer decisions."},{"id":"520","category_id":"4","question":"The vehicle’s exterior mirrors are covered by a film of mud and dust. What should the driver do?","img":"","options":["Angle the mirrors towards the front for a distance in order to clean them.","Clean them with a cloth or tissue before starting their journey.","Drive in the slip stream of other traffic, as this will eventually clean the mirrors.","Continue on and clean them after reaching the destination."],"answer":["option_2"],"explanation":"The purpose of mirrors is to increase the driver’s view to the rear and sides of the vehicle and to enable them to take into account all visible hazards. Proper use will enable drivers to make informed, correct and safer decisions. Drivers should ensure that all mirrors, including the exterior ones, are clean and properly adjusted at all times to ensure optimum view."},{"id":"521","category_id":"4","question":"What effect can wet weather have on a vehicle’s exterior mirrors?","img":"","options":["Water droplets can make the reflected object appear closer than it really is.","Water droplets help to keep them clean.","Water can cause a short-circuit in the electrically heated mirrors.","Water droplets can obscure the reflected image."],"answer":["option_4"],"explanation":"When driving in wet weather conditions, small water droplets can form on the glass of the exterior mirrors. This could make it more difficult to see the road behind and to the sides. Switch on the mirror demisters, if they are fitted. If necessary, stop and clear them."},{"id":"522","category_id":"4","question":"What does blue smoke coming from the vehicle’s exhaust generally mean?","img":"","options":["The catalytic converter is worn out.","The engine is burning oil.","The air filter needs to be replaced.","The engine is overheating."],"answer":["option_2"],"explanation":"A vehicle can give off blue smoke from the exhaust when it is burning oil. Poor maintenance and worn engines are typical causes. This blue smoke is harmful to the environment and may be costly. Drivers should have the vehicle checked by a competent person."},{"id":"523","category_id":"4","question":"What is the effect of a worn exhaust?","img":"","options":["The filtering of fumes is reduced and engine noise is louder.","Fuel efficiency is increased as the fumes escape more quickly.","Gear-changing is more difficult.","The engine overheats."],"answer":["option_1"],"explanation":"A worn exhaust system can have a number of effects, including increased noise from the engine and more environmentally damaging fumes (as they are not filtered properly). There are requirements to ensure vehicles are compliant with EU and Irish legislation. Vehicles are tested for compliance during road worthiness testing."},{"id":"524","category_id":"4","question":"What effect can a faulty exhaust system have?","img":"","options":["It can increase the vehicle’s noise and pollution levels.","It can reduce the vehicle’s engine noise.","It can increase wear on the vehicle’s engine.","It can improve the vehicle’s fuel consumption."],"answer":["option_1"],"explanation":"A worn exhaust system can have a number of negative effects, including increased noise from the engine and more environmentally damaging fumes (as they are not filtered properly). There are requirements to ensure vehicles are compliant with EU and Irish legislation. Vehicles are tested for compliance during road worthiness testing."},{"id":"525","category_id":"4","question":"What is the purpose of a catalytic converter?","img":"","options":["It allows the engine to quickly reach its normal operating temperature.","It increases engine power.","It decreases engine power.","It filters exhaust gases and reduces air pollution."],"answer":["option_4"],"explanation":"The purpose of a catalytic converter (CAT) is to remove toxic or polluting gases such as carbon monoxide, nitrogen oxide and unburned hydrocarbons from the exhaust emissions. When the CAT is faulty, an engine management warning light illuminates on the dashboard and drivers should seek advice from a competent person."},{"id":"526","category_id":"4","question":"How does harsh acceleration affect fuel consumption?","img":"","options":["There is no effect provided the engine is properly tuned.","There is no effect if a high gear is engaged.","Fuel consumption decreases.","Fuel consumption increases."],"answer":["option_4"],"explanation":"Harsh acceleration increases fuel consumption. Smooth acceleration helps to reduce fuel consumption and the emissions from vehicles. Try not to over-rev the engine and use the appropriate gear for the speed of the vehicle. When slowing down, take your foot off the accelerator and allow the vehicle to slow progressively before you brake."},{"id":"527","category_id":"4","question":"How does continuous high-speed driving affect fuel consumption?","img":"","options":["It reduces fuel consumption as long as the road is straight.","It reduces fuel consumption.","It increases fuel consumption.","It uses the same consumption of fuel as lower speed driving."],"answer":["option_3"],"explanation":"Driving at continuous high speeds increases your fuel consumption. Vehicles driving at 112 km/h consumes approximately 30% more fuel than a vehicle travelling at 80 km/h."},{"id":"528","category_id":"4","question":"How can fuel efficiency be improved?","img":"","options":["By using an anti-waxing agent only in freezing conditions.","By accelerating hard up through the gears to reach the desired speed as quickly as possible.","By using gentle acceleration and making gear changes appropriate to speed.","By driving the vehicle in a lower gear for as long as possible."],"answer":["option_3"],"explanation":"A driver can contribute to their vehicle’s fuel efficiency by reading the road ahead and driving smoothly. This is achieved by accelerating gently, using the most appropriate gear for the speed they are travelling at and avoiding harsh braking."},{"id":"529","category_id":"4","question":"What effect does a worn exhaust have on a vehicle?","img":"","options":["It causes the water coolant to leak from the engine.","It causes noise and gas pollution levels to increase.","It decreases fuel consumption.","It causes oil to leak on the road."],"answer":["option_2"],"explanation":"A vehicle with a worn exhaust will probably be noisier and will produce more polluting emissions. There are strict regulations governing the noise and emission levels of vehicles, and these are rigorously checked during a vehicle’s NCT."},{"id":"530","category_id":"4","question":"When is the use of the horn prohibited?","img":"","options":["Between 11:30 pm and 6:00 am on any road.","At all times in a built-up area.","Between 10:00 pm and 6:00 am in a built-up area.","Between 11:30 pm and 7:00 am in a built-up area."],"answer":["option_4"],"explanation":"Drivers are not permitted to sound the horn in a built-up area between 11:30 pm and 7:00 am unless there is a traffic emergency. Only sound the horn to warn other road users of oncoming danger or if they need to be made aware of your presence for safety reasons. Sounding the horn does not give the driver an automatic right of way. Never sound the horn to provoke a reaction from or to rebuke another motorist."},{"id":"531","category_id":"4","question":"What can a driver do to maximise fuel efficiency while driving?","img":"","options":["Reduce pressure in all tyres.","Avoid carrying unnecessary weight.","Fit a roof rack.","Increase road speed."],"answer":["option_2"],"explanation":"The more extra weight is in your vehicle, the more fuel you use. Using a roof rack or a roof box increases wind resistance and this also increases fuel consumption – by as much as 15%. Remove roof racks and roof boxes when not in use."},{"id":"532","category_id":"4","question":"Which action is likely to cause an increase in fuel consumption?","img":"","options":["Driving at a constant speed.","Harsh acceleration.","Turning off air conditioning.","Looking ahead and anticipating traffic flow."],"answer":["option_2"],"explanation":"Harsh acceleration increases fuel consumption. Driving smoothly reduces wear and tear and also improves fuel consumption. Use the highest gear possible without causing the engine to labour."},{"id":"533","category_id":"4","question":"How are emergency vehicles identified?","img":"","options":["By continuously lit red lights.","By flashing green lights.","By flashing amber and white lights.","By flashing red or blue lights."],"answer":["option_4"],"explanation":"If you hear or see an emergency vehicle approaching sounding its siren or flashing lights, be extra careful and give way if it is safe to do so."},{"id":"534","category_id":"4","question":"After a heavy downpour, why should a driver keep a greater distance from the vehicle in front?","img":"","options":["Because tyre grip improves when wet.","Because wheels rotate at a greater speed after rain.","Because wheels rotate at a slower speed after rain.","Because the required stopping distances is greater."],"answer":["option_4"],"explanation":"On a wet road surface, your tyres do not grip the road surface as well as in dry conditions and your required stopping distance is increased. Because of that you should slow down during or after rain and keep a greater distance from the vehicle in front."},{"id":"535","category_id":"4","question":"At traffic lights, a driver should take particular care for which road users coming up on the left?","img":"","options":["Tractors.","Motorcyclists.","Vans.","Cars."],"answer":["option_2"],"explanation":"Before moving off at traffic lights the driver should be aware of traffic, particularly cyclists and motorcyclists, coming up on the left, especially where there is an advanced stop line for cyclists ahead of that which applies to other road users."},{"id":"536","category_id":"4","question":"When a driver intends to make a left-hand turn at a junction where there are pedestrians and cyclists present, what should a driver do?","img":"","options":["Sound the horn while proceeding to warn the other road users of the intention to turn.","Check your mirrors and watch for cyclists or pedestrians on the left.","Check the right-hand mirror, make the turn and then signal.","Signal left, watch the right-hand mirror and make the turn."],"answer":["option_2"],"explanation":"The vehicle does not have a greater right-of-way than any other road user. As a driver you should pay particular attention to vulnerable road users such as pedestrians, cyclists and motorcyclists and be aware that they are entitled to use the road in safety."},{"id":"537","category_id":"4","question":"Which of the following road users are most vulnerable in slow-moving city traffic?","img":"","options":["Cars.","Taxis.","Motorcyclists.","Vans."],"answer":["option_3"],"explanation":"In slow-moving city traffic, you should be aware of and check your blind spots before any manoeuvre. Motorcyclists can easily become hidden in a blind spot, and in slow-moving traffic, they might be moving faster than you are."},{"id":"538","category_id":"4","question":"Which of the following road users are most vulnerable in slow-moving city traffic?","img":"","options":["Cars.","Taxis.","Vans.","Pedestrians."],"answer":["option_4"],"explanation":"In slow-moving city traffic, you should be aware of and check your blind spots before any manoeuvre. Pedestrians can easily become hidden in a blind spot, and in slow-moving traffic, they might be moving faster than you are."},{"id":"539","category_id":"4","question":"What should a driver do when driving at night on an unlit road?","img":"","options":["Watch out for unlit cyclists.","Drive close to the left and switch on front fog lights.","Drive at least 30 km/h below the posted speed limit.","Keep well out from the left-hand side of the road."],"answer":["option_1"],"explanation":"While driving at night and even with the best headlights, it can be very difficult to see all the hazards that you might come across – for example, stray animals or livestock on the road. At night you should drive at a speed that will enable you to stop safely within the distance you can see to be clear ahead."},{"id":"540","category_id":"4","question":"What can be achieved by the driving style known as ‘Eco-Driving’?","img":"","options":["Improved road safety.","Reduced journey times.","Increased journey times.","Increased emissions."],"answer":["option_1"],"explanation":"The advantages of eco-driving include improved road safety, improved fuel consumption and reduced emissions. The eco-conscious driver becomes a more efficient driver because they learn to read the road further ahead and display better anticipation skills. This reduces the need for harsh acceleration and braking which results in a more economical style of driving and a smoother drive."},{"id":"541","category_id":"4","question":"What can be achieved by the driving style known as ‘Eco-Driving’?","img":"","options":["Increased fuel consumption.","Increased journey times.","Increased emissions.","Increased fuel efficiency."],"answer":["option_4"],"explanation":"One of the many advantages of an eco-driving style, includes: Increased fuel efficiency, reduced emissions and improved driver safety. The eco-conscious driver becomes a more efficient driver because they learn to read the road further ahead and display better anticipation skills. This reduces the need for harsh acceleration and braking which results in a more economical style of driving and a smoother journey."},{"id":"542","category_id":"4","question":"Which action contributes to eco-driving?","img":"","options":["Maintaining a steady speed.","Braking harshly.","Driving with the windows open.","Driving in a low gear at high speed."],"answer":["option_1"],"explanation":"One of the many advantages of maintaining a steady speed includes: Increased fuel efficiency, reduced emissions and improved driver safety. The eco-conscious driver becomes a more efficient driver because they learn to read the road further ahead and display better anticipation skills. This reduces the need for harsh acceleration and braking which results in a more economical style of driving and a smoother journey."},{"id":"543","category_id":"4","question":"Which action contributes to eco-driving?","img":"","options":["Driving in a low gear at high speed.","Braking harshly.","Looking ahead and anticipating.","Reducing tyre pressure."],"answer":["option_3"],"explanation":"One of the many advantages of an eco-driving style, includes: Increased fuel efficiency, reduced emissions and improved driver safety. The eco-conscious driver becomes a more efficient driver because they learn to read the road further ahead and display better anticipation skills. This reduces the need for harsh acceleration and braking which results in a more economical style of driving and a smoother journey."},{"id":"544","category_id":"4","question":"When a driver intends to make a left-hand turn on a busy city street junction and there are pedestrians and cyclists around, what should the driver do?","img":"","options":["Signal left, watch the right-hand mirror and make the turn when it is clear.","Stay close to the left to prevent cyclists or pedestrians coming up on your left side.","Watch for cyclists or pedestrians who may try to cross the road in front of the vehicle.","Keep to the right to make room for cyclists to pass."],"answer":["option_3"],"explanation":"When making a left-hand turn on a busy city street, drivers should pay particular attention to vulnerable road users such as pedestrians, cyclists and motorcyclists who may appear unexpectedly and may not be aware of the vehicle’s intention."},{"id":"545","category_id":"4","question":"Before exiting the vehicle on a busy road, what should the driver ensure?","img":"","options":["That the gear lever is in neutral.","That the wheels are positioned straight ahead.","Before opening the door the driver should check it is safe to do so.","That the passengers open their door first."],"answer":["option_3"],"explanation":"When exiting from a parked vehicle on a busy road, the driver should check it is safe to do so before opening the door, as there could be cyclists or other traffic passing closely by."},{"id":"546","category_id":"4","question":"When towing a high and wide-bodied trailer what should a driver do?","img":"","options":["Drive with hazard warning lights flashing at all times.","Make use of extended mirrors to check for following traffic.","Drive with a red flag to the front right-hand side of the trailer.","Drive with a red flag at the rear left of the trailer."],"answer":["option_2"],"explanation":"When towing a high and wide-bodied trailer, a driver should use extended mirrors on both sides of the towing vehicle. This will allow the driver to better observe the traffic situation behind and to the sides."},{"id":"547","category_id":"4","question":"If the vehicle’s windows are covered with ice, what should the driver do?","img":"","options":["Fully clear ice from all windows.","Drive slowly until the heater and demister have cleared the ice.","Use boiling water to clear the ice.","Clear enough space in the windscreen to be able to see ahead."],"answer":["option_1"],"explanation":"Make sure all the windows are completely clear of ice so that the driver can safely observe road and traffic conditions all around. This is especially important when driving in slippery conditions. It is good practice to carry a can of de-icer in the vehicle and if possible to fill the washer reservoir with a de-icing agent."},{"id":"548","category_id":"4","question":"What should a driver do if the vehicle’s windows and mirrors are covered in ice?","img":"","options":["Drive at a reduced speed until the heating system has cleared the ice.","Switch on the heating system and use a scraper to clear the ice before driving.","Use boiling water with salt to clear the ice.","Switch on the windscreen wipers."],"answer":["option_2"],"explanation":"Make sure all the windows and mirrors are completely clear of ice so that the driver can safely observe road and traffic conditions all around. This is especially important when driving in slippery conditions. It is good practice to carry a can of de-icer in the vehicle and if possible to fill the washer reservoir with a de-icing agent."},{"id":"549","category_id":"4","question":"What specific observations should a driver make before reversing their vehicle?","img":"","options":["Look over both shoulders and behind.","Look over right-hand shoulder.","Look in door mirrors only.","Look in interior mirror only."],"answer":["option_1"],"explanation":"Before reversing, look over both shoulders and to the rear to check all around that there are no children or other road users around the vehicle and that it is safe to reverse."},{"id":"550","category_id":"4","question":"What specific observations should a driver make before reversing a vehicle fitted with an external audible warning device?","img":"","options":["Observations should be made by opening the driver’s door and looking behind.","Observations should be made only in blind spots.","Observations should be made to the front, sides and rear of the vehicle, including blind spots.","No specific observations needed, as bystanders will be aware of the vehicle."],"answer":["option_3"],"explanation":"Drivers should not rely solely on an external audible warning device to warn others that their vehicle is reversing. Before reversing, drivers must make sure it is safe to do so by taking all appropriate observations to the front, sides and rear of the vehicle, including the blind spots. Never assume it is safe to reverse just because the vehicle has an external audible warning device."},{"id":"551","category_id":"4","question":"What should a driver do when they intend to reverse into a side road?","img":"","options":["Focus totally on the left-side door mirror while reversing.","Check carefully all around before and during the reverse.","Open the left-side door fully to look behind.","Angle the door mirrors down before reversing."],"answer":["option_2"],"explanation":"Before and while reversing into a side road, check all around to make sure it is safe and clear to carry out the manoeuvre, paying particular attention to pedestrians crossing behind the vehicle and any other road users."},{"id":"552","category_id":"4","question":"What should a driver do if they intend to reverse their vehicle into an area which they cannot see?","img":"","options":["Open driver’s window and look behind.","Open driver’s door and look behind.","Ask someone to guide you when reversing.","Look in nearside (left) mirror when reversing."],"answer":["option_3"],"explanation":"Do not attempt to reverse into an area that you cannot see into properly. You should get assistance from somebody who can guide you safely into the area."},{"id":"553","category_id":"4","question":"What should a driver do in order to keep alert during a long journey?","img":"","options":["Increase speed to shorten the journey.","Keep the radio turned on and windows closed.","Increase the air circulation and stop if necessary.","Turn up the heater to maintain driver comfort."],"answer":["option_3"],"explanation":"While on a long journey, a driver should take regular rest breaks. A short walk and a caffeinated drink (tea or coffee) can help to revive them. The vehicle should be kept cool and well ventilated with a steady flow of fresh air."},{"id":"554","category_id":"4","question":"When should rear fog lights be used?","img":"","options":["In dense fog or falling snow.","Only in light fog.","When the vehicle behind is too close.","Always when driving at night in an unlit area."],"answer":["option_1"],"explanation":"A driver must only use rear fog lights in dense fog or falling snow. Using fog lights in normal road and weather conditions can dazzle or blind following motorists. Also, fog lights may make brake lights harder to see."},{"id":"555","category_id":"4","question":"When should rear fog lights be used?","img":"","options":["When driving in dense fog or falling snow.","Rear fog lights should always be used.","When both the rear tail lights are broken.","Rear fog lights should be used only at dawn and dusk."],"answer":["option_1"],"explanation":"A driver must only use rear fog lights in dense fog or falling snow. Using fog lights in normal road and weather conditions can dazzle or blind following motorists. Also, fog lights may make brake lights harder to see."},{"id":"556","category_id":"4","question":"What should a driver do if dazzled by headlights reflecting in the rear-view mirror of their car?","img":"","options":["Use the night driving mode on their rear-view mirror.","Adjust the mirror to reflect the light back towards the following driver.","Switch the lights off and on to remind the following driver to dip their lights.","Turn on the rear fog lights to signal to the following vehicle to turn off their headlights."],"answer":["option_1"],"explanation":"If a driver is being dazzled by the lights of following traffic, they should adjust their rear-view mirror to the night driving mode. This will allow them to concentrate on the road ahead and not be distracted by lights from following traffic."},{"id":"557","category_id":"4","question":"At night, what effect could driving with a single headlight have on oncoming drivers?","img":"","options":["It could dazzle them.","They could mistake the vehicle for a motorcycle.","It could enable them to see the vehicle more clearly.","It would have no effect on oncoming drivers."],"answer":["option_2"],"explanation":"Motor vehicles (except motorcycles) are required by law to have two headlights. A vehicle with only one headlight could be mistaken for a motorcycle and other road users could believe that it is in a different position on the road than it actually is. Vehicle lights should be checked on a regular basis and repair faulty lighting immediately."},{"id":"558","category_id":"4","question":"What is meant by the term jack-knifing?","img":"","options":["When the trailer is too heavy to be drawn by the tractor.","When the vehicle slides due to ice or water on the road.","When the jack is not strong enough to lift an axle.","When the trailer is travelling faster than the drawing vehicle."],"answer":["option_4"],"explanation":"Towing a trailer or caravan dramatically reduces the stability of the towing vehicle. If a driver brakes sharply or slows down quickly, the trailer may pivot around the tow hitch coupling, causing both vehicles to go off course, and possibly overturn."},{"id":"559","category_id":"4","question":"When should a driver use the vehicle side lights?","img":"","options":["When driving in foggy conditions.","When parking at all times.","When driving in an unlit area at night.","When parking on an unlit road."],"answer":["option_4"],"explanation":"When leaving a vehicle on an unlit public road at night this creates a potential danger for other road users. Drivers should therefore leave side/parking lights on, so that the vehicle can be seen by other road users. Drivers should not leave headlights on when parked as this may cause other road users to become disoriented."},{"id":"560","category_id":"4","question":"What is a possible effect of over-filling the engine with oil?","img":"","options":["It could burst the oil filter.","It could damage the oil pump.","It could damage the catalytic converter.","It could reduce the oil pressure."],"answer":["option_3"],"explanation":"It is essential that the vehicle’s engine is not over filled with oil as this can permanently damage the catalytic converter, which is part of most vehicles’ exhaust systems and removes up to 75% of the carbon monoxide, nitrogen oxide and hydrocarbons from the vehicle’s exhaust. Damaging this increase exhaust emissions."},{"id":"561","category_id":"4","question":"What safety precaution should a driver take when getting out of their vehicle?","img":"","options":["Check all around for approaching traffic and pedestrians before opening the door.","Ensure the gear lever is in neutral.","Open the door and try to get out as speedily as possible.","Ensure all valuables are secured and out of sight."],"answer":["option_1"],"explanation":"Before opening any door, check for other road users passing, and in particular look out for pedestrians, cyclists and motorcyclists. Exit the vehicle only when it is safe to do so, and close the door as soon as possible. Passengers should exit on the side nearest the kerb wherever possible."},{"id":"562","category_id":"4","question":"On a busy road, how should a driver allow passengers out of a vehicle?","img":"","options":["Stop and allow them to get out from whichever side of the vehicle they are sitting.","Stop and allow them to get out on the side nearest the kerb.","Stop and encourage them to get out as quickly as possible.","Signal to following traffic to overtake before allowing the passengers to get out."],"answer":["option_2"],"explanation":"Before allowing any door to be opened, check for other road users passing, and in particular look out for pedestrians, cyclists and motorcyclists. Passengers should exit on the side nearest the kerb, without getting in the way of pedestrians."},{"id":"563","category_id":"4","question":"How should a driver apply the brakes in an emergency if the vehicle is fitted with anti-lock brakes (ABS)?","img":"","options":["Press the brake pedal only lightly.","Press the brake pedal firmly and hold.","Press and release the brake at rapid intervals.","Press and release the brake at slow intervals."],"answer":["option_2"],"explanation":"If your vehicle is fitted with ABS, brake firmly. ABS will not stop the vehicle more quickly, it will only prevent the wheels from locking. This helps you to maintain control of the vehicle."},{"id":"564","category_id":"4","question":"What effect could a front-tyre blow-out have on a vehicle?","img":"","options":["The wheels will lock up and stop rotating.","The steering wheel will stay in the straight on position.","The steering wheel will pull to one side.","Anti-lock brakes will be automatically disengaged."],"answer":["option_3"],"explanation":"If a front tyre on the vehicle you are driving blows out, you will feel the effect of it through the steering wheel. The wheel will generally pull to the side of the blown-out tyre."},{"id":"565","category_id":"4","question":"What should a driver do when suddenly confronted by a hazard on the road?","img":"","options":["Decelerate and apply the footbrake firmly.","Slowly brake and switch off the ignition.","Apply the handbrake and the footbrake together.","Depress clutch and switch off the ignition."],"answer":["option_1"],"explanation":"To stop your vehicle in an emergency, apply the footbrake firmly, and maintain the pressure until the vehicle stops. Depress the clutch pedal just before stopping."},{"id":"566","category_id":"4","question":"When driving along and required to stop suddenly, what should a driver do?","img":"","options":["Depress the clutch and then apply the handbrake.","Apply the handbrake and the footbrake together.","Apply the footbrake firmly.","Steer sharply to one side and apply the handbrake."],"answer":["option_3"],"explanation":"To stop your vehicle in an emergency, apply the footbrake firmly, and maintain the pressure until the vehicle stops. Depress the clutch pedal just before stopping."},{"id":"567","category_id":"4","question":"When required to stop in an emergency, what should a driver do?","img":"","options":["Press the footbrake and engage a higher gear.","Apply both the clutch and handbrake.","Apply firm pressure on the footbrake.","Apply gentle pressure to the footbrake."],"answer":["option_3"],"explanation":"To stop your vehicle in an emergency, apply the footbrake firmly, and maintain the pressure until the vehicle stops. Depress the clutch pedal just before stopping."},{"id":"568","category_id":"4","question":"When required to stop in an emergency, what should a driver do?","img":"","options":["Apply the footbrake firmly.","Switch off the ABS system.","Apply the footbrake and engage a higher gear.","Depress the clutch pedal and engage a lower gear."],"answer":["option_1"],"explanation":"To stop your vehicle in an emergency, apply the footbrake firmly, and maintain the pressure until the vehicle stops. Depress the clutch pedal just before stopping."},{"id":"569","category_id":"4","question":"What can a driver do to stay alert on a long journey?","img":"","options":["Roll down the window and allow fresh air in.","Stop, park in a safe place and have a cup of coffee.","Turn up the temperature in the vehicle.","Listen attentively to the radio."],"answer":["option_2"],"explanation":"If a driver continues to drive fighting sleep it can be the same as being over the drink driving limit. Stopping the vehicle in a safe place, drinking caffeine and taking a nap for 15 minutes will revive the driver allowing them to continue for a short period."},{"id":"570","category_id":"4","question":"What effect can wet weather have on the vehicle’s exterior mirrors?","img":"","options":["It has no effect.","It can short-circuit the electrically heated mirrors.","It can keep them clean.","It can distort the rear vision of the driver."],"answer":["option_4"],"explanation":"When driving in the rain, water droplets can adhere to the exterior mirrors and obscure the driver’s view to the side and rear of the vehicle. If the vehicle has heated mirrors, turn them on to clear them. Alternatively, stop periodically to clear them manually."},{"id":"571","category_id":"4","question":"What should a driver do before starting a journey in bad weather?","img":"","options":["Reduce tyre pressure to ensure better grip on the road.","Top up the windscreen washer reservoir.","Increase tyre pressure to ensure better grip on the road.","Top up the gearbox with coolant."],"answer":["option_2"],"explanation":"Before starting a long journey in adverse weather the driver should ensure that there is sufficient fluid in the windscreen washer bottle in order to keep the windscreen clear in these conditions."},{"id":"572","category_id":"4","question":"What should a driver do to secure the vehicle before leaving it?","img":"","options":["Apply the exhaust brake and switch off the engine.","Leave the engine running with the parking brake on.","Apply the parking brake and switch off the engine.","Leave the engine running with the exhaust brake on."],"answer":["option_3"],"explanation":"Before you leave your vehicle, apply the parking brake and switch off the ignition. Check to make sure that you can open the door safely without endangering others, and alight when it is safe to do so."},{"id":"573","category_id":"4","question":"Before entering a tunnel, what should a driver do in order to improve vision?","img":"","options":["Wear sunglasses to prevent glare from the lights.","Take off sunglasses.","Drive close to the vehicle in front.","Pull down the visor to eliminate overhead light glare."],"answer":["option_2"],"explanation":"Be aware that there is considerably less light available in a tunnel, even with the tunnel lights on. To improve your vision remove your sunglasses before entering the tunnel."},{"id":"574","category_id":"4","question":"When a vehicle is stopped in a tunnel due to congestion what should a driver do?","img":"","options":["Walk to the nearest emergency exit.","Switch off the engine and leave the vehicle.","Keep close to the vehicle in front.","Switch on hazard warning lights."],"answer":["option_4"],"explanation":"If, when driving a vehicle through a tunnel, you meet traffic congestion, leave a safe distance between you and the vehicle in front and switch on your hazard warning lights when stationary."},{"id":"575","category_id":"4","question":"When a vehicle is stopped in a tunnel due to congestion what should a driver do?","img":"","options":["Switch on the fog lights.","Switch off the engine.","Only give hand signals.","Keep the engine ticking over in a low gear."],"answer":["option_2"],"explanation":"If, when driving a vehicle through a tunnel, you are halted in stationary traffic for any length of time, you should switch off the engine to reduce fumes in the tunnel and conserve fuel."},{"id":"576","category_id":"4","question":"What should a driver do if their vehicle breaks down in a tunnel?","img":"","options":["Hitch a lift to the nearest service area and get help.","Flag down a passing motorist and ask for help.","Use the emergency telephone to call for help.","Walk to the end of the tunnel to call the Gardaí."],"answer":["option_3"],"explanation":"If a driver’s vehicle stops in a tunnel due to a breakdown, switch off the engine, switch on the hazard warning lights, check the radio for instructions and use the emergency phone at the emergency station to call for help, check all electronic signs in the tunnel for information."},{"id":"577","category_id":"4","question":"What should a driver do if their vehicle breaks down in a tunnel?","img":"","options":["Wait in the vehicle for help to arrive.","Beckon other traffic to overtake.","Reverse the vehicle to the exit.","Switch on the hazard warning lights."],"answer":["option_4"],"explanation":"If a driver’s vehicle stops in a tunnel due to a breakdown, switch off the engine, switch on the hazard warning lights, check the radio for instructions and use the emergency phone at the emergency station to call for help, check all electronic signs in the tunnel for information."},{"id":"578","category_id":"4","question":"If a vehicle being driven through a tunnel goes on fire, what should the driver do?","img":"","options":["Leave the vehicle immediately and use the emergency phone at the nearest emergency station.","Stay in the vehicle and phone the emergency station to report the fire.","Drive to the nearest emergency exit as quickly as possible.","Wait for the tunnel traffic radio to announce the fire drill."],"answer":["option_1"],"explanation":"If there is smoke or fire in the vehicle, switch off the engine, leave the vehicle immediately, go to the emergency station and use the emergency phone to alert the tunnel operator and leave the tunnel by the nearest available exit."},{"id":"579","category_id":"4","question":"When joining a motorway from a slip road, what should a driver do?","img":"","options":["Adjust speed to match that of the motorway traffic, and merge into a suitable gap.","Drive on the hard shoulder for a distance until a suitable gap appears in the traffic.","Stop on the slip road until a suitable gap appears in the traffic.","Use the size of the vehicle to assert its position on the motorway."],"answer":["option_1"],"explanation":"When joining a motorway from a slip road, drivers should adjust their speed to that of the motorway traffic on the acceleration lane and merge into a suitable gap in lane 1. Do not force other traffic to swerve or slow down to avoid your vehicle."},{"id":"580","category_id":"4","question":"What would a lightness in the steering MOST likely indicate?","img":"","options":["Gravelled surface.","Icy surface.","Smooth surface.","Wet surface."],"answer":["option_2"],"explanation":"Lightness in steering indicates a loss of traction. This generally happens when the road surface is icy. Ice provides a harder, smoother surface than rain, or snow so it is difficult to avoid skidding and drivers should allow up to 10 times the normal braking distance in order to stop safely."},{"id":"581","category_id":"4","question":"What are the drink driving penalties for a learner driver with a blood alcohol concentrate (BAC) of 20 mg to 80 mg per 100 millilitres of blood?","img":"","options":["€200 fine and 5 penalty points.","€200 fine and 6 months driving disqualification.","€200 fine and 3 months driving disqualification.","€200 fine and 3 penalty points."],"answer":["option_3"],"explanation":"Alcohol is a major factor in crashes that lead to death and injury. Research proves that even small amounts of alcohol affect your judgement and ability to drive. It is illegal to drive with alcohol levels above the legal limits."},{"id":"582","category_id":"4","question":"What are the drink driving penalties for a professional driver holding a full car licence and found to have a blood alcohol concentrate (BAC) of 20 mg to 80 mg per 100 millilitres of blood?","img":"","options":["€100 fine and 6 months driving disqualification.","€200 fine and 3 months driving disqualification.","The penalties only apply over 80 mg (BAC).","There are no penalties below 50 mg (BAC)."],"answer":["option_2"],"explanation":"Alcohol is a major factor in crashes that lead to death and injury. Research proves that even small amounts of alcohol affect your judgement and ability to drive. It is illegal to drive with alcohol levels above the legal limits."},{"id":"583","category_id":"4","question":"What are the drink driving penalties for a driver with a blood alcohol concentrate (BAC) of 80 mg to 100 mg per 100 millilitres of blood?","img":"","options":["€200 fine and 3 months driving disqualification.","€400 fine and 3 months driving disqualification.","€200 fine and 6 months driving disqualification.","€400 fine and 6 months driving disqualification."],"answer":["option_4"],"explanation":"Alcohol is a major factor in crashes that lead to death and injury. Research proves that even small amounts of alcohol affect your judgement and ability to drive. It is illegal to drive with alcohol levels above the legal limits."},{"id":"584","category_id":"4","question":"What is the penalty for a driver who refuses to give breath, blood or urine samples as evidence for a second offence to An Gárda Síochána?","img":"","options":["Automatic disqualification for 12 months.","Automatic disqualification for 3 months.","Automatic disqualification for 4 years.","Automatic disqualification for 6 years."],"answer":["option_4"],"explanation":"Alcohol is a major factor in crashes that lead to death and injury. Research proves that even small amounts of alcohol or drugs affect your judgement and ability to drive. It is illegal to drive with alcohol levels above the legal limits, or while under the influence of drugs. It is an offence to refuse to give a breath, blood or urine sample."},{"id":"585","category_id":"4","question":"Can An Gárda Síochána conduct roadside testing for drugs and alcohol in the mornings?","img":"","options":["They can check for alcohol only.","They can check for drugs only.","No, they can’t check until after midday.","Yes, they can check at any time."],"answer":["option_4"],"explanation":"It is against the law to drive a car, motor bike, truck, bus, pedal bike or an animal-drawn vehicle while ‘under the influence of an intoxicant to such an extent as to be incapable of having control of the vehicle’. Intoxicants include alcohol and drugs, whether taken separately or together. The word ‘drugs’ here includes legal prescribed and Over-The-Counter (OTC) medicines."},{"id":"586","category_id":"4","question":"Along with an impairment test, what may a Garda request if they suspect a driver of driving under the influence of drugs?","img":"","options":["An insurance certificate.","A saliva sample.","A driver’s licence.","A breath sample."],"answer":["option_2"],"explanation":"If a driver is stopped at a roadside check, they should be aware that, along with the impairment test, Gardaí can also request a saliva sample if they suspect the driver is driving under the influence of drugs."},{"id":"587","category_id":"4","question":"What is the maximum penalty on conviction for drug driving?","img":"","options":["€5,000 fine and 6 months in prison.","€3,000 fine and 12 months driving disqualification.","€3,000 fine and 12 months in prison.","€5,000 fine and 6 months driving disqualification."],"answer":["option_1"],"explanation":"Drivers should be aware of the severe penalties if they chose to drive having taken drugs and are detected. Drug driving is extremely dangerous due to the effect drugs have on the brain."},{"id":"588","category_id":"4","question":"Do the limits for drink and drug driving differ if detected in the morning?","img":"","options":["Yes, they are lower in the mornings.","No, unless tested after 10:00 am.","Yes, they are higher in the evening.","No, they are the same at all times."],"answer":["option_4"],"explanation":"The limits for drink and drug driving do not change depending on the time of the day drivers are checked. Drink and drugs remain in the body for a period of time. A driver should think carefully before driving a vehicle the morning after taking drink or drugs, and be aware that they could still be well over the limit."},{"id":"589","category_id":"4","question":"What should a driver do when an emergency service vehicle approaches with flashing blue lights?","img":"","options":["Increase speed to prevent obstructing the emergency service vehicle.","React quickly, safely and carefully to allow the emergency service vehicle to pass.","Brake suddenly to allow the emergency service vehicle to pass.","Do nothing and ignore the emergency service vehicle."],"answer":["option_2"],"explanation":"A driver needs to know what to do when they see an emergency vehicle. A driver must react quickly, safely and carefully to allow emergency service vehicles to pass. It is important to be alert and attentive at all times."},{"id":"590","category_id":"4","question":"What should a driver never do when an emergency service vehicle approaches with flashing blue lights?","img":"","options":["React quickly, safely and carefully to allow the emergency service vehicle to pass.","Clear the way as soon as possible.","Brake suddenly or block the road.","Pull over in a place which has enough space for the emergency service vehicle to pass safely."],"answer":["option_3"],"explanation":"A driver needs to know what to do when they see an emergency vehicle. A driver must react quickly, safely and carefully to allow emergency service vehicles to pass. It is important to be alert and attentive at all times."},{"id":"591","category_id":"4","question":"Can a driver break a red light or break the speed limit to allow an emergency service vehicle to pass?","img":"","options":["Yes, a driver may break the speed limit to allow an emergency service vehicle to pass.","No, a driver should never break a red light or speed up to allow an emergency service vehicle to pass.","No, except where the junction or road is clear, then a driver can break a red light or speed up to allow an emergency service vehicle to pass.","Yes, a driver may legally break a red light to allow an emergency service vehicle to pass."],"answer":["option_2"],"explanation":"A driver needs to know what to do when they see an emergency vehicle. A driver must react quickly, safely and carefully to allow emergency service vehicles to pass. It is important to be alert and attentive at all times."},{"id":"592","category_id":"4","question":"If it is safe to overtake a cyclist in speed zones up to 50 km/h, what is the recommended minimum passing distance?","img":"","options":["Allow a maximum of 1 metre.","Allow a maximum of 1.75 metres.","Allow a minimum of 1.75 metres.","Allow a minimum of 1 metre."],"answer":["option_4"],"explanation":"A driver should drive their vehicle far enough to the left to allow traffic to safely pass or overtake on the right, but not so far to the left that you are driving on a cycle lane or blocking or endangering cyclists or pedestrians. Where a driver wishes to overtake a cyclist and it is safe to do so, they should, if it is possible, give the recommended clearance depending on the speed limit area they are in."},{"id":"593","category_id":"4","question":"If it is safe to overtake a cyclist in speed zones over 50 km/h, what is the recommended minimum passing distance?","img":"","options":["Allow a maximum of 1.75 metres.","Allow a minimum of 1 metre.","Allow a maximum of 1.5 metres.","Allow a minimum of 1.5 metres."],"answer":["option_4"],"explanation":"A driver should drive their vehicle far enough to the left to allow traffic to safely pass or overtake on the right, but not so far to the left that you are driving on a cycle lane or blocking or endangering cyclists or pedestrians. Where a driver wishes to overtake a cyclist and it is safe to do so, they should, if it is possible, give the recommended clearance depending on the speed limit area they are in."},{"id":"594","category_id":"4","question":"How can a pedestrian walking along a poorly lit road reduce the risk of an accident occurring?","img":"","options":["Walk as part of a group.","Wear dark clothing.","Walk on the left-hand side of the road.","Wear high-visibility clothing."],"answer":["option_4"],"explanation":"Even with the best headlights, drivers can see less at night than during the day. Pedestrians and unlit bicycles are extremely difficult to see in the dark, particularly if they have to deal with the glare of oncoming lights. Pedestrians should always wear bright and hi-vis clothing during the day and reflective clothing at night when walking outside built-up areas."},{"id":"595","category_id":"4","question":"What is a courtesy pedestrian crossing?","img":"","options":["An uncontrolled pedestrian crossing place.","A pedestrian crossing with flashing amber lights.","A pedestrian crossing on a pedestrian street.","A pedestrian crossing with ‘look right’ painted on the roadway."],"answer":["option_1"],"explanation":"Pedestrians should only enter uncontrolled crossing places (courtesy crossing) ensuring that all traffic is aware of their presence if crossing the road. Motorists entering uncontrolled crossing places (courtesy crossing) should react by driving very slowly, and be aware of the potential dangers of pedestrians using the area."},{"id":"596","category_id":"4","question":"What is the likely effect of motorists ‘rubbernecking’ at the scene of a traffic incident?","img":"","options":["It can cause additional incidents as drivers become distracted.","It allows traffic to change course without attention.","It allows traffic to change speed without attention.","It can increase traffic flow near an incident."],"answer":["option_1"],"explanation":"When approaching or being near to the scene of an incident, motorists are often seen ‘rubbernecking’. This means turning your head and stretching your neck to get a better view of what’s happening. It can be the cause of traffic jams as drivers slow down to ‘rubberneck’. It can also cause road incidents as drivers become distracted and change their speed and/or direction while other drivers are also distracted."},{"id":"597","category_id":"4","question":"How should a driver react to emergency services vehicles with flashing blue lights and/or sirens on?","img":"","options":["Brake suddenly and stop to avoid causing obstruction.","Check their mirrors before looking for space to move aside.","Mount kerb on offside of the road to make room.","Only move aside if it is an ambulance."],"answer":["option_2"],"explanation":"If you see any emergency vehicle approaching with lights and/or sirens activated, check your rear view mirrors to gauge the speed of the emergency vehicle/s and also look out for pedestrians, cyclists, motorcyclists and other road users. Indicate your intention to pull over. Pull over only in a space that has enough space for the emergency vehicle/s to pass safely. Move off safely with appropriate observations and signals after the emergency vehicle has passed."},{"id":"598","category_id":"4","question":"What is the penalty for a vehicle owner who allows a learner driver to drive their vehicle unaccompanied?","img":"","options":["They will incur 2 penalty points on their licence.","They will be fined €2,000.","Their vehicle will be seized.","They will lose their driving licence."],"answer":["option_3"],"explanation":"A learner driver needs to be aware that driving unaccompanied in a vehicle, even where the owner has given their consent to drive, may result in the vehicle being seized."},{"id":"599","category_id":"4","question":"A learner permit driver who receives 7 penalty points in a 36 month period (three years) will be banned from driving for how many months?","img":"","options":["9 months.","6 months.","12 months.","3 months."],"answer":["option_2"],"explanation":"A learner driver needs to be aware that there is a lower penalty point threshold for learner or novice drivers."},{"id":"600","category_id":"4","question":"If the owner of a vehicle allows a learner driver to drive their vehicle, what is the maximum fine the owner could face?","img":"","options":["€1,000.","€500.","€2,000.","€1,500."],"answer":["option_1"],"explanation":"A learner driver needs to be aware that driving unaccompanied in a vehicle which they do not own could see the owner facing a fine of up to €1,000 and having the vehicle seized."},{"id":"601","category_id":"4","question":"Is a learner driver permitted to drive unaccompanied if they have the consent of the vehicle owner?","img":"","options":["Yes, provided the vehicle owner has open drive insurance.","Yes, provided the vehicle owner has given their consent.","Yes, provided the owner is a family member and has given their consent.","No, a learner driver is not permitted to drive unaccompanied even with the owner’s consent."],"answer":["option_4"],"explanation":"A learner driver needs to be aware that, even with the consent of the owner of the vehicle, they are not permitted to drive unaccompanied."},{"id":"602","category_id":"4","question":"For how long is a learner driver’s accompanying driver required to have held their full licence in Category B?","img":"","options":["3 years.","1 year.","2 years.","6 months."],"answer":["option_3"],"explanation":"A learner driver needs to be aware that not just anyone can be an accompanying driver. An accompanying driver has to have held a full licence for at least 2 years and have built up good driving experience."},{"id":"603","category_id":"4","question":"When a learner driver has passed their driving test, are they permitted to drive unaccompanied as the holder of a Certificate of Competency?","img":"","options":["No, a learner driver is not permitted to drive unaccompanied until they have been issued with a full driving licence in that category.","No, a learner driver is not permitted to drive unaccompanied on a Certificate of Competency unless they continue to display L plates.","Yes, a learner driver is permitted to drive unaccompanied on a Certificate of Competency once they have notified their insurance company.","Yes, a learner driver is permitted to drive unaccompanied on a Certificate of Competency once they have N plates displayed."],"answer":["option_1"],"explanation":"A learner driver who successfully passes their driving test needs to be aware that the rules that apply to learner permit holders still apply to them until they are in possession of a full driving licence in that category. A Certificate of Competency is not a full licence."},{"id":"604","category_id":"4","question":"Can a learner driver drive unaccompanied if they are on their third or subsequent learner permit?","img":"","options":["Yes, provided they display N plates on the front and rear of the vehicle.","No, unless they display L plates on the front and rear of the vehicle.","No, they cannot drive unaccompanied on any learner permit.","Yes, but not on motorways."],"answer":["option_3"],"explanation":"A learner driver needs to be aware that they are not permitted under any circumstance to drive unaccompanied regardless of the amount of learner permits held."},{"id":"605","category_id":"4","question":"Can a person who has passed their car driving test within the last two years act as an accompanying driver?","img":"","options":["Yes, as long as they have completed their Essential Driver Training (EDT).","Yes, as long as they have their full licence with them.","No, they must hold the full driving licence for a minimum of 2 years.","No, unless they are a qualified Approved Driving Instructor (ADI)."],"answer":["option_3"],"explanation":"To be an accompanying driver for a learner driver, you must have a full driving licence for at least 2 years."},{"id":"606","category_id":"4","question":"Are there any occasions when a learner driver can drive unaccompanied?","img":"","options":["Yes, when driving to the test centre before the driving test.","Yes, when meeting an Approved Driving Instructor (ADI).","No, learner drivers must be accompanied at all times by a qualified driver.","Yes, after completing a driving test."],"answer":["option_3"],"explanation":"Learner drivers must be aware that they must be accompanied by a qualified driver at all times."},{"id":"607","category_id":"4","question":"What should a driver do in the event of a breakdown or incident in a tunnel?","img":"","options":["Beckon other traffic to overtake.","Reverse the vehicle if necessary to make room for overtaking traffic.","Switch off the engine and switch on the hazard lights.","Signal the vehicle behind to stop and ask the driver to summon help at the other end of the tunnel."],"answer":["option_3"],"explanation":"If your vehicle breaks down or is involved in a collision in a tunnel, switch on your hazard warning lights, switch off your engine, go to an emergency station and use the emergency phone to alert the tunnel operator."},{"id":"608","category_id":"4","question":"Is a driver allowed to sound the horn while driving in a built-up area at night?","img":"","options":["Yes, but only for momentary use.","Yes, but between 11:30 pm and 7:00 am the horn may be sounded only in an emergency.","No, use of the horn is not permitted in a built-up area between 11:30 pm and 7:00 am.","Yes, but only between 11:30 pm and 7:00 am."],"answer":["option_2"],"explanation":"Drivers are not allowed to use the horn in a built-up area between 11:30 pm and 7:00 am unless there is a traffic emergency. Only use a horn to warn other road users of danger or if needed to make them aware of your vehicle’s presence for safety reasons. Using the horn does not give drivers an automatic right of way. Never use the horn to provoke a reaction from or to rebuke another motorist."},{"id":"609","category_id":"4","question":"When driving on this one-way street with vehicles parked on both sides, what should a driver be prepared for?","img":"a_1zkyX.png","options":["Pedestrians crossing between the vehicles.","The truck may be a left-hand drive vehicle.","Oncoming traffic as the driver overtakes the truck."],"answer":["option_1"],"explanation":"When driving on a one-way street, you should be extra careful and be prepared to react to a change in the traffic situation."},{"id":"610","category_id":"4","question":"When driving late at night what should a driver be aware of?","img":"","options":["That there is a danger of themselves or other drivers falling asleep.","That all pedestrians will be wearing high-visibility clothing.","That trucks may drive in the outside lane of a motorway.","That speed limits do not apply between midnight and 6:00 am."],"answer":["option_1"],"explanation":"Driving when tired can be very dangerous and driver fatigue is one of the main causes of serious road collisions. If a driver becomes drowsy while driving, they should stop in a safe place take a caffeine-based drink and take a short nap. After this they should then get some fresh air and stretch their legs for a few minutes before setting off again. The only cure for fatigue is proper sleep. Never ever drive when tired."},{"id":"611","category_id":"4","question":"To whom should a driver report aggressive driving?","img":"","options":["Local Garda station or Traffic Watch.","Transport Infrastructure Ireland.","Health and Safety Authority.","Road Safety Authority."],"answer":["option_1"],"explanation":"Report all aggressive driving incidents to Traffic Watch or a Garda station. They are the best people to deal with aggressive driving."},{"id":"612","category_id":"4","question":"A learner driver who has been stopped by a Garda for driving unaccompanied faces a minimum fine of how much?","img":"","options":["€120","€140","€160"],"answer":["option_3"],"explanation":"A learner driver needs to be aware that if stopped by a Garda for driving unaccompanied it will lead to a financial penalty."},{"id":"613","category_id":"4","question":"What is the fine for a learner driver who drives unaccompanied?","img":"","options":["€160","€120","€140"],"answer":["option_1"],"explanation":"A learner driver needs to know that there are fines for driving unaccompanied."},{"id":"614","category_id":"4","question":"How many penalty points will an unaccompanied learner driver receive on conviction?","img":"","options":["3 penalty points.","4 penalty points.","2 penalty points."],"answer":["option_2"],"explanation":"A learner driver needs to be aware that driving unaccompanied increases the penalty points to 4 on conviction."},{"id":"615","category_id":"4","question":"What should a driver do in this situation?","img":"a_Po7bB.png","options":["Continue ahead while indicating to overtake parked car.","Sound the horn as a warning and proceed.","Reduce speed and be prepared to stop as other children could follow."],"answer":["option_3"],"explanation":"Drivers should always be aware of other road users especially children, who can be unpredictable and show no road sense. Drivers should slow down and take extra care in areas where there are children about – for example, near schools, playgrounds and in residential areas."},{"id":"616","category_id":"4","question":"What should a driver do in this situation?","img":"a_9TQ6E.png","options":["Proceed promptly to clear the crossing.","Sound the horn to alert the pedestrian.","Allow the pedestrian to cross the road."],"answer":["option_3"],"explanation":"When approaching a zebra crossing, you must yield to pedestrians already on or about to cross the road."},{"id":"617","category_id":"4","question":"What should the driver do when driving a vehicle they are not familiar with?","img":"","options":["Initially drive with extra care and at a lower speed until fully familiar with the vehicle.","Drive with hazard lights on until fully familiar with the vehicle.","Drive at a normal speed as all vehicle’s features are the same."],"answer":["option_1"],"explanation":"You should know where to find and how to operate all the controls on your vehicle, including all of its safety features and warning lamps. When you are driving, you need to be able to concentrate on what’s happening around you and operating the vehicle controls should be second nature to you. When you sit into the driver’s seat of a vehicle you are not familiar with, you should do a thorough cockpit drill before you move off."},{"id":"618","category_id":"4","question":"What should a driver do when approaching roadworks warning signs?","img":"","options":["Maintain speed until signalled to slow down by a flagman.","Reduce speed and be prepared to stop for works vehicles or a flagman.","Increase speed and move to the centre of the road."],"answer":["option_2"],"explanation":"A driver should always approach roadworks with caution and reduce speed as there are many possible hazards to deal with – including road workers, works vehicles, uneven road surfaces and temporary traffic controls."},{"id":"619","category_id":"4","question":"What should a driver do when they want to use a mobile phone?","img":"","options":["Reduce speed, show caution, and be alert for other road users.","Pull in and stop in a safe place.","Keep the conversation short.","Allow a wider gap to open up with the vehicle in front and continue at normal speed."],"answer":["option_2"],"explanation":"It is illegal to use or handle a mobile phone while driving. Driving requires all of your attention, all of the time, so you should never use or handle a mobile phone while driving. If you want to use a mobile phone, the only safe thing to do is to find a safe place to stop."},{"id":"620","category_id":"4","question":"Why is tailgating (driving too close behind the vehicle in front) dangerous?","img":"","options":["The vehicle will exceed the speed limit.","The vehicle will not have enough distance to stop safely in an emergency.","The braking system is less efficient in the slipstream of the vehicle in front.","The engine may overheat because of restricted air flow over the vehicle’s engine."],"answer":["option_2"],"explanation":"If you drive too close to the vehicle in front and it brakes suddenly, you will not have enough time to react. For that reason you should always keep a safe distance from the vehicle in front. One way of calculating a safe distance in dry weather is the two-second rule: Allow at least two seconds to elapse between the vehicle in front and your own vehicle passing a fixed point such as a lamp post or sign post."},{"id":"621","category_id":"4","question":"What is the correct action to take in this situation?","img":"a_oEs3A.png","options":["Continue to drive at the same speed.","Keep a close eye on the children and be prepared to brake in good time.","Drive closer to the left-hand side (nearside) and sound the horn."],"answer":["option_2"],"explanation":"Because it is difficult to predict children’s behaviour, you should always be prepared to react to a change in the traffic situation or to stop."},{"id":"622","category_id":"4","question":"When approaching the pedestrian crossing, what should the driver do in this situation?","img":"a_bIJ7c.png","options":["Maintain speed, because the pedestrians have not stepped on to the crossing.","Continue to drive on fast because the pedestrians have to wait.","Slow down in good time and be prepared to stop."],"answer":["option_3"],"explanation":"When there are pedestrians at or near a zebra crossing, you should slow down on approach and be prepared to stop to allow the pedestrians to cross safely."},{"id":"623","category_id":"4","question":"What should the driver do if there are children playing at the edge of the roadway?","img":"a_4vE7m.png","options":["Accelerate and move to the right-hand side of the road to avoid the children.","Give a warning signal and drive past at the same speed.","Reduce speed, drive cautiously and remain ready to brake."],"answer":["option_3"],"explanation":"Because it is difficult to predict children’s behaviour, you should always be prepared to react to a change in the traffic situation and be prepared to stop."},{"id":"624","category_id":"4","question":"Why might it be dangerous to drive on a poorly-lit street?","img":"a_DI85b.png","options":["Pedestrians crossing in a dark area might be difficult to see.","Drivers can only see the traffic coming against them.","Drivers can only see the traffic in front of them."],"answer":["option_1"],"explanation":"When you are driving along a poorly-lit street, you should take extra care – vulnerable road users such as pedestrians might not be so easy to see. You should always be prepared to react to a change in the traffic situation."},{"id":"625","category_id":"4","question":"What should a driver do if dazzled by the lights of an oncoming vehicle?","img":"a_ylGXc.png","options":["Accelerate to get out of range of light as quickly as possible.","Flash the oncoming vehicle and move to the left.","Look to the left-hand edge (nearside) of the roadway and slow down if necessary."],"answer":["option_3"],"explanation":"If you are dazzled by the lights of oncoming traffic, turn your eyes to the left edge (nearside) of the road. If necessary, stop and allow your eyes to recover before driving on."},{"id":"626","category_id":"4","question":"What should a driver do in this situation when intending to turn left?","img":"a_L2OLe.png","options":["Proceed between both pedestrians.","Stop and beckon both pedestrians to cross.","Yield to pedestrians already crossing."],"answer":["option_3"],"explanation":"By law you must yield to pedestrians already crossing at a junction. Pedestrians are vulnerable road users and you should be extra careful driving at places where pedestrians are attempting to cross the road."},{"id":"627","category_id":"4","question":"What should a driver do if they see a truck reversing into a side entrance on the left-hand side of the road ahead?","img":"","options":["Sound the horn to indicate to the driver of the truck to stop.","Try to overtake it so as not to inconvenience traffic behind.","Stop and stay back safely and wait until the way is clear."],"answer":["option_3"],"explanation":"Always read the road ahead and be prepared to react to any traffic situation. You should be aware of the difficulties that drivers of large vehicles can have reversing into a side entrance. In this case, a large vehicle reversing could obstruct your view of the road ahead as you approach, and you should afford the truck driver adequate space to manoeuvre."},{"id":"628","category_id":"4","question":"A driver who is about to undertake a journey is upset or angry. What should they do?","img":"","options":["Drive slower than normal for a distance.","Being upset or angry does not affect driving.","A driver should not drive until they are calm."],"answer":["option_3"],"explanation":"If you drive when you are angry or upset, you are more likely to be involved in a collision, and more likely to react to other drivers bad behaviour. Take the time to calm down and compose yourself before you set out on a journey."},{"id":"629","category_id":"4","question":"What should a driver be aware of when driving through a section of road where roadworks are ongoing?","img":"","options":["That the area will be cleared for the driver so that there are no traffic delays.","That road workers are always aware of the movement of traffic.","Narrower lanes than usual and restricted shoulder areas."],"answer":["option_3"],"explanation":"When travelling through a section of roadworks, a driver needs to be extra careful, as the road surface area may be considerably reduced. It may be narrower, uneven, slippery or there may be loose chippings which may pose a danger for road workers and other road users."},{"id":"630","category_id":"4","question":"When approaching a roundabout, to whom should a driver give way?","img":"","options":["The driver must give way to traffic approaching from the right or already on the roundabout.","The driver approaching the roundabout always has right of way.","The driver must only give way to pedestrians and cyclists on the roundabout."],"answer":["option_1"],"explanation":"Drivers should always approach roundabouts with caution. They should be prepared to give way to traffic on the right, traffic already on the roundabout, pedestrians already crossing and to always stop if necessary."},{"id":"631","category_id":"4","question":"What should a driver do when they see a slow moving vehicle up ahead being driven by a learner driver?","img":"","options":["Maintain a distance behind to avoid undue pressure.","Drive close behind the vehicle to show your intention to overtake.","Overtake the vehicle as quickly as possible."],"answer":["option_1"],"explanation":"Show patience and courtesy when driving behind a learner driver. Learner drivers are not as experienced as other road users and may drive erratically when put under pressure."},{"id":"632","category_id":"4","question":"When stopped at traffic lights, a driver should take particular care for which road users coming up on their left?","img":"","options":["Cars.","Tractors.","Cyclists."],"answer":["option_3"],"explanation":"Before moving off at traffic lights and particularly when turning left you should be aware of cyclists and motorcyclists coming up on the left in general – in particular where there is an advanced stop line for cyclists ahead of that for other road users."},{"id":"633","category_id":"4","question":"What should a driver do to minimise fuel consumption in their vehicle?","img":"","options":["Use gentle acceleration and braking.","Use maximum acceleration between gear changes.","Drive gently in a low gear."],"answer":["option_1"],"explanation":"Driving smoothly will help reduce fuel consumption. Read the road ahead and adjust speed in good time, and avoid harsh acceleration and late braking."},{"id":"634","category_id":"4","question":"What alternatives can drivers take to help protect the environment?","img":"","options":["Use public transport.","Accelerate and brake harshly while driving.","Only use low gears."],"answer":["option_1"],"explanation":"Using public transport helps to protect the environment. Buses, trams and trains are a more environmentally friendly way to move large numbers of people especially in urban areas. Consider using public transport where possible – not only is it more environmentally friendly, but it can also be more cost-effective when you take the cost of fuel and parking charges into account."},{"id":"635","category_id":"4","question":"A driver approaches a pelican crossing with a flashing amber light showing. There is a pedestrian still on the road. What should the driver do?","img":"","options":["Beckon the pedestrian to move along as quickly as possible.","Wait and let the pedestrian cross at their own pace.","Sound the horn as a warning and proceed with care."],"answer":["option_2"],"explanation":"You must yield to pedestrians at a pelican crossing when the amber light is flashing."},{"id":"636","category_id":"4","question":"When can a driver travel in the right-hand lane on a dual carriageway?","img":"","options":["In order to keep a greater distance from the hard shoulder.","When overtaking a vehicle in the left-hand lane.","When following other traffic in the right-hand lane."],"answer":["option_2"],"explanation":"You must normally drive in the left-hand lane of a dual carriageway. You should not use the right-hand lane as a driving lane. You may use the right-hand lane when overtaking or when intending to turn right a short distance ahead."},{"id":"637","category_id":"4","question":"What should a driver do when feeling tired within a short distance from their destination?","img":"","options":["Stop in a safe place and take a break.","Continue their journey as they are near to their destination.","Speed up so they reach their destination sooner."],"answer":["option_1"],"explanation":"Do not be tempted to keep driving when you are tired when you are close to your destination. The driver should stop in a safe place and take a break. Many driver tiredness related collisions occur within a short distance of their destination as the body begins to relax."},{"id":"638","category_id":"4","question":"When should a driver move into an auxiliary lane on a motorway?","img":"","options":["To leave the motorway.","To allow other traffic to overtake.","To overtake slower traffic in other lanes."],"answer":["option_1"],"explanation":"Auxiliary lanes are found on some motorways and are to the left of the main motorway lanes. They link the off-ramp of the road you are leaving with the next available off-ramp or exit. If a driver is already in lane 1 of the motorway and they intend to take the next exit, they should enter the auxiliary lane to do so. The auxiliary lane is normally identified by a broken white line to the right of the lane, with markings that are shorter, closer and wider than the broken white lines normally seen in lane 1, 2 or 3."},{"id":"639","category_id":"4","question":"When overtaking a cyclist what should a driver be aware of?","img":"","options":["The cyclist is only permitted to use the bus lane.","The cyclist is not wearing a safety helmet.","The cyclist may suddenly change direction."],"answer":["option_3"],"explanation":"Cyclists are just as entitled to use the road as other vehicles, and drivers need to pay special attention to them. Cyclists are vulnerable road users and sometimes make sudden movements - for example, to avoid a pothole, some broken glass or other debris on the road. Sufficient clearance should be given when overtaking them to lessen the possible danger."},{"id":"640","category_id":"4","question":"What should a driver ensure when overtaking a cyclist?","img":"","options":["Overtake when the cyclist pulls in and stops.","Overtake only when the cyclist is in a cycle lane.","Overtake giving them plenty of space."],"answer":["option_3"],"explanation":"Cyclists are vulnerable road users. Motorists must give good clearance when overtaking cyclists."},{"id":"641","category_id":"4","question":"Is a driver allowed to exceed the speed limit when overtaking?","img":"","options":["The driver may not exceed the speed limit when overtaking.","The driver may exceed the speed limit briefly in order to complete the manoeuvre.","The driver may exceed the speed limit if the vehicle in front is turning left."],"answer":["option_1"],"explanation":"When overtaking the driver is not permitted to exceed the speed limit."},{"id":"642","category_id":"4","question":"When is a driver allowed to overtake another vehicle on the left?","img":"","options":["When on the motorway in fast moving traffic.","A driver is never allowed to overtake on the left.","When the driver is turning left."],"answer":["option_3"],"explanation":"Drivers must normally overtake on the right however they may overtake on the left when they have signalled that they intend to turn left and it is done in a safe manner relative to the traffic conditions."},{"id":"643","category_id":"4","question":"At traffic lights a driver should take particular care for which road users coming up on the left side (nearside)?","img":"","options":["Motorcyclists.","Trucks.","Cars."],"answer":["option_1"],"explanation":"Before moving off at traffic lights you should be aware of motorcyclists unexpectedly coming up on the left-hand side (nearside)."},{"id":"644","category_id":"4","question":"What should a driver do if their vehicle is forced to stop in a tunnel due to a breakdown or a crash?","img":"","options":["Wait in the vehicle for help to arrive.","Beckon other traffic to overtake.","Call for help from an emergency station."],"answer":["option_3"],"explanation":"If there is a breakdown or crash in a tunnel, stop, switch off the engine, switch on the hazard warning lights, check the radio for instructions and use the emergency phone at the emergency station to call for help, check all electronic signs in the tunnel for information."},{"id":"645","category_id":"4","question":"When may you pass another vehicle on the left-hand side?","img":"","options":["When there is enough space to do so.","When a driver cannot pass on the right-hand side because of oncoming traffic.","A driver must never overtake on the left.","When the vehicle in front is signalling to turn right or in slow moving lanes of traffic."],"answer":["option_4"],"explanation":"Normally you must overtake on the right. There are, however, circumstances where you may overtake on the left – for example, when the vehicle has moved out and signalled to turn right."},{"id":"646","category_id":"4","question":"What should a driver do if there is a large oil spill on the road?","img":"","options":["Maintain normal speed in a lower gear and switch on hazard warning lights.","Reduce speed by gently applying the brakes and switch on the hazard warning lights.","Maintain normal speed and try to drive on the spill with the wheels.","Depress the clutch and brake sharply and switch on the hazard warning lights."],"answer":["option_2"],"explanation":"Where oil is spilt on the road, your tyres will have reduced grip, and you might be at risk of skidding if you brake sharply. If you do come across oil on the road, brake gently and switch on your hazard warning lights for a short period to alert other traffic to the hazard."},{"id":"647","category_id":"4","question":"When should signals (for example, with indicators) be given to other road users?","img":"","options":["When turning, except where road markings indicate your direction.","Clearly and in good time to let other road users know what you intend to do.","Only when it is necessary to warn following traffic."],"answer":["option_2"],"explanation":"Giving signals is a way of telling other road users what you intend to do. So, you should signal properly before moving off, turning right or left, changing lanes, overtaking, slowing down or stopping. Signal clearly and in good time, and keep in mind that giving a signal does not give you the right of way."},{"id":"648","category_id":"4","question":"How does giving a late signal affect other road users?","img":"","options":["They are not affected.","It only affects other road users at roundabouts.","They may not have been given enough time to react.","It only affects other road users at traffic lights."],"answer":["option_3"],"explanation":"Giving signals is a way of telling other road users what you intend to do. So, you should signal properly before moving off, turning right or left, changing lanes, overtaking, slowing down or stopping. Signal clearly and in good time, and keep in mind that giving a signal does not give you the right of way. Late signals may confuse other road users."},{"id":"649","category_id":"4","question":"When driving behind a heavy goods vehicle that is signalling to turn right, what should a driver do?","img":"","options":["Overtake it slowly on the inside by driving partly on the footpath if necessary.","See if the vehicle can complete the turn without stopping, and if not, overtake it yourself.","Stay behind until there is enough space to overtake it on the inside or until it has completed the turn.","Sound the horn and overtake the heavy goods vehicle on the right."],"answer":["option_3"],"explanation":"Heavy goods vehicles need extra space on the road, and when they are turning the overhang of the vehicle may swing out into the path of overtaking or passing traffic. For that reason, it is a good idea to stay back and let the heavy goods vehicle complete its turn unless there is sufficient space to overtake safely."},{"id":"650","category_id":"4","question":"Where are the blind spots that a driver needs to be aware of when towing a loaded trailer?","img":"","options":["Parts of the road ahead which are blocked by other large vehicles.","The area to the side and rear of the vehicle and the trailer that the driver cannot see.","The goods or cargo area on the back of the trailer.","The view to the front hidden by the sun-visor."],"answer":["option_2"],"explanation":"A blind spot is an area that a driver cannot see when looking forward or when looking in the mirrors. You should check your blind spots before changing direction or changing lane. The bigger the vehicle, the bigger the blind spots, and you should keep this in mind if you are driving behind a large vehicle, such as one towing a loaded trailer. In this situation, if you cannot see the towing vehicle’s mirror, then the driver of that vehicle cannot see you."},{"id":"651","category_id":"4","question":"What should a driver do when overtaking parked vehicles in a residential area?","img":"","options":["Keep close to the parked vehicles allowing maximum room for oncoming traffic.","Increase speed to overtake the vehicles as quickly as possible.","Move as far to the right as possible.","Allow enough clearance when passing."],"answer":["option_4"],"explanation":"When you are passing parked vehicles in a residential area, move into a safe overtaking position in good time and leave plenty of clearance between your vehicle and the parked vehicles to increase visibility of small children in the area and in case someone opens their car door in front of you."},{"id":"652","category_id":"4","question":"How should a driver manage a steep hill or humpbacked bridge when the road is slippery?","img":"","options":["Select neutral gear position.","Drive with extreme care.","Press the clutch and brake together.","Press the clutch only."],"answer":["option_2"],"explanation":"Be extra careful when negotiating steep hills or humpbacked bridges in slippery conditions. Slow down gently on the approach, select the appropriate gear for the speed of the vehicle and use gentle steering and acceleration."},{"id":"653","category_id":"4","question":"What should a driver do when they see joggers ahead on the left?","img":"","options":["Indicate and overtake allowing enough clearance.","Sound the horn and flash the lights to warn them of your presence.","Check the mirrors, indicate and overtake, allowing them enough clearance.","Expect them to move in out of the driver’s path."],"answer":["option_3"],"explanation":"People on the road are more vulnerable than vehicles so you should treat them with extra care. If you see people jogging ahead, use the Mirror–Signal–Manoeuvre routine and give plenty of clearance to the joggers when you are overtaking them."},{"id":"654","category_id":"4","question":"What could happen if a driver parks on a footpath?","img":"","options":["The tyres will lose air pressure.","The suspension will be weakened.","Pedestrians could be prevented from passing.","Traffic could be prevented from passing."],"answer":["option_3"],"explanation":"You should never park on a footpath. Pedestrians (including people with young children in pushchairs, prams and also wheelchair users) might have to go onto the road to get around your car, and this could put them in danger."},{"id":"655","category_id":"4","question":"If a driver suspects that their vehicle indicators have not been seen, what should the driver do?","img":"","options":["Use a clear, decisive hand signal as well.","The driver’s position on the road is enough of a signal.","It is unnecessary to give signals provided observation is taken."],"answer":["option_1"],"explanation":"If the driver is concerned that for whatever reason the indicators are not giving an adequate signal, they should use clear decisive hand signals as well to advise other road users of their intention."},{"id":"656","category_id":"4","question":"What should a driver do before starting a journey in poor weather conditions?","img":"","options":["Top up the windscreen washer reservoir with coolant.","Check the weather forecast for the planned route.","Increase tyre pressure to ensure better grip on the road.","Reduce tyre pressure to ensure better grip on the road."],"answer":["option_2"],"explanation":"Driving in adverse weather conditions is more dangerous and more tiring. Drivers should check the weather forecast and weather warnings and other sources for information on the expected conditions on the intended route, and allow extra time to complete the journey."},{"id":"657","category_id":"4","question":"How should a driver manage a steep descent in snow or frosty weather?","img":"","options":["Engage a lower gear early and use gentle braking applications to keep the speed down.","Keep the clutch depressed and use gentle braking.","Engage a higher gear than normal in order to avoid wheel-spin.","Always keep close to the left and use short, sharp brake applications to keep the speed down."],"answer":["option_1"],"explanation":"In snow or ice, a vehicle takes longer to stop. Before starting a steep descent in a large vehicle, the driver should reduce speed and select a lower gear, brake gently and only when needed. If the vehicle is fitted with a manually selectable retarder, engage it before starting the descent."},{"id":"658","category_id":"4","question":"Before driving through a tunnel, what should a driver do?","img":"","options":["Turn on side lights only.","Register at the first tunnel station.","Disengage the Global Positioning System (GPS).","Check that you have enough fuel."],"answer":["option_4"],"explanation":"If your route takes you through a tunnel, you must ensure that your vehicle has enough fuel to safely pass through."},{"id":"659","category_id":"4","question":"When another driver is in a hurry and cuts in front what should a driver do?","img":"","options":["Drive closely behind them so other vehicles cannot do the same.","Be patient and do not react.","Flash the headlights to express their annoyance.","Drive faster to make up for lost time."],"answer":["option_2"],"explanation":"If another driver behaves badly, you should not let it annoy you – show restraint and don’t react. Road rage only increases the risk of a collision."},{"id":"660","category_id":"4","question":"What is the purpose of rumble strips on the sides of a carriageway?","img":"","options":["To alert drivers that their vehicle is veering out of their lane.","To prevent livestock entering the carriageway.","To improve drainage of the carriageway in heavy rain."],"answer":["option_1"],"explanation":"Rumble strips are raised or grooved patterns on the roadway shoulder that provide both an audible warning (rumbling sound) and a physical vibration to alert drivers that they are leaving the driving lane. In addition to warning inattentive drivers, rumble strips help drivers on the road during inclement weather when visibility is poor."},{"id":"661","category_id":"4","question":"What should a driver do if they feel tired before starting a journey?","img":"","options":["Do not start the journey until they are rested.","Open the windows in the vehicle before they start their journey.","Bring a cup of strong coffee to drink in the vehicle during the journey."],"answer":["option_1"],"explanation":"A driver should not drive or begin a journey if they are feeling tired or fatigued. Research has shown that tired drivers are a major road safety risk, both to themselves and to others."},{"id":"662","category_id":"4","question":"What should a driver do if they experience micro-sleep whilst driving?","img":"","options":["Open all vehicle windows to reduce temperature.","Stop in a safe place.","Have a 20 minute sleep when they reach their destination."],"answer":["option_2"],"explanation":"A driver should not drive while tired or fatigued. Research has shown that tired drivers are a major road safety risk, both to themselves and to others. If a driver is tired and fighting sleep, they are likely to experience “micro-sleeps” these episodes can last up to 10 seconds and can be experienced even when eyes are open. During a micro-sleep of even 4 seconds, a vehicle can travel 100 metres (more than the length of a football pitch) without the driver being in control of the vehicle."},{"id":"663","category_id":"4","question":"What should a driver do if they are taking a medication which can make them feel drowsy?","img":"","options":["Continue driving until they begin to feel drowsy.","Only drive during daylight hours.","Do not drive a vehicle."],"answer":["option_3"],"explanation":"It is against the law to drive a vehicle while under the influence of an intoxicant to such an extent as to be incapable of having control of the vehicle. Intoxicants include alcohol or drugs, whether taken separately or together. Drugs include legally prescribed or Over-The-Counter (OTC) medicines."},{"id":"664","category_id":"4","question":"When driving on a road that has a potholed surface and there is an e-scooter ahead, what should a driver do?","img":"","options":["Expect the e-scooter to keep to the left and maintain speed.","Allow extra clearance in case the e-scooter swerves to avoid a pothole.","Maintain course and sound the horn to alert the e-scooter of their approach."],"answer":["option_2"],"explanation":"You should always be aware of how vulnerable e-scooters are. When you are driving on a road with potholes or bad surfaces, give plenty of clearance to the e-scooters when overtaking them. Take into account that they may swerve suddenly to avoid potholes."},{"id":"665","category_id":"4","question":"What procedure should a driver follow when intending to overtake an e-scooter travelling in the same direction up ahead?","img":"","options":["Signal, check mirrors, move out and overtake when safe to do so.","Check mirrors, signal and move out if it is safe to do so.","Signal, move out and check mirrors for following traffic."],"answer":["option_2"],"explanation":"The procedure drivers should follow the mirrors - signal - manoeuvre routine when overtaking. Drivers should overtake only when it is safe to do so. Give extra space to e-scooters when overtaking them, as they may need to move out to avoid a pothole, or they could be blown into your path on windy days."},{"id":"666","category_id":"4","question":"When driving in the dark on an unlit country road, what should a driver be aware of?","img":"","options":["That e-scooter users have space in the margin of the road so that a driver can overtake them without moving out.","That e-scooter users all wear reflective belts, have the correct lighting on their e-scooters and are clearly visible.","That e-scooter users are much more vulnerable on dark roads."],"answer":["option_3"],"explanation":"Drivers should take extra care when driving on dark winter mornings and evenings – vulnerable road users such as cyclists, e-scooters and pedestrians (particularly schoolchildren) might not be so easy to see in low light conditions."},{"id":"667","category_id":"4","question":"When stopped at traffic lights, a driver should take particular care for which road users coming up on their left?","img":"","options":["Cars.","Tractors.","E-scooters."],"answer":["option_3"],"explanation":"Before moving off at traffic lights and particularly when turning left you should be aware of e-scooters coming up from behind."},{"id":"668","category_id":"4","question":"What should a driver do when they intend to make a left-hand turn at a junction where there are cyclists and e-scooter users present?","img":"","options":["Use your mirrors to check for cyclists and e-scooter users on the left before turning.","Signal left, check the right-hand mirror and complete the turn.","Sound the horn so as to warn the other road users of the intention to turn."],"answer":["option_1"],"explanation":"The vehicle does not have a greater right-of-way than any other road user. As a driver you should pay particular attention to vulnerable road users such as e-scooter users, cyclists and motorcyclists and be aware that they are entitled to use the road in safety."},{"id":"669","category_id":"4","question":"When a driver intends to make a left-hand turn at a busy city junction and there are pedestrians, cyclists and e-scooter users present, what should the driver do?","img":"","options":["Keep to the right to make room for cyclists and e-scooter users to pass.","Signal left, watch the right-hand mirror and make the turn when it is clear.","Watch for pedestrians, cyclists and e-scooter users who may try to cross the road in front of the driver’s vehicle."],"answer":["option_3"],"explanation":"When making a left-hand turn on a busy city street, drivers should pay particular attention to vulnerable road users such as pedestrians, cyclists, motorcyclists and e-scooter users who may appear unexpectedly and especially from the left and may not be aware of the vehicle’s intention."},{"id":"670","category_id":"4","question":"In slow-moving city traffic, a driver should occasionally check their blind spots for which road users in particular?","img":"","options":["Cars.","Vans.","E-scooters."],"answer":["option_3"],"explanation":"Drivers should be aware of and check blind spots before moving off and changing direction where appropriate. E-scooters can easily become hidden in a blind spot, and in slow-moving traffic, they might be moving faster than you are."},{"id":"671","category_id":"4","question":"What action should a driver take on approach to the brow of this hill?","img":"a_6uQ6U.png","options":["Reduce speed as possible hazards ahead.","Comply with the road markings.","Maintain normal speed."],"answer":["option_1"],"explanation":"On the approach to the brow of a hill you should be extra careful and be prepared to react to a change in the traffic situation."},{"id":"672","category_id":"4","question":"What should a driver do when driving at night on an unlit road?","img":"","options":["Drive close to the left and switch on front fog lights.","Watch out for unlit e-scooters.","Drive along the centre of the road."],"answer":["option_2"],"explanation":"While driving at night and even with the best headlights, it can be very difficult to see all the hazards that you might come across – for example, unlit e-scooters on the road. At night you should drive at a speed that will enable you to stop safely within the distance you can see to be clear ahead."},{"id":"673","category_id":"4","question":"Which type of road users are particularly vulnerable at junctions?","img":"","options":["Car drivers.","Van drivers.","E-scooter users."],"answer":["option_3"],"explanation":"Cyclists, motorcyclists and e-scooter users are often difficult to see at junctions and may approach faster than you think."},{"id":"674","category_id":"4","question":"What should a driver be aware of when making a left turn into a side road?","img":"","options":["E-scooters may come up on the left (nearside).","E-scooters might come up on the right (offside).","Following traffic must have room to overtake."],"answer":["option_1"],"explanation":"When turning left, drivers should be aware that cyclists, pedestrians and e-scooters may come up on the left (nearside) . Always check to your left (nearside) before you make a left turn."},{"id":"675","category_id":"4","question":"If there is no footpath, where must a pedestrian walk?","img":"","options":["Right-hand side of the road.","1 metre from the edge of the road.","Left-hand side of the road.","There is no regulation."],"answer":["option_1"],"explanation":"Where there is no footpath provided, pedestrians should walk on the right-hand side of the road facing oncoming traffic. Drivers should be aware of the Rules of the Road for pedestrians, drive with caution and be prepared to react to any changes in the traffic situation."},{"id":"676","category_id":"4","question":"When should pedestrians wear reflective clothing at night?","img":"","options":["When in urban areas.","At night, when walking outside built-up areas.","When walking two abreast.","Only when it is raining."],"answer":["option_2"],"explanation":"Outside built-up areas, pedestrians should wear reflective clothing at all times when walking at night. This is particularly important where there is no street lighting and no footpath for pedestrians."},{"id":"677","category_id":"4","question":"As the driver of the car, which conduct is correct?","img":"a_zTgsn.png","options":["A driver must give way to traffic on the left.","A driver must drive on the right-hand side to allow clearance to the motorcyclist.","A driver may proceed with caution.","Slow down and beckon the motorcyclist to cross the road."],"answer":["option_3"],"explanation":"You may proceed, but you should be aware of the presence of the motorcyclist. You should always be prepared to react to a change in the traffic situation – for example, the motorcyclist might not have seen your vehicle."},{"id":"678","category_id":"4","question":"What should the car driver do in this situation?","img":"a_lLMXF.png","options":["The driver must allow the cyclist to proceed.","The driver may turn right before the cyclist.","The driver must allow the motorcyclist to proceed.","The driver must stop and yield right of way to the other road users."],"answer":["option_1"],"explanation":"When you are turning right from a major road to a minor road, you must yield to oncoming traffic, and you should proceed only when it is safe to do so."},{"id":"679","category_id":"4","question":"What should the driver do in this situation?","img":"a_RUTv3.png","options":["The driver must wait for the yellow car to stop.","The driver must yield to the yellow car on the roundabout.","As the driver is entering the roundabout they have right of way.","The driver may proceed onto the roundabout in front of the yellow car."],"answer":["option_2"],"explanation":"When you reach the roundabout, you must give way to traffic approaching from the right – unless signs, road markings or traffic lights tell you otherwise."},{"id":"680","category_id":"4","question":"What should the car driver do in this situation?","img":"a_isUvr.png","options":["The car driver is not allowed to turn right.","The car driver must allow the bus to proceed.","The car driver may proceed first.","The car driver must allow the motorcycle to proceed."],"answer":["option_4"],"explanation":"When you are turning right from a major road to a minor road, you must yield to oncoming traffic. You should proceed only when it is safe to do so."},{"id":"681","category_id":"4","question":"What should the driver do in this situation?","img":"a_zZj1I.png","options":["The driver must allow the red car to proceed.","The driver must stop and allow all other traffic to proceed.","The driver must allow the blue car to proceed.","The driver may turn in front of the other two cars."],"answer":["option_4"],"explanation":"When you are turning right from a major road to a minor road, you must yield to oncoming traffic and only proceed when it is safe to do so. However, the drivers on the minor roads must give way to the traffic on the major road."},{"id":"682","category_id":"4","question":"What should the driver do in this situation?","img":"a_TlpjV.png","options":["The cyclist must proceed first.","The driver must allow the van to cross the junction.","The driver may continue ahead with caution.","The cyclist must allow the other vehicles to proceed."],"answer":["option_3"],"explanation":"On approaching a crossroads you should check the road sign to see which traffic has priority and be prepared for emerging traffic from either side. Vehicles do not have an automatic right of way on the road. The overriding rule is to proceed with caution in all circumstances."},{"id":"683","category_id":"4","question":"What should the driver do in this situation?","img":"a_MBl69.png","options":["The driver must allow the orange car to cross.","The driver must turn left.","The driver is not allowed to turn right.","The driver may turn right."],"answer":["option_4"],"explanation":"You may turn right if there no oncoming traffic but you should also be aware that there might be traffic emerging from the minor roads."},{"id":"684","category_id":"4","question":"What should the driver do in this situation?","img":"a_Nruma.png","options":["The driver must allow the blue truck to proceed.","The driver must allow the red car to proceed.","The driver may proceed first."],"answer":["option_1"],"explanation":"When you are turning right from a major road to a minor road, you must yield to oncoming traffic and proceed only when it is safe to do so. You should also be aware that there might be emerging from the minor road."},{"id":"685","category_id":"4","question":"What should a driver be conscious of in this situation?","img":"a_UYpF6.png","options":["People crossing the street at the rear of the bus.","The bus driver will always signal before moving off.","The bus may start to reverse.","Traffic emerging from the street on the left."],"answer":["option_1"],"explanation":"You should always read the road ahead and be prepared to react to the changing traffic situation. In particular, you should be aware that pedestrians might emerge at the rear of the bus. In this situation you should also look out for pedestrians making their way towards the waiting bus."},{"id":"686","category_id":"4","question":"The driver is following these two vehicles and wishes to overtake - what must the driver consider before overtaking here?","img":"a_BDfkg.png","options":["The driver should overtake both vehicles together.","The driver of the silver car may decide to turn right.","The driver’s field of view is not good enough to allow safe overtaking.","The roadway markings forbid overtaking here."],"answer":["option_3"],"explanation":"You should always make sure that the road ahead is clear so that there is enough distance to allow you to overtake and get back to the correct side of the road without forcing any other road user to alter speed or course. In this case, the brow of the hill is too close to allow a driver to overtake safely."},{"id":"687","category_id":"4","question":"What should a driver be aware of when approaching a vehicle which is attempting to park?","img":"a_yzT7c.png","options":["The vehicle may be parking at an area designated for loading.","The driver may have to stop and assist the driver parking the vehicle.","That there may be a driveway at the point where the vehicle is parking.","That the vehicle being parked may move out without warning."],"answer":["option_4"],"explanation":"When you approach a vehicle that is being parked on the roadway, you should be aware that its driver will probably be concentrating on parking the vehicle and may not be aware of moving out into the road to correct its position."},{"id":"688","category_id":"4","question":"What should the driver of the silver car do before turning left?","img":"a_mgPI9.png","options":["Increase speed to be able to complete the left turn before the cyclist.","Overtake the cyclist on the left and complete the turn.","Allow the cyclist heading straight on to pass.","Sound the horn to alert the cyclist to the car’s presence."],"answer":["option_3"],"explanation":"Do not overtake a cyclist as you approach a junction at which you are turning left. The cyclist might be continuing ahead. Cyclists are vulnerable road users and may be unstable in slow-moving traffic and at junctions. Give them more room."},{"id":"689","category_id":"4","question":"What lights should a driver use in dense fog?","img":"a_Mr5gm.png","options":["Front and rear fog lights along with dipped headlights.","Front and rear fog lights along with side lights.","Front and rear fog lights along with main beam lights.","Front and rear fog lights along with hazard warning lights."],"answer":["option_1"],"explanation":"When driving in dense fog you should switch on your front and rear fog lights along with dipped headlights. You should not drive in fog with main beam headlights on."},{"id":"690","category_id":"4","question":"What should the driver do?","img":"a_n1p5L.png","options":["The driver must stop and yield to all traffic.","The driver should allow the oncoming cyclist to turn first.","The driver should allow the yellow car to proceed.","The driver may turn left first."],"answer":["option_3"],"explanation":"At a cross junction of equal importance the traffic approaching from the right has priority. It is important to understand that the right of way is not an absolute right. You must proceed with caution while showing regard for other road users."},{"id":"691","category_id":"4","question":"What action should the driver take?","img":"a_14Xoi.png","options":["Proceed in front of the bus.","Proceed in front of the cyclist.","Signal the bus to proceed.","Stop at the stop line."],"answer":["option_4"],"explanation":"By law you must stop at a stop line (or at a STOP sign if there is no stop line), and wait for other traffic to clear before proceeding."},{"id":"692","category_id":"4","question":"The driver intends to turn left at this junction - what should the driver do?","img":"a_czrOb.png","options":["Allow the van and cyclist to proceed.","Yield right of way to the van.","Allow the cyclist to continue before turning left.","Turn left in front of the cyclist."],"answer":["option_3"],"explanation":"Do not overtake a cyclist as you approach a junction at which you are turning left. The cyclist might be continuing ahead. Cyclists are vulnerable road users and may be unstable in slow-moving traffic and at junctions. Give them more room."},{"id":"693","category_id":"4","question":"The driver intends to turn right at this junction - what should the driver do?","img":"a_F4WCl.png","options":["Proceed after the motorcycle and bus have passed.","Proceed after the motorcycle only.","Proceed in front of the bus and motorcyclist.","Proceed in front of the bus only."],"answer":["option_1"],"explanation":"When you are turning right at a junction, you should yield to traffic on the major road, and to oncoming traffic at the junction."},{"id":"694","category_id":"4","question":"When intending to turn right as shown, what should the car driver do?","img":"a_87z1w.png","options":["Continue with care as the driver has right of way.","Wait and allow the truck to proceed first.","Wait and allow the oncoming vehicle to pass.","Wait and allow the truck and the oncoming vehicle to proceed first."],"answer":["option_3"],"explanation":"When you are turning right from a main road onto a side road, you must by law give way to oncoming traffic on the main road."},{"id":"695","category_id":"4","question":"What should a driver do when continuing straight ahead in the middle lane?","img":"a_5OxCa.png","options":["Slow down and allow the driver in front to change lanes.","Take any lane as convenient.","Take position in the right-hand lane even if proceeding straight ahead.","Overtake the other vehicles quickly on the right-hand side."],"answer":["option_1"],"explanation":"You should always keep a safe distance from the vehicle in front especially when it is slowing down or stopping."},{"id":"696","category_id":"4","question":"When driving on a cobblestone road why should you take extra care?","img":"a_LcFce.png","options":["The road surface is uneven and road grip varies.","The smoothness of the cobblestones helps to improve grip.","The road surface is particularly even and tyre grip is improved.","The gaps between the stones helps road holding and grip is improved."],"answer":["option_1"],"explanation":"Different road surfaces can affect your vehicle’s grip on the road and its stopping distances. You should be aware of this when driving on different surfaces."},{"id":"697","category_id":"4","question":"When driving on this one-way street with vehicles parked on both sides, what should a driver be prepared for?","img":"a_cmTBd.png","options":["The truck may be a left-hand drive vehicle.","Oncoming traffic as the driver overtakes the truck.","A vehicle door may open on either side of the street."],"answer":["option_3"],"explanation":"When driving on a one-way street, you should be extra careful and should be prepared to react to a change in the traffic situation."},{"id":"698","category_id":"4","question":"When preparing to stop, a driver notices the vehicle behind is towing a trailer. What should the driver do?","img":"","options":["Use the handbrake to slow down and stop.","Stop quickly keeping a close eye on the rear-view mirror.","Speed up temporarily to put distance between their vehicle and the vehicle behind.","Indicate in good time and pull in gradually to allow the vehicle behind extra stopping distance."],"answer":["option_4"],"explanation":"When you are slowing down or stopping, you should be mindful of the type of vehicle that is following you. For example, if the vehicle following you is a large vehicle or one towing a trailer, you should think of indicating a little earlier than normal to allow the following vehicle enough time to react safely."},{"id":"699","category_id":"4","question":"What should a driver do when being overtaken by another vehicle?","img":"","options":["Move to the right.","Continue at the same pace.","Slow down quickly.","Increase speed."],"answer":["option_2"],"explanation":"When you are being overtaken by another vehicle, you should continue at the same pace but be alert in case the overtaking vehicle suddenly pulls back in front you."},{"id":"700","category_id":"4","question":"How does rain affect driving in this situation?","img":"a_UH0RB.png","options":["It increases tyre grip on the road.","It reduces the danger of skidding.","It increases visibility.","It increases the danger of skidding."],"answer":["option_4"],"explanation":"When it is wet, your tyres do not grip the road surface as well as when it is dry, your stopping distance is increased and you are more likely to skid. For these reasons you should slow down during or after rain and keep a greater distance from the vehicle in front."},{"id":"701","category_id":"4","question":"When should a driver use the vehicle’s rear view mirror?","img":"","options":["Before moving off only.","Before reversing only.","Before changing direction.","Before switching on the rear demister."],"answer":["option_3"],"explanation":"You should use your mirrors to stay aware of traffic situations behind and around you. Always check your mirror before you change direction on a road, and before you signal or begin a manoeuvre."},{"id":"702","category_id":"4","question":"What should drivers do if they become drowsy while driving?","img":"","options":["Stop and have a good meal to boost energy levels.","Turn up the heating.","Open a window or turn on the air conditioning to let cool air into the vehicle.","Stop, take a break including a short walk if possible."],"answer":["option_4"],"explanation":"Driving when you are tired can be very dangerous, and tiredness is one of the main causes of serious road collisions. If you become drowsy while driving, stop in a safe place and take a short nap. Then get some fresh air and stretch your legs for a few minutes before setting off again. Taking a caffeine-based drink such as coffee may also help."},{"id":"703","category_id":"4","question":"Which of the following affects the braking distance of a vehicle?","img":"","options":["The use of unleaded fuel.","The brake-pad clearance.","The speed and weight of the vehicle.","The power of the engine."],"answer":["option_3"],"explanation":"The overall stopping distance of your vehicle depends on its speed and weight – faster and heavier vehicles require greater stopping distances."},{"id":"704","category_id":"4","question":"What should a driver do when driving in dense fog?","img":"","options":["Drive along the hard shoulder and watch for the reflective markers.","Drive along the central dividing line and watch for the reflective markings.","Reduce speed and use dipped headlights.","Reduce speed and use full headlights."],"answer":["option_3"],"explanation":"In dense fog you should reduce your speed and use dipped headlights and fog lights (where fitted). Sidelights are not strong enough in fog, and full headlights can reflect off the fog and make it harder to see where you are going."},{"id":"705","category_id":"4","question":"When driving at night the full headlights of a typical car should enable the driver to see for a distance of how many metres?","img":"","options":["50 metres.","150 metres.","100 metres.","200 metres."],"answer":["option_3"],"explanation":"At night in good driving conditions the full headlights of a car will typically let you see 100 metres ahead. So, you should travel at a speed that allows you to stop within that distance."},{"id":"706","category_id":"4","question":"When driving at night the dipped headlights of a typical car should enable the driver to see for a distance of how many metres?","img":"","options":["20 metres.","30 metres.","50 metres.","40 metres."],"answer":["option_2"],"explanation":"When driving at night in good driving conditions the dipped headlights of a car will typically let you see 30 metres ahead. So, you should travel at a speed that allows you to stop in that distance."},{"id":"707","category_id":"4","question":"When driving at night, when must a driver dip the vehicle’s full headlights?","img":"","options":["When driving at less than 50 km/h.","When meeting or driving behind other traffic.","When entering a motorway.","When there is no oncoming traffic."],"answer":["option_2"],"explanation":"When driving at night you should dip your headlights when you meet oncoming vehicles so that you do not dazzle them. And you should also dip your headlights when you are driving behind another vehicle so the driver is not dazzled by your lights in their mirror."},{"id":"708","category_id":"4","question":"When meeting an oncoming vehicle at night, what should a driver do?","img":"","options":["Avoid looking directly at the oncoming vehicle’s lights.","Increase speed to pass the oncoming vehicle.","Focus eyes directly on the steering.","Focus eyes directly on the oncoming vehicle’s lights."],"answer":["option_1"],"explanation":"If you are dazzled by the lights of an oncoming vehicle, look towards the verge until the vehicle has passed and/or slow down and stop if necessary."},{"id":"709","category_id":"4","question":"When wishing to turn right at the end of a one-way street, where should a driver position their vehicle?","img":"","options":["Drive occupying both lanes when approaching the end of the street.","Drive in either lane as there is no oncoming traffic.","Drive as close as is possible to the right-hand side of the road.","Drive as close as possible to the left-hand side of the road."],"answer":["option_3"],"explanation":"When a driver wants to turn right on a one way street, they should check their mirrors, signal right and manoeuvre into the right-hand side when it is safe to do so. Then complete the turn into the appropriate lane of the street they are entering."},{"id":"710","category_id":"4","question":"In what direction should a driver turn when entering a roundabout?","img":"","options":["To the left.","To the right.","To the right when controlled by a traffic light.","To either left or right."],"answer":["option_1"],"explanation":"By law you must enter a roundabout by turning to the left and giving way to traffic already on the roundabout."},{"id":"711","category_id":"4","question":"What should a driver do if their vehicle breaks down or they are involved in a collision in a tunnel?","img":"","options":["Switch off all lights and remain in vehicle until help arrives.","Beckon other traffic to overtake.","Signal all other traffic to stop.","Switch on hazard warning lights and walk to emergency station to call for help."],"answer":["option_4"],"explanation":"If your vehicle breaks down or is involved in a collision in a tunnel, switch on your hazard warning lights, switch off your engine, go to an emergency station and use the emergency phone to alert the tunnel operator."},{"id":"712","category_id":"4","question":"What should a driver do if their vehicle breaks down in a tunnel?","img":"","options":["Wait in the vehicle until help arrives.","Flag down a passing motorist and ask for help.","Walk to the end of the tunnel and call the Gardaí.","Use the emergency telephone to call for help."],"answer":["option_4"],"explanation":"If your vehicle breaks down or is involved in a collision in a tunnel, switch on your hazard warning lights, switch off your engine, go to an emergency station and use the emergency phone to alert the tunnel operator."},{"id":"713","category_id":"4","question":"What should a driver do if their vehicle goes on fire in a tunnel?","img":"","options":["Drive to the nearest fire exit.","Drive to the nearest emergency station.","Leave the vehicle and follow the emergency escape route.","Leave the vehicle and use the fire extinguishers provided in the tunnel to extinguish the fire."],"answer":["option_3"],"explanation":"If your vehicle goes on fire in a tunnel, you should stop the vehicle as soon as possible, evacuate any passengers to a safe place, go to an emergency station and use the emergency phone to alert the tunnel operator."},{"id":"714","category_id":"4","question":"What should a driver do if their vehicle gets a puncture on a motorway?","img":"","options":["Pull in where safe on the hard shoulder and call for assistance.","Stop in the hard shoulder and get a passenger to warn traffic.","Drive on to the next service area and get assistance.","Stop in the traffic lane and switch on the hazard warning lights."],"answer":["option_1"],"explanation":"Don’t try to change a wheel on a motorway, as this could be very dangerous. Drive the car on to the hard shoulder, and when it is safe to do so, get out of the vehicle and move behind the barrier. Call for assistance from a motorway emergency phone or using a mobile phone (call the Gardaí)."},{"id":"715","category_id":"4","question":"When should a driver use hazard warning lights on a motorway?","img":"","options":["When another vehicle is following too closely.","When driving on the hard shoulder.","When the vehicle is towing a trailer.","When the vehicle has broken down."],"answer":["option_4"],"explanation":"If your vehicle breaks down on a motorway, drive it to the hard shoulder and switch on the hazard warning lights to warn following traffic. When it is safe to do so, get out of the vehicle and move behind the barrier. Call for assistance from a motorway emergency phone or using a mobile phone (call the Gardaí)."},{"id":"716","category_id":"4","question":"When a driver is making a left-hand turn, what mirrors should they particularly concentrate on?","img":"","options":["The right exterior mirror.","The interior and left exterior mirror.","The interior mirror.","The interior and right exterior mirror."],"answer":["option_2"],"explanation":"When turning left, drivers should in particular be aware that cyclists and other vehicles may come up on their nearside (left-hand side). For that reason, when checking mirrors, it is particularly important to check both the left exterior and the interior mirror before turning. Drivers must always use the Mirrors–Signal–Mirror–Manoeuvre routine when turning. They should be particularly careful if crossing the path of a bus and/or cycle lane."},{"id":"717","category_id":"4","question":"How can a driver help the environment?","img":"","options":["By braking harshly.","By increasing speed.","By harsh acceleration.","By reducing speed."],"answer":["option_4"],"explanation":"As a driver you can do less damage to the environment if you drive smoothly and avoid harsh acceleration and braking. Vehicles travelling at 110 km/h use up to 30% more fuel than those travelling at 80 km/h. However, you should not drive so slow as to inconvenience other road users."},{"id":"718","category_id":"4","question":"What action should a driver take when they meet a vehicle with flashing blue lights?","img":"","options":["Switch on the vehicle hazard warning lights.","Flash the headlights and drive up onto the footpath on the left.","Flash the headlights and come to an immediate stop.","Move to the left, reduce speed and stop if necessary."],"answer":["option_4"],"explanation":"When a driver notices an emergency vehicle approaching in the distance, they should check their mirror and move to the left to allow the vehicle to pass. On some occasions it may be necessary to stop."},{"id":"719","category_id":"4","question":"What should a driver do if an ambulance is stopped up ahead with its flashing blue lights on?","img":"","options":["Stop and offer assistance.","Move to the centre of the road to stop other vehicles from overtaking.","Reduce speed and prepare to stop if necessary.","Stop immediately to see what is happening."],"answer":["option_3"],"explanation":"When you come upon an emergency vehicle stopped on the road, you should slow down and be prepared to stop. Do not stop to see what is happening as this could be dangerous and you might cause an obstruction to the flow of traffic."},{"id":"720","category_id":"4","question":"When driving on a road with tram lines why should a driver take extra care?","img":"","options":["Driving on the tracks can improve braking.","Driving on the tracks can reduce tyre grip.","Driving on the tracks can improve tyre grip.","Driving on the tracks can improve steering."],"answer":["option_2"],"explanation":"Different road surfaces can affect your vehicle’s grip on the road and its stopping distances. You should be aware of this when driving on different surfaces."},{"id":"721","category_id":"4","question":"In this situation, what should the driver in the right-hand lane of the dual carriageway be aware of?","img":"a_714MI.png","options":["Oncoming traffic.","Increased visibility.","The motorcyclist may perform a U-turn.","Crosswinds may blow the rider into their path."],"answer":["option_4"],"explanation":"When driving in wet and windy conditions, a driver should be aware that these conditions can affect the stability of vulnerable road users such as motorcyclists or cyclists. These road users may be blown into the driver’s path particularly in open and exposed areas."},{"id":"722","category_id":"4","question":"What should a driver do if dazzled by lights at night reflecting in their interior mirror?","img":"","options":["Switch on the rear fog lights.","Switch on hazard lights.","Temporarily adjust the angle of the mirror.","Adjust the mirror to reflect the light back towards the following driver."],"answer":["option_3"],"explanation":"If the lights of following traffic reflecting in your interior mirror are dazzling you, activate the night driving/anti dazzle mode. If the vehicle is not equipped with this feature drivers should temporarily adjust the angle of the interior mirror to relieve the glare and allow them to drive without distraction."},{"id":"723","category_id":"4","question":"What lights should be shown on a parked car, tractor or works vehicle at night on an unlit public road?","img":"","options":["At least one side lamp front and rear on the side nearest the centre of the road.","Tail lights only.","Dipped headlights.","At least one side lamp front and rear on the side nearest the kerb."],"answer":["option_1"],"explanation":"When leaving a vehicle on an unlit public road at night this creates a potential danger for other road users. Drivers should therefore leave side/parking lights on, so that the vehicle can be seen by other road users. Drivers should not leave headlights on when parked as this may cause other road users to become disoriented."},{"id":"724","category_id":"4","question":"When are children allowed to stand with their heads up through an open sun roof?","img":"","options":["When they are aged more than 12 years.","Children are never allowed to do so.","When travelling at speeds below 30 km/h.","When they are wearing eye protection."],"answer":["option_2"],"explanation":"When carrying children in a car or goods vehicle, it is the driver’s responsibility to make sure that they are suitably restrained."},{"id":"725","category_id":"4","question":"When may the holder of a Category W learner permit carry a passenger on a tractor or works vehicle?","img":"","options":["When the passenger holds a full Category M licence and has personal insurance cover.","When there is proper passenger seating and the passenger holds a full Category W licence.","When there is a need for their assistance.","When the passenger has personal insurance cover."],"answer":["option_2"],"explanation":"The holder of a Category W licence may carry a passenger in the vehicle only if: 1. the vehicle is designed to take a passenger, and 2. the passenger has held a full driving licence in Category W for two or more years."},{"id":"726","category_id":"4","question":"When is a driver allowed to carry more passengers in a car than there are seat belts available?","img":"","options":["It is always allowed.","When the driver’s visibility is not interfered with.","When the driver has the appropriate insurance cover.","It is never allowed."],"answer":["option_4"],"explanation":"A driver must make sure that each passenger in the vehicle has a seatbelt. Failure to wear a seatbelt is an offence. It is the driver’s responsibility to ensure that passengers under the age of 17 wear seatbelts. Older passengers are themselves responsible for wearing seatbelts."},{"id":"727","category_id":"4","question":"When is a tractor most likely to overturn?","img":"","options":["When turning sharply.","When reversing slowly.","When driving uphill.","When driving on the flat."],"answer":["option_1"],"explanation":"When you are driving a tractor, you should be aware that tractors are less stable than other vehicles and take extra care when manoeuvring."},{"id":"728","category_id":"4","question":"When driving a tractor and trailer, what should the driver do on entering a roundabout to avoid possible roll-over?","img":"","options":["Drive in a high gear.","Reduce speed.","Engage the parking brake.","Increase speed."],"answer":["option_2"],"explanation":"Drivers should always drive at a speed which is safe. In particular, when changing direction, such as entering a roundabout. If driving a tractor with a trailer, extra care should be taken due to their instability."},{"id":"729","category_id":"4","question":"When is jack-knifing most likely to occur?","img":"","options":["When trying to reduce speed sharply while travelling downhill.","When travelling sideways across a slope.","When travelling uphill.","When the trailer springs are over-greased."],"answer":["option_1"],"explanation":"Towing a trailer or caravan dramatically reduces the stability of the towing vehicle. If a driver brakes sharply or slows down quickly, the trailer may pivot around the tow hitch coupling, causing both vehicles to go off course, and possibly overturn."},{"id":"730","category_id":"4","question":"What could a driver do in order to avoid excessive exhaust pollution from their vehicle?","img":"","options":["Drive a diesel powered vehicle.","Use a fuel additive to increase the fuel octane rating.","Have the vehicle’s air filters changed regularly.","Drive at a higher speed in order to reduce the time spent on the road."],"answer":["option_3"],"explanation":"Drivers should have their vehicle serviced regularly in accordance with the manufacturer’s guidelines. A vehicle with a dirty air filter uses more fuel and creates more exhaust pollution. Air filters should be changed as part of normal servicing. If a vehicle is used in dusty conditions, the air filter may need to be changed more often. More information is available in the vehicle owner’s handbook."},{"id":"731","category_id":"4","question":"In general how regularly should a vehicle be serviced?","img":"","options":["As per the manufacturer’s recommendation.","Every 30,000 kilometres.","Once every year.","Every 30 months."],"answer":["option_1"],"explanation":"Drivers should have their vehicle serviced regularly in accordance with the manufacturer’s guidelines. This helps the vehicle to perform properly, and as a result saves fuel and reduces emissions. In addition, drivers should also carry out their own daily and weekly checks on fluid levels and tyres."},{"id":"732","category_id":"4","question":"What is the purpose of a catalytic converter?","img":"","options":["To reduce harmful exhaust emissions.","To curb exhaust noise levels only on petrol-powered vehicles.","To allow the exhaust system to be reconditioned.","To curb exhaust noise levels only on diesel-powered vehicles."],"answer":["option_1"],"explanation":"Catalytic converters are part of a vehicle’s exhaust system. They help to protect the environment by removing up to 75% of the carbon monoxide, nitrogen oxide and hydrocarbons from the vehicle’s exhaust."},{"id":"733","category_id":"4","question":"What should a driver do before getting out of the vehicle?","img":"","options":["Open the door and exit the vehicle without delay.","Check the interior mirror before opening the door.","Check their side mirror and look behind before opening the door.","Open the door part way and then look behind."],"answer":["option_3"],"explanation":"Before opening any door, check for other road users passing, and in particular look out for pedestrians, cyclists and motorcyclists. Exit the vehicle only when it is safe to do so, and close the door as soon as possible. Where ever possible, passengers should exit on the side nearest the kerb wherever possible."},{"id":"734","category_id":"4","question":"How should a driver secure their vehicle before getting out of it?","img":"","options":["Apply the parking brake, stop the engine and engage a low gear.","Engage a low gear and stop the engine.","Angle the wheels away from the kerb and stop the engine.","Angle the wheels towards the kerb and stop the engine."],"answer":["option_1"],"explanation":"Before leaving your vehicle, apply the handbrake, switch off the engine and engage a low gear. If the vehicle is fitted with automatic transmission, select P (park)."},{"id":"735","category_id":"4","question":"At what point is a vehicle load more likely to shift?","img":"","options":["When reversing.","When braking gently.","When cornering.","When overtaking."],"answer":["option_3"],"explanation":"It is the driver’s responsibility to ensure that the load is properly secured and evenly distributed, so that the vehicle can be properly controlled when changing direction and when braking."},{"id":"736","category_id":"4","question":"What should a driver do if a tyre bursts on the vehicle they are driving?","img":"","options":["Continue at the normal speed and stop at the next garage.","Pull on the handbrake to bring the vehicle to a stop.","Hold the steering wheel firmly and pull in on the side of the road.","Apply the brakes as quickly as possible."],"answer":["option_3"],"explanation":"If a tyre bursts on your vehicle, keep a firm hold of the steering, slow down gradually and stop where it is safe to do so. Switch on the hazard warning lights."},{"id":"737","category_id":"4","question":"What should a driver do if their vehicle gets into a four-wheel sideways skid?","img":"","options":["Turn the steering wheel in the opposite direction to improve tyre grip.","Turn the steering wheel in the same direction as the skid and apply the handbrake.","Turn the steering wheel in the same direction as the skid and ease off the accelerator.","Turn the steering wheel in the opposite direction and apply the handbrake."],"answer":["option_3"],"explanation":"If your vehicle goes into a four-wheel skid, turn the steering wheel in the same direction as the skid and ease off the accelerator. This should help to bring the wheels back into line and allow you to regain control."},{"id":"738","category_id":"4","question":"What should a driver do if their vehicle gets into a front-wheel sideways skid?","img":"","options":["Release the accelerator.","Continue to accelerate.","Apply the handbrake.","Press the footbrake."],"answer":["option_1"],"explanation":"If your vehicle goes into a front-wheel sideways skid, release the accelerator and do not try to steer until the tyres regain some grip on the road."},{"id":"739","category_id":"4","question":"What should a driver do if their vehicle gets into a rear-wheel sideways skid?","img":"","options":["Turn the steering wheel in the same direction as the rear wheels are heading.","Turn the steering wheel in the same direction as the front wheels are heading.","Apply the handbrake to bring the vehicle to a halt.","Apply the footbrake to bring the vehicle to a halt."],"answer":["option_1"],"explanation":"If your vehicle goes into a rear-wheel sideways skid, turn the steering in the direction the rear wheels are heading. This should be done very gradually, as too much steering could cause the vehicle to skid in the opposite direction."},{"id":"740","category_id":"4","question":"How should a driver in a vehicle without anti-lock brakes (ABS) deal with a front-wheel straight-line skid?","img":"","options":["Press in the clutch and release the accelerator.","Press and release the footbrake at rapid intervals.","Turn the steering wheel gently from side to side.","Pull the handbrake and hold the footbrake down."],"answer":["option_2"],"explanation":"If your vehicle does not have ABS and it goes into a straight-line front-wheel skid due to braking, press and release the brake pedal repeatedly and rapidly. This will help to restore tyre grip and enable you to regain control."},{"id":"741","category_id":"4","question":"What should a driver do if they get a tyre blow-out on the road?","img":"","options":["Switch off the engine ignition to bring the vehicle to a halt.","Continue driving until they reach a garage.","Apply the footbrake gently and bring the vehicle to a halt.","Apply the handbrake immediately to bring the vehicle to a halt."],"answer":["option_3"],"explanation":"If a tyre on the vehicle you are driving blows out, slow down gradually and find a safe and suitable place to stop. Switch on your hazard warning lights and change the wheel or call for assistance."},{"id":"742","category_id":"4","question":"What effect could a rear-tyre blow-out have on a vehicle?","img":"","options":["The steering wheel will pull to the right.","The handbrake will automatically come on.","It could cause the wheels to lock and stop rotating.","It could cause the vehicle to sway from side to side."],"answer":["option_4"],"explanation":"If a rear tyre on the vehicle you are driving blows out, the vehicle may sway from side to side, and this will affect its stability. Slow down, pull in where it is safe to do so, and switch on the hazard warning lights. Change the wheel or call for assistance."},{"id":"743","category_id":"4","question":"What action should a driver take if the engine in their vehicle cuts out suddenly when they are driving along?","img":"","options":["Signal and steer the vehicle to the side of the road.","Check the handbrake is fully off.","Engage a lower gear.","Depress the accelerator and then release it."],"answer":["option_1"],"explanation":"If the engine in a vehicle cuts out when driving, it is important to signal and steer to the side of the road, switch on the hazard warning lights to warn other drivers, and contact the relevant breakdown service to get assistance."},{"id":"744","category_id":"4","question":"How would hydraulic power steering be affected if an engine stalled in slow-moving traffic?","img":"","options":["The steering would become heavy and difficult to operate.","The steering would become much lighter and easier to operate.","The steering wheel would automatically lock.","The steering fluid reservoir would lose all its fluid."],"answer":["option_1"],"explanation":"Hydraulic power steering is operated by a pump which is driven by the engine. If the engine stalls, the pump stops working, and the steering becomes heavy and requires much more effort to turn."},{"id":"745","category_id":"4","question":"When driving along, a driver feels that the oncoming car may crash into their vehicle. What should they do?","img":"","options":["Apply the handbrake immediately to help bring the vehicle to a halt.","Sound the horn to attract the attention of the other driver and take evasive action.","Apply the footbrake gently and bring the vehicle to a halt.","Switch off the engine ignition to help bring the vehicle to a halt."],"answer":["option_2"],"explanation":"If there is an oncoming vehicle in your path, take evasive action and sound your horn to alert the other driver. Bring your vehicle to a halt immediately."},{"id":"746","category_id":"4","question":"What should a driver do to avoid having to make an emergency stop?","img":"","options":["Keep a safe distance from the vehicle in front.","Drive with the left foot covering the clutch pedal.","Keep the left hand available to apply the handbrake.","Drive with the left foot covering the brake pedal."],"answer":["option_1"],"explanation":"When driving in traffic, read the road ahead and keep a safe distance from the vehicle in front. Use the two-second rule to determine your safe distance from the vehicle in front."},{"id":"747","category_id":"4","question":"What should a driver do to avoid having to make an emergency stop?","img":"","options":["Drive with the left foot covering the clutch pedal.","Scan the road well ahead.","Keep the left hand available to apply the handbrake.","Drive with the left foot covering the brake pedal."],"answer":["option_2"],"explanation":"When driving in traffic, read the road ahead and keep a safe distance from the vehicle in front. Use the two-second rule to determine your safe distance from the vehicle in front."},{"id":"748","category_id":"4","question":"Which of the following is a possible consequence for a learner driver if they drive after drinking as little as just one unit of alcohol?","img":"","options":["A three month disqualification from driving.","A €90 fine.","A one month disqualification from driving.","A €60 fine."],"answer":["option_1"],"explanation":"The blood alcohol concentrate limit for novice/learner drivers is much lower than that of a driver who has held their full licence for more than two years (not a novice driver). Therefore as little as one unit of alcohol would result in the driver exceeding the lower limit."},{"id":"749","category_id":"4","question":"During what time periods can a driver be tested for drugs at a road side checkpoint?","img":"","options":["Only after an accident.","Anytime of day or night.","Only during night time hours.","Only during daylight hours."],"answer":["option_2"],"explanation":"The law allows for a driver to be tested at any time."},{"id":"750","category_id":"4","question":"What must a driver be prepared for in this situation?","img":"a_pgmzG.png","options":["A child could turn back to collect the ball from the roadway.","The oncoming vehicle may swerve in your direction.","The ball could damage your vehicle.","The ball may burst after you have passed."],"answer":["option_1"],"explanation":"Because it is difficult to predict children’s behaviour, you should always be prepared to react to a change in the traffic situation and be prepared to stop."},{"id":"751","category_id":"4","question":"What should a driver do when travelling behind this vehicle?","img":"a_3YxUz.png","options":["Reduce speed and prepare to stop if necessary.","Overtake the vehicle in front.","Drive as close as possible to the vehicle.","Pass the vehicle slowly by mounting the kerb on the left."],"answer":["option_1"],"explanation":"You should always read the road ahead and be prepared to react to the changing traffic situation as you approach junctions."},{"id":"752","category_id":"4","question":"When approaching a bus up ahead that is signalling to move off from a bus stop, what should a driver do?","img":"","options":["Indicate and try to get past it promptly.","Stop immediately as the bus has the right of way.","Slow down and allow it to move out."],"answer":["option_3"],"explanation":"A driver should allow signalling buses back into the stream of traffic when they are moving out from a stop. Be careful of pedestrians getting on and off buses, particularly of children near schools."},{"id":"753","category_id":"4","question":"What should a driver do if they are behind schedule in reaching a destination at an appointed time?","img":"","options":["Be patient and do not exceed the speed limit so as to arrive safely.","Use hazard warning lights to encourage other road users to let you pass.","Exceed the speed limit if necessary to make up the time."],"answer":["option_1"],"explanation":"You should always drive at a speed that allows you to stop safely within the distance you can see to be clear. Being late for an appointment is no excuse for exceeding speed limits or for driving at an unsafe speed. Arrive alive."},{"id":"754","category_id":"4","question":"What should a driver do when they see plant or machinery crossing the roadway at roadworks up ahead?","img":"","options":["Slow down and prepare to stop.","Leave the carriage way as the road ahead is blocked.","Maintain the same speed along the road."],"answer":["option_1"],"explanation":"When you notice works vehicles ahead, slow down and be prepared to stop for the road works. If machinery is crossing you must stop if directed."},{"id":"755","category_id":"4","question":"What should the driver allow for when following the bus on an icy road?","img":"a_NiEDV.png","options":["Same braking distance as in wet conditions.","A longer braking distance is required.","A shorter braking distance is required."],"answer":["option_2"],"explanation":"When driving in icy conditions, you should always reduce speed and allow a bigger gap to the vehicle in front in order to be able to stop safely if necessary."},{"id":"756","category_id":"4","question":"A driver wants to pull out of a driveway and turn right onto the road. At the same time a cyclist is approaching from the right and a pedestrian wants to cross. Who must wait?","img":"a_2QvDd.png","options":["The pedestrian must wait.","The pedestrian and the cyclist must wait.","The driver must wait."],"answer":["option_3"],"explanation":"By law you must give way to other road users, including pedestrians and cyclists, when you are entering or leaving a driveway."},{"id":"757","category_id":"4","question":"The driver intends to turn right at this junction - what should the driver do?","img":"a_9jkWi.png","options":["Stop in front of the bus.","Stop in front of the motorcycle.","Stop at the line."],"answer":["option_3"],"explanation":"You must stop at the line where a junction is controlled by a STOP sign and stop line. Do not proceed until it is safe to do so."},{"id":"758","category_id":"4","question":"What should a driver be aware of in this situation?","img":"a_hKtnt.png","options":["Only buses may use this road.","There may be a car hidden from view in front of the bus.","The bus may be parked at a terminus."],"answer":["option_2"],"explanation":"On approach to an area with a restricted view you should be extra careful and be prepared to react to a change in the traffic situation."},{"id":"759","category_id":"4","question":"What should the driver do if they are driving and feel tired?","img":"","options":["The driver should drive along the centre of the road and reduce speed.","The driver should stop and take a break.","The driver should drive on the hard shoulder where available."],"answer":["option_2"],"explanation":"Driving when you are tired can be very dangerous, and it may cause you to micro-sleep (or nod off momentarily). At 100 km/h you travel at 28 metres a second, so if you micro-sleep for just 4 seconds you would travel over 100 metres without being in control of the vehicle. Never drive if you are fighting sleep."},{"id":"760","category_id":"4","question":"What should drivers do if they approach road works and there is earth-moving machinery moving about?","img":"","options":["Reduce speed as there may be loose gravel or mud on the road.","Switch on headlights as a warning and carry on as normal.","Stop, turn the vehicle around on the road and find an alternative route."],"answer":["option_1"],"explanation":"Where earth-moving machinery is working, there are likely to be mud and gravel deposits on the road. Also the noise of such machines might make it hard for road workers to hear the approaching traffic. When you come across earth-moving machinery, slow down and proceed with extreme caution."},{"id":"761","category_id":"4","question":"What effect does spilt diesel have on a road?","img":"","options":["It makes the road more slippery.","It improves the vehicle’s braking ability.","It increases tyre noise."],"answer":["option_1"],"explanation":"Diesel spilt on the road can make the road surface extremely slippery, particularly if the road is wet."},{"id":"762","category_id":"4","question":"What should a rider be aware of when crossing road markings such as lines or arrows?","img":"","options":["Tyre grip is reduced.","Steering is improved.","Tyre grip is not affected."],"answer":["option_1"],"explanation":"Riding on just 2 wheels, riders need to be on the constant lookout for irregularities and other problems with the road surface. This can include all road markings."},{"id":"763","category_id":"4","question":"What should a driver do if traffic comes to a halt in a tunnel?","img":"","options":["Select a low gear and keep the engine running.","Switch off the engine.","Switch on front and rear fog lights."],"answer":["option_2"],"explanation":"If traffic comes to a halt in a tunnel, switch off your engine to prevent a build up of fumes in the tunnel. Stay patient and follow the instructions of the tunnel operators."},{"id":"764","category_id":"4","question":"Why is it dangerous to allow children to stand in the space between the front seats of a car?","img":"","options":["They could distract other drivers thus drawing attention away from the road.","They could be thrown backward if the brakes are applied suddenly.","They could be thrown forward if the brakes are applied suddenly."],"answer":["option_3"],"explanation":"When carrying children in a car or goods vehicle, it is the driver’s responsibility to make sure that they are suitably restrained."},{"id":"765","category_id":"4","question":"How should a driver proceed if their view is blocked at a junction?","img":"","options":["Move out slowly onto the road while watching carefully for other traffic.","Sound the horn several times and proceed.","Flash headlights on and off before moving out.","Ask a passer-by for guidance onto the other road."],"answer":["option_1"],"explanation":"At junctions where the view is blocked, move carefully into a position where you can see without interfering with other road users. Then assess the situation before you continue."},{"id":"766","category_id":"4","question":"What should a driver do who wishes to turn a vehicle around on the road?","img":"","options":["Drive onto a footpath if necessary in order to ensure that they have enough room to turn.","It is not allowed to turn a vehicle around on the road in any circumstance.","Drive into somebody’s driveway and reverse back onto the road.","Check ahead and behind for oncoming traffic and turn the vehicle around while still keeping a look out."],"answer":["option_4"],"explanation":"If you want to turn a vehicle around on the road, you must first choose a place where it is safe and legal to do so. Check all around for other road users and do not impede their right of way. Complete the manoeuvre efficiently and safely."},{"id":"767","category_id":"4","question":"What should a driver do to avoid the need for harsh braking?","img":"","options":["Drive with one foot resting on the brake pedal.","Drive with cruise control engaged.","Look ahead and be prepared for what others may do.","Drive with one foot resting on the clutch pedal."],"answer":["option_3"],"explanation":"You should know what speed you’re travelling at and you should always drive at a speed that is appropriate to the conditions you are driving in, and you should be able to stop smoothly and safely within the distance you can see to be clear ahead."},{"id":"768","category_id":"4","question":"Are children allowed to be left unattended in a vehicle?","img":"","options":["Only when there is enough ventilation.","Only when the vehicle is parked in a supervised car park.","Children should never be left unattended in a vehicle."],"answer":["option_3"],"explanation":"Children must not be left unattended in a vehicle, even for a short period of time. Children might interfere with the vehicle’s controls, and would not be able to deal with an emergency situation, such as a fire or electrical malfunction which could result in serious injury or death."},{"id":"769","category_id":"4","question":"When must a driver use a red flag as a marker for a rear load overhang that exceeds one metre?","img":"","options":["Only during the day.","At no time.","At all times.","Only during the night."],"answer":["option_1"],"explanation":"During daylight hours, you must use a red flag to mark any load that is protruding more than one metre. At night, you must use a red light."},{"id":"770","category_id":"4","question":"How should a driver manage a bend when driving a fully loaded vehicle?","img":"","options":["At a slower speed than when empty.","At the same speed as when empty.","By taking the bend more sharply than when empty."],"answer":["option_1"],"explanation":"Driving too fast on the approach to a bend and while driving through it with a fully loaded vehicle can lead to a loss of control. This can be prevented by driving in a safe and sensible manner and by reading the road ahead."},{"id":"771","category_id":"4","question":"When a driver is at a junction where visibility is extremely limited, what should the driver do?","img":"","options":["Move out with extreme care, watching carefully to the left and right.","Sound the horn and quickly proceed.","Move the vehicle out onto the road to enable other drivers to see you."],"answer":["option_1"],"explanation":"Where your view is obstructed at a junction, you should move carefully into a position where you can see, but without interfering with other road users. You should then assess the situation before you continue."},{"id":"772","category_id":"4","question":"On a narrow busy road, what should pedestrians do when walking?","img":"","options":["Walk two abreast.","Walk more than two abreast.","Walk in groups of no more than three.","Walk in single file."],"answer":["option_4"],"explanation":"Pedestrians should walk in single file on busy narrow roads. Drivers should be aware of the Rules of the Road for pedestrians, drive with caution and be prepared to react to any changes in the traffic situation."},{"id":"773","category_id":"4","question":"A driver is automatically disqualified from driving for how long if, on a first offence, they refused to provide a member of An Garda Síochána with a sample of blood, urine or breath?","img":"","options":["4 years.","3 years.","2 years.","1 year."],"answer":["option_1"],"explanation":"It is an offence not to comply with a request from a member of An Garda Síochána to provide to provide a sample of breath, urine or blood."},{"id":"774","category_id":"4","question":"What is the maximum disqualification period imposed in court when the learner driver has a blood alcohol concentration (BAC) level in excess of 80 mg?","img":"","options":["One year.","Six years.","Two years.","Four years."],"answer":["option_2"],"explanation":"Where a learner driver has failed to pay a fixed penalty notice they will be summonsed to court where a judge can apply a disqualification period of between 1-6 years."},{"id":"775","category_id":"4","question":"What advice should a driver give to passengers before opening doors?","img":"","options":["Leave windows slightly open to allow circulation of air.","Make sure that you have proper clothing protection on.","Check all around and open door with caution.","Remove seat belt and exit vehicle immediately."],"answer":["option_3"],"explanation":"Before opening any doors, check for other road users nearby, in particular motorcyclists and pedestrians."},{"id":"776","category_id":"4","question":"How do you make sure your vehicle is parked safely?","img":"","options":["Drive into parking space as quickly as possible.","Park your vehicle opposite another vehicle on a narrow road.","Avoid reversing your vehicle into a space.","Don’t park it where it may endanger other road users."],"answer":["option_4"],"explanation":"When parking make sure you do not interfere with normal traffic flow and that your vehicle does not disturb, block or endanger other road users."},{"id":"777","category_id":"4","question":"What should be considered when reversing out of a parking space?","img":"","options":["Always reverse quickly to get out of space.","Check for pedestrians and vehicles all around.","Check behind using interior rear view mirror only.","Avoid switching on your rear wiper."],"answer":["option_2"],"explanation":"Some car parks are designed for you to park forwards to make it easier to load shopping. In these cases take extra care as you reverse out of the parking space because pedestrians and vehicles may pass behind you."},{"id":"778","category_id":"5","question":"When a driver operates the indicator switch and hears a more rapid clicking noise than normal, what could this mean?","img":"","options":["The hazard warning lights are on.","The voltage regulator is not functioning properly.","The hazard warning light switch is faulty.","An indicator bulb may have blown."],"answer":["option_4"],"explanation":"A rapid clicking noise when you turn on an indicator is usually a sign that one of the indicator bulbs has failed. Drivers are responsible for making sure that their vehicle is roadworthy. This should include a regular check that all lights, reflectors and indicators, are working properly."},{"id":"779","category_id":"5","question":"What does Anti-lock Braking System (ABS) do?","img":"","options":["ABS locks the brakes to prevent skidding during harsh braking.","ABS displays the name of the radio station playing on the car radio.","ABS prevents the wheels from locking under harsh braking conditions.","ABS deploys the airbags during a collision."],"answer":["option_3"],"explanation":"Anti-lock Braking System (ABS) is a type of braking system found in most modern cars. It comes into play automatically when the driver brakes harshly. In the wet it can help prevent the wheels from skidding so that, if necessary, the driver can continue to steer while braking. Be aware that ABS does not reduce the braking distance."},{"id":"780","category_id":"5","question":"If the oil pressure gauge shows little or no pressure, or the warning light comes on, what could the problem be?","img":"","options":["The oil level is too high.","The oil level is too low.","The oil is too cold.","The oil is too thick."],"answer":["option_2"],"explanation":"Drivers should check the oil level in their vehicle regularly, and if it is low, top it up. If it needs to be topped up very often, have the vehicle checked by a competent person to see if there is a problem."},{"id":"781","category_id":"5","question":"What may happen if the vehicle’s engine oil is not changed as required?","img":"","options":["The engine may overheat.","The vehicle’s fuel consumption may increase.","Parts of the engine may suffer increased wear.","The vehicle’s fuel consumption may decrease."],"answer":["option_3"],"explanation":"Engine oil becomes inefficient over time, losing its viscosity and lubricating qualities, and therefore must be changed as required in accordance with the manufacturer’s recommendations. Failure to do so may result in costly and extensive engine damage. The oil change is usually done when the vehicle is being serviced."},{"id":"782","category_id":"5","question":"If a vehicle is driven with low oil pressure, what effect does this have on its engine?","img":"","options":["It increases fuel consumption.","It increases wear and tear on the engine.","It increases fuel efficiency.","It increases exhaust emissions."],"answer":["option_2"],"explanation":"Low oil pressure is usually related to low oil level or to a faulty oil pump. Low engine oil level should be topped up in accordance with the manufacturer’s recommendations. Failure to do so may result in costly and extensive engine damage."},{"id":"783","category_id":"5","question":"What should a driver do before checking the engine oil level on a vehicle?","img":"","options":["Make sure that the vehicle is in a low gear.","Make sure that the engine is switched off and cold.","Make sure that the engine is running.","Make sure that the engine is switched on and hot."],"answer":["option_2"],"explanation":"Drivers need a basic knowledge of the regular checks that should be carried out on their vehicle. Checking the engine oil level is important – do this with the vehicle parked on level ground with the engine switched off and cold for a more accurate reading. Refer to the vehicle handbook for further information and guidance."},{"id":"784","category_id":"5","question":"What is the purpose of engine oil?","img":"","options":["It lubricates the engine.","It lubricates the braking system.","It lubricates the exhaust system.","It lubricates the wheel bearings."],"answer":["option_1"],"explanation":"The purpose of engine oil is to lubricate and cool the moving parts of the engine. Refer to the vehicle handbook for further information and guidance."},{"id":"785","category_id":"5","question":"When is it recommended to use coolant?","img":"","options":["Winter only.","All year round.","In petrol engines only.","Summer only."],"answer":["option_2"],"explanation":"The purpose of coolant is to keep the engine cool during operation. Coolant is usually a mixture of water and anti-freeze – this ensures that the engine is kept cool and that the coolant does not freeze in very cold weather."},{"id":"786","category_id":"5","question":"What happens if the vehicle has a flat battery?","img":"","options":["The battery will leak acid into the engine.","The engine will not start.","The head light bulbs will have to be replaced.","The battery will have to be replaced."],"answer":["option_2"],"explanation":"All motor vehicles have a battery to supply power, primarily to start the engine. If the battery is flat, the driver will not be able to start the engine in the normal way. When the engine is running, it produces its own electricity to recharge the battery and run the various electrical components, including lights, heating, the radio and so on. If the battery is completely dead it will have to be replaced."},{"id":"787","category_id":"5","question":"What is the primary purpose of the battery fitted to a petrol - or diesel - powered motor vehicle?","img":"","options":["To start the engine.","To reduce fuel consumption.","To provide heat to the engine.","To provide braking."],"answer":["option_1"],"explanation":"The primary purpose of the battery is to start the engine. When the engine is running, it produces its own electricity to charge the battery and run the various electrical components, including lights, heating, radio and so on."},{"id":"788","category_id":"5","question":"What effect would a weak battery have on a vehicle’s driving performance?","img":"","options":["It would have no effect.","The headlights would not function.","The fuel would burn less efficiently.","Uphill acceleration would be reduced."],"answer":["option_1"],"explanation":"It might be difficult to start a car with a weak battery, but once the engine is running, it makes no difference. If the battery fails to charge or maintain its full charge seek advice from a competent person."},{"id":"789","category_id":"5","question":"What effect can a worn shock absorber have on a vehicle?","img":"","options":["It can trigger the release of the airbags.","It can increase fuel consumption.","It can cause an electrical short-circuit.","It can cause the vehicle to ‘bounce’ in an unstable manner."],"answer":["option_4"],"explanation":"A worn shock absorber can seriously affect the control of the vehicle especially on uneven surfaces or when cornering and can cause unnecessary wear and tear on tyres. It may increase stopping distance by not keeping the tyres in proper contact with the road under harsh braking."},{"id":"790","category_id":"5","question":"Why should the valve be replaced when having a tubeless tyre fitted?","img":"","options":["To ensure the tyre will remain inflated.","To ensure the wheel remains aligned.","To ensure the wheel nuts remain tight.","To ensure the wheel remains balanced."],"answer":["option_1"],"explanation":"When fitting a new tubeless tyre to a vehicle it is recommended to change the valve. This is because the old valve has been on the wheel since the old tyre was fitted. The old valve may break down, leak or cause air to escape."},{"id":"791","category_id":"5","question":"What effect does low tyre-pressure have on a vehicle?","img":"","options":["The brakes can overheat.","The engine noise increases.","The vehicle accelerates faster.","Braking and cornering are impaired."],"answer":["option_4"],"explanation":"Incorrect tyre pressure adversely affects many of a vehicle’s systems, including suspension, steering and fuel consumption. In particular, under-inflated tyres can affect the vehicle’s braking ability and its effectiveness when cornering. Tyres should always be inflated according to the vehicle manufacturer’s guidelines, information on which can be found in the vehicle handbook."},{"id":"792","category_id":"5","question":"What is an effect of under-inflated tyres on a vehicle?","img":"","options":["Increased wear on the vehicle’s engine.","Impaired braking and steering.","Improved braking and steering.","Improved fuel economy and braking."],"answer":["option_2"],"explanation":"Drivers should check their vehicle’s tyre pressures (including the spare) regularly at least once a week. Under-inflated tyres adversely affect many of a vehicle’s systems, including braking ability, suspension, steering, fuel consumption and premature tyre wear. Tyres should always be inflated according to the vehicle manufacturer’s guidelines, information on which can be found in the vehicle handbook."},{"id":"793","category_id":"5","question":"While driving at higher speeds, what does a continuous vibration in the steering indicate?","img":"","options":["Weight distribution is uneven.","The shock absorbers are worn.","The wheel balance is uneven.","The steering is out of alignment."],"answer":["option_3"],"explanation":"If a driver feels a continuous vibration in the steering, particularly at higher speeds, this could typically indicate that the balance of the vehicle wheels is uneven. This can lead to instability in the handling of the vehicle. If this is the case, have it investigated by a competent person."},{"id":"794","category_id":"5","question":"After changing a wheel on a vehicle, which of the following should be checked after a short distance?","img":"","options":["The tyre tread depth.","The tyre air valve.","The brake pad clearance.","The wheel nut tightness."],"answer":["option_4"],"explanation":"After changing a wheel on a vehicle, check the tightness of the wheel nuts or studs on the replacement wheel after driving a short distance to ensure they are securely fitted. If in doubt seek assistance from a competent person."},{"id":"795","category_id":"5","question":"What can be affected by driving on under-inflated tyres?","img":"","options":["Braking ability.","The exhaust system.","Engine temperature.","Climate control system."],"answer":["option_1"],"explanation":"Under-inflated tyres may adversely affect many of the vehicle’s systems, including its braking ability, suspension, steering and fuel consumption. In particular, under-inflated tyres can affect the vehicle’s braking ability and can result in premature tyre wear. Tyres should always be inflated according to the vehicle manufacturer’s guidelines, information on which can be found in the vehicle handbook."},{"id":"796","category_id":"5","question":"In general, above what gross vehicle weight must a trailer have brakes fitted?","img":"","options":["500 kg","750 kg","850 kg","900 kg"],"answer":["option_2"],"explanation":"Brakes must be fitted to a trailer if its gross vehicle weight exceeds either 750 kg or half the weight of the towing vehicle."},{"id":"797","category_id":"5","question":"If the vehicle’s oil-pressure gauge is reading low or the red oil-pressure warning light comes on, what should a driver do?","img":"","options":["Drive at lower speeds until the oil level is topped up.","Drive to a safe place, stop the vehicle and check the oil level.","Drive in a low gear until the oil level is topped up."],"answer":["option_2"],"explanation":"Oil circulation is essential for the safe running of the vehicle’s engine. If the warning lights or gauges indicate that the oil or the oil-pressure is low, the driver should stop as soon as they can in safe place, check the oil level, and top up if necessary. Continuing to drive may damage the engine. If the problem is not just related to the oil level, have the vehicle checked by a competent person."},{"id":"798","category_id":"5","question":"If driving a vehicle with automatic transmission, what in particular should a driver be aware of?","img":"","options":["That wheel-spin occurs more often.","That engine braking power is reduced.","That the gear box may overheat while being driven in low gear.","That driving on a motorway is not permitted."],"answer":["option_2"],"explanation":"When driving an automatic vehicle, it may not slow at the same rate as a vehicle with a manual gearbox when the driver releases the accelerator. Drivers should be aware of this, as they may need to apply the brake earlier in order to stop where required."},{"id":"799","category_id":"5","question":"What effect does automatic transmission have on engine braking power?","img":"","options":["It transfers the braking ability to the handbrake.","It increases it.","It reduces it.","It transfers the braking ability to all the wheels."],"answer":["option_3"],"explanation":"When driving an automatic vehicle, it may not slow at the same rate as a vehicle with a manual gearbox when the driver releases the accelerator. Drivers should be aware of this, as they may need to apply the brake earlier in order to stop where required."},{"id":"800","category_id":"5","question":"When driving, where should a driver rest their left foot?","img":"","options":["On the floor or foot rest.","On the clutch pedal.","Under the brake pedal.","Under the clutch pedal."],"answer":["option_1"],"explanation":"When driving a driver should rest their left foot on the floor or foot rest but not under the pedals. To do so may cause delayed response time in an emergency. Resting the foot on the pedal may result in coasting, which may inadvertently increase the speed of the vehicle, or clutch mechanism damage."},{"id":"801","category_id":"5","question":"On a motorway, when should a driver use the hazard warning lights?","img":"","options":["When slowing down quickly because of danger ahead.","When driving on the hard shoulder.","When towing another vehicle.","When another vehicle is following too closely."],"answer":["option_1"],"explanation":"Use the hazard warning lights to warn other road users of a danger ahead. For example, if you have to slow down sharply because of a build-up of traffic ahead, you can use the hazard warning lights to warn following vehicles that they need to slow down."},{"id":"802","category_id":"5","question":"What should a driver do if the fuel system becomes air-locked?","img":"","options":["Loosen the fuel pump.","Tighten the injector pipes.","Bleed the air out of the fuel system.","Drain the fuel filter."],"answer":["option_3"],"explanation":"The fuel system can become air-locked if you let the fuel get too low or if there is a leak in the system. You should have the problem corrected before driving. The solution may be as simple as bleeding the fuel system to release the air."},{"id":"803","category_id":"5","question":"Under what circumstances could both cross-ply and radial tyres be fitted to a vehicle?","img":"","options":["When towing a trailer in snow.","When heavy loads are being carried.","When each type is fitted on a different axle.","When driving in slippery road conditions."],"answer":["option_3"],"explanation":"In general, you should fit the same type of tyres all round the vehicle. However if you need to fit a mix of cross-ply and radials, the tyres on any axle should be of the same type."},{"id":"804","category_id":"5","question":"What does the warning light and/or red zone on a fuel gauge mean?","img":"","options":["The level of fuel in the tank is low.","There is a leak in the fuel system.","The incorrect type of fuel is in the tank."],"answer":["option_1"],"explanation":"Many vehicles are fitted with various warning lights and gauges. A red zone or a warning light on a fuel gauge means the vehicle is low in fuel and should be refuelled as soon as possible."},{"id":"805","category_id":"5","question":"What does the speed rating of a tyre indicate?","img":"","options":["The minimum speed for which the tyre is designed.","The maximum speed for which the tyre is designed.","The maximum speed the vehicle can be driven at."],"answer":["option_2"],"explanation":"The speed rating of a tyre is the maximum speed for which the tyre is designed. This relates to the speed capability of the tyre. It does not relate to the speed at which the tyre should or could legally be driven."}];
